struct UserElaboratorArtifactTypecheck;

impl UserElaboratorArtifactTypecheck {
    // Evaluator-artifact construction can run in a singleflight winner;
    // nested Rayon work could starve while sibling workers wait for that winner.
    const EXECUTION: crate::pass::typecheck_core::TypecheckExecution =
        crate::pass::typecheck_core::TypecheckExecution::Sequential;

    fn discharge_deferred<'m>(
        elaborations: &mut Elaborations,
        env: &ModuleEnv<'m>,
    ) -> Result<(), Error> {
        elaborations.discharge_deferred_with_execution(env, Self::EXECUTION)
    }

    fn check_package(
        package: &Package,
        type_interner: std::sync::Arc<crate::pass::typecheck_core::TypeInterner<Lowered>>,
    ) -> Result<CheckedLoweredPackage, Vec<LocatedError>> {
        let normalized = crate::pass::alpha_normalize::normalize_transformed_package(package);
        let typecheck_scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                type_interner,
            );
        check_normalized_package_with_scope_and_execution(
            normalized,
            typecheck_scope,
            Self::EXECUTION,
        )
    }
}

const USER_ELABORATOR_REFLECTION_INFER_MESSAGE: &str =
    "`_` cannot be reflected by a user elaborator; write the type explicitly";

// `TyperPhase` and the `Typer<P>` dispatch trait live in
// `crate::pass::typecheck_core`; the Prime implementation lives in
// `crate::prime::typer`. The Lowered impl below ties this
// binary's `Elaborations` table to the trait -- it must stay here
// because `Elaborations` lives in this module -- and provides the
// `LoweredTyper` shim that wires the trait's two dispatch methods
// to the elaboration-aware `synth_expr` / `check_value_against`
// defined further down in this file.

/// Lowered's `Typer<Lowered>` implementation. A unit struct whose
/// only job is to wire the trait's static dispatch methods through
/// to the existing elaboration-aware functions in this module —
/// `synth_expr` (whose surface elaboration arms are inhabited) and
/// `check_value_against` (with its Lowered-only elaboration cases).
///
/// The shared helpers in `typecheck_core` (`synth_let`, `synth_fn`,
/// `synth_call`, …, as they migrate) call back into the trait via
/// `<P::Typer as Typer<P>>::synth_expr(...)`, so at Lowered the
/// recursion always lands here.
pub struct LoweredTyper;

pub(crate) fn resolved_nominal_type_binder(
    kind: crate::pass::typecheck_core::NominalTypeBinderKind,
    declaring_module_path: &str,
    name: &str,
) -> ResolvedBinder {
    use crate::pass::typecheck_core::NominalTypeBinderKind;

    match kind {
        NominalTypeBinderKind::TypeAlias => ResolvedBinder::TypeAlias {
            module_path: declaring_module_path.to_owned(),
            name: name.to_owned(),
        },
        NominalTypeBinderKind::Newtype => ResolvedBinder::Newtype {
            module_path: declaring_module_path.to_owned(),
            name: name.to_owned(),
        },
        NominalTypeBinderKind::HostType => ResolvedBinder::HostType {
            module_path: declaring_module_path.to_owned(),
            name: name.to_owned(),
        },
    }
}

pub(crate) fn resolved_binder_for_position<'m>(
    kind: crate::pass::typecheck_core::ResolvedBinderKind,
    name: &str,
    parent: Option<&str>,
    qualifier: Option<&str>,
    tcx: &crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
) -> ResolvedBinder {
    use crate::pass::typecheck_core::ResolvedBinderKind as Kind;

    let module_path = tcx.env.module_path.clone();
    let module_key = |module: &crate::ast::Module<Lowered>| {
        crate::pass::typecheck_core::module_path_key(module, None)
    };
    let qualified_owner = |alias: &str| {
        tcx.env
            .qualified_imports
            .get(alias)
            .map(|module| module_key(module))
    };
    let nominal_owner = |visible_name: &str| {
        let segment = PathSegment::new(visible_name.to_owned(), Span::new(0, 0));
        tcx.env
            .nominal_ref_identity(std::slice::from_ref(&segment))
            .map(|(owner, _)| owner)
    };
    match kind {
        Kind::Local => ResolvedBinder::Local {
            name: name.to_owned(),
            decl_span: tcx.value_decl_span(name),
        },
        Kind::TypeParam => ResolvedBinder::TypeParam {
            name: name.to_owned(),
            decl_span: tcx.type_param_decl_span(name),
        },
        Kind::Fn => ResolvedBinder::Fn {
            module_path,
            name: name.to_owned(),
        },
        Kind::CrossModuleFn => ResolvedBinder::Fn {
            module_path: tcx
                .env
                .cross_module_fn_def_modules
                .get(name)
                .map(|module| module_key(module))
                .unwrap_or(module_path),
            name: name.to_owned(),
        },
        Kind::HostEnvFn => ResolvedBinder::HostEnvFn {
            module_path: parent
                .and_then(qualified_owner)
                .or_else(|| {
                    tcx.env
                        .cross_module_env_fn_modules
                        .get(name)
                        .map(|module| module_key(module))
                })
                .unwrap_or(module_path),
            name: name.to_owned(),
        },
        Kind::Intrinsic => ResolvedBinder::Intrinsic {
            name: name.to_owned(),
        },
        Kind::Newtype => ResolvedBinder::Newtype {
            module_path: parent.and_then(qualified_owner).unwrap_or(module_path),
            name: name.to_owned(),
        },
        Kind::CrossModuleNewtype => ResolvedBinder::Newtype {
            module_path: nominal_owner(name).unwrap_or(module_path),
            name: name.to_owned(),
        },
        Kind::NewtypeMember => ResolvedBinder::NewtypeMember {
            module_path: qualifier
                .and_then(qualified_owner)
                .or_else(|| parent.and_then(nominal_owner))
                .unwrap_or(module_path),
            newtype: parent.unwrap_or("").to_owned(),
            member: name.to_owned(),
        },
        Kind::QualifiedImport => ResolvedBinder::QualifiedImport {
            alias: name.to_owned(),
        },
        Kind::QualifiedImportMember => ResolvedBinder::Fn {
            module_path: parent.and_then(qualified_owner).unwrap_or(module_path),
            name: name.to_owned(),
        },
    }
}

impl crate::pass::typecheck_core::Typer<Lowered> for LoweredTyper {
    const RECORD_NOMINAL_TYPE_BINDERS: bool = true;

    // Surface Kio's call rule locally infers omitted universal type
    // arguments from value arguments and the expected return type.
    const ALLOW_ELIDED_UNIVERSAL_CALL_TYPE_ARGS: bool = true;

    // Kio surface accepts the multi-layer flat-call form per
    // `specs/language.md` § 4c — `foo(T1, v1, T2, v2)` against
    // `Forall([A], Function(A, Forall([B], Function(B, Unit))))`
    // walks both curry layers in one application.
    const ALLOW_MULTI_LAYER_FLAT_CALL: bool = true;

    fn synth_expr<'m>(
        e: &'m Expr,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) -> Result<crate::pass::typecheck_core::Synth<Lowered>, Error> {
        let synth = synth_expr(e, tcx)?;
        // Record the synthesized type at the expression's span in the
        // position-keyed index for the LSP's hover, goto-definition,
        // and references queries. The post-elaborator synthesized type is what
        // hover should show, so the recording sits at the dispatch
        // boundary after every `synth_expr` arm has resolved the
        // expression's type (including the elaboration-bearing arms,
        // which set `synth.ty` to the post-elaboration target).
        Self::record_position_type(e.span(), synth.ty.clone(), tcx);
        Ok(synth)
    }

    fn check_value_against_interned<'m>(
        e: &'m Expr,
        expected: &InternedType,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) -> Result<(), Error> {
        check_value_against(e, expected, tcx)
    }

    fn check_user_elaborator_item<'m>(
        elaborator: &'m crate::ast::UserElaboratorDef<Lowered>,
        item_index: usize,
        env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
        elaborations: &mut Elaborations,
    ) -> Result<(), Error> {
        check_user_elaborator_item(elaborator, item_index, env, elaborations)
    }

    fn record_type_resolution<'m>(
        call_site: crate::ast::ExpressionSite,
        slot_index: usize,
        resolved: InternedType,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        tcx.elaborations
            .record_type_resolution(&mp, call_site.id, slot_index, resolved);
    }

    fn mark_value_at_type_slot<'m>(
        call_site: crate::ast::ExpressionSite,
        slot_index: usize,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        tcx.elaborations
            .mark_value_at_type_slot(&mp, call_site.id, slot_index);
        tcx.elaborations
            .position_index
            .record_value_at_type_slot(&mp, call_site.span, slot_index);
    }

    fn record_call_split<'m>(
        call_site: crate::ast::ExpressionSite,
        split_after_slot: usize,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        tcx.elaborations
            .record_call_split(&mp, call_site.id, split_after_slot);
    }

    fn record_call_implicit_unit<'m>(
        call_site: crate::ast::ExpressionSite,
        slot_index: usize,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        tcx.elaborations
            .record_call_implicit_unit_slot(&mp, call_site.id, slot_index);
    }

    fn record_regular_ufcs_elaboration<'m>(
        original: &'m Expr,
        normalized_call: Expr,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        tcx.elaborations
            .record_elaboration(&mp, original, normalized_call);
    }

    fn record_literal_resolution<'m>(
        literal_site: crate::ast::ExpressionSite,
        resolved: InternedType,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        tcx.elaborations
            .record_literal_resolution(&mp, literal_site.id, resolved);
    }

    fn record_fn_param_type<'m>(
        fn_site: crate::ast::ExpressionSite,
        value_param_index: usize,
        resolved: InternedType,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        tcx.elaborations
            .record_fn_param_type(&mp, fn_site.id, value_param_index, resolved);
    }

    fn record_binder_at<'m>(
        segment_span: crate::span::Span,
        kind: crate::pass::typecheck_core::ResolvedBinderKind,
        name: &str,
        parent: Option<&str>,
        qualifier: Option<&str>,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        // The map key identifies the source module containing this written
        // segment. The binder itself carries the resolved declaration owner;
        // imported and qualified paths must use that canonical owner so every
        // syntax surface shares one references/rename identity.
        let mp = tcx.env.module_path.clone();
        let binder = resolved_binder_for_position(kind, name, parent, qualifier, tcx);
        tcx.elaborations
            .record_position_binder(&mp, segment_span, binder);
    }

    fn record_nominal_type_binder_at<'m>(
        segment_span: crate::span::Span,
        kind: crate::pass::typecheck_core::NominalTypeBinderKind,
        declaring_module_path: &str,
        name: &str,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let binder = resolved_nominal_type_binder(kind, declaring_module_path, name);
        let consumer_module = tcx.env.module_path.clone();
        tcx.elaborations
            .record_position_binder(&consumer_module, segment_span, binder);
    }

    fn record_newtype_member_binder_at<'m>(
        segment_span: crate::span::Span,
        declaring_module_path: &str,
        newtype: &str,
        member: &str,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let consumer_module = tcx.env.module_path.clone();
        tcx.elaborations.record_position_binder(
            &consumer_module,
            segment_span,
            ResolvedBinder::NewtypeMember {
                module_path: declaring_module_path.to_owned(),
                newtype: newtype.to_owned(),
                member: member.to_owned(),
            },
        );
    }

    fn record_binder_decl_at<'m>(
        decl_span: crate::span::Span,
        kind: crate::pass::typecheck_core::ResolvedBinderKind,
        name: &str,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        tcx.attach_decl_span_to_local(name, decl_span);
        let mp = tcx.env.module_path.clone();
        let binder = match kind {
            crate::pass::typecheck_core::ResolvedBinderKind::Local => ResolvedBinder::Local {
                name: name.to_owned(),
                decl_span: Some(decl_span),
            },
            crate::pass::typecheck_core::ResolvedBinderKind::TypeParam => {
                ResolvedBinder::TypeParam {
                    name: name.to_owned(),
                    decl_span: Some(decl_span),
                }
            }
            _ => unreachable!("only local and type-parameter binders have lexical declarations"),
        };
        tcx.elaborations
            .record_local_decl(&mp, name, decl_span, binder);
        if let Some(ty) = tcx.locals.iter().rev().find_map(|local| match local {
            crate::pass::typecheck_core::Local::Value {
                name: bound_name,
                ty,
                decl_span: Some(span),
                ..
            } if bound_name == name && *span == decl_span => Some(ty.clone()),
            _ => None,
        }) {
            // Keep the bound type at its declaration; a use can be adapted
            // or instantiated without changing the value available in scope.
            Self::record_position_type(decl_span, ty, tcx);
        }
    }

    fn record_position_type<'m>(
        expr_span: crate::span::Span,
        resolved: InternedType,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        let binders = tcx.in_scope_type_param_presentation();
        tcx.elaborations
            .record_position_type(&mp, expr_span, resolved, binders);
    }

    fn record_inlay_let_type<'m>(
        name_span: crate::span::Span,
        name: &str,
        resolved: Type,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        if name == "_" {
            return;
        }
        let mp = tcx.env.module_path.clone();
        tcx.elaborations.record_inlay_let_type(
            &mp,
            name_span,
            resolved,
            tcx.in_scope_type_param_presentation(),
        );
    }

    fn record_inlay_type_args<'m>(
        call_site: crate::ast::ExpressionSite,
        callee_span: crate::span::Span,
        slot_offset: usize,
        resolved: Vec<Type>,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        if resolved.is_empty() {
            return;
        }
        let mp = tcx.env.module_path.clone();
        let callee_end = crate::span::Span::new(callee_span.end, callee_span.end);
        tcx.elaborations.record_inlay_type_args(
            &mp,
            call_site,
            callee_end,
            slot_offset,
            resolved,
            tcx.in_scope_type_param_presentation(),
        );
    }

    fn discharge_module_deferrals(
        env: &crate::pass::typecheck_core::ModuleEnv<'_, Lowered>,
        elaborations: &mut Elaborations,
    ) -> Result<(), Error> {
        elaborations.discharge_deferred(env)
    }
}

fn refl_type(name: &str, span: Span) -> Type {
    ty_path(name, span)
}

fn checked_term_type(span: Span) -> Type {
    refl_type("__Checked_term__", span)
}

fn comptime_proof_type(span: Span) -> Type {
    refl_type("__Comptime__", span)
}

fn fill_ctx_type(span: Span) -> Type {
    refl_type("__Fill_ctx__", span)
}

fn optional_type_slot_type(span: Span) -> Type {
    ty_sum(
        refl_type("__Type__", span),
        Type::Unit {
            meta: Meta::new(span),
        },
        span,
    )
}

#[derive(Clone)]
enum UserElaboratorSignatureSlot {
    Type {
        param: TypeParam,
    },
    Value {
        ty: InternedType,
        layer: usize,
        expanded_start: usize,
        expanded_width: usize,
    },
}

#[derive(Clone)]
struct UserElaboratorSignatureLayout {
    slots: Vec<UserElaboratorSignatureSlot>,
    layers: Vec<UserElaboratorSignatureLayer>,
    result_ty: InternedType,
}

#[derive(Clone)]
struct UserElaboratorSignatureLayer {
    type_params: Vec<TypeParam>,
    value_param: Option<InternedType>,
    value_abi_arity: usize,
}

/// Goal-free output of the ordinary application frontier.  The source index
/// is stable across successive callable layers; `expanded_*` describes the
/// semantic right-spine slots occupied by the one source expression.
pub(crate) struct TypedUserElaboratorCall {
    pub(crate) layers: Vec<TypedUserElaboratorCallLayer>,
    pub(crate) result_ty: Option<InternedType>,
}

pub(crate) struct TypedUserElaboratorCallLayer {
    pub(crate) type_slots: Vec<TypedUserElaboratorTypeSlot>,
    pub(crate) sources: Vec<TypedUserElaboratorCallSource>,
    pub(crate) value_layer_consumed: bool,
}

pub(crate) struct TypedUserElaboratorTypeSlot {
    pub(crate) resolved: Option<InternedType>,
    pub(crate) occurrence: Option<InternedType>,
}

pub(crate) struct TypedUserElaboratorCallSource {
    pub(crate) source_index: usize,
    pub(crate) source: Expr,
    pub(crate) expanded_start: usize,
    pub(crate) expanded_width: usize,
    pub(crate) expected: InternedType,
}

/// Definition-side facts for one user-elaborator call before the shared
/// application frontier closes its type slots.  Reflection and evaluator work
/// deliberately stay out of this state: the consuming `into_ready` transition
/// is the only point at which goal-free types become ABI values.
pub(crate) struct PreparedUserElaboratorAction<'m> {
    node_id: NodeId,
    name: String,
    elaborator: &'m crate::ast::UserElaboratorDef<Lowered>,
    elaborator_module: Option<&'m Module>,
    call_ty: InternedType,
    args: Vec<CallArgRef<'m, Lowered>>,
    layout: UserElaboratorSignatureLayout,
    type_slot_modes: Vec<UserElaboratorTypeSlotMode>,
    span: Span,
}

pub(crate) enum ProjectedUserElaboratorSlot {
    Type {
        layer: usize,
        slot: usize,
        result_focus: bool,
        residual: Option<ProjectedResidualTypeInput>,
    },
    Value {
        layer: usize,
        expanded_start: usize,
        expanded_width: usize,
        implicit_unit: bool,
        residual: Option<ProjectedResidualValueInput>,
    },
}

pub(crate) struct ProjectedResidualTypeInput {
    pub(crate) ty: InternedType,
    pub(crate) lexical_binders: Vec<TypeParam>,
}

pub(crate) struct ProjectedResidualValueInput {
    pub(crate) name: String,
    pub(crate) ty: InternedType,
    pub(crate) lexical_binders: Vec<TypeParam>,
}

pub(crate) struct ProjectedUserElaboratorCallShape {
    pub(crate) layers: Vec<ProjectedUserElaboratorCallLayerShape>,
    pub(crate) observed_types: Vec<InternedType>,
}

pub(crate) struct ProjectedUserElaboratorCallLayerShape {
    pub(crate) type_slots: Vec<Option<InternedType>>,
    pub(crate) value_layer_consumed: bool,
    pub(crate) expanded_value_slots: usize,
    pub(crate) has_value_sources: bool,
}

#[derive(Clone)]
pub(crate) struct FrozenProjectedResidualAbi {
    generated_type_params: Vec<Option<TypeParam>>,
    bound_value_names: Vec<Option<String>>,
}

impl FrozenProjectedResidualAbi {
    fn has_residual_abstraction(&self) -> bool {
        self.generated_type_params.iter().any(Option::is_some)
            || self.bound_value_names.iter().any(Option::is_some)
    }
}

pub(crate) struct ProjectedUserElaboratorAbiPlan {
    pub(crate) slots: Vec<ProjectedUserElaboratorSlot>,
    pub(crate) frozen_residual: FrozenProjectedResidualAbi,
    pub(crate) terminal_result: ProjectedResidualTypeInput,
}

impl<'m> PreparedUserElaboratorAction<'m> {
    fn validate_trailing_call(
        &self,
        call: &TypedUserElaboratorCall,
        tcx: &TypeCtx<'_, '_>,
    ) -> Result<(), Error> {
        let blocks = &self.elaborator.trailing_blocks;
        if blocks.is_empty() {
            return Ok(());
        }
        let error = |span, message: &str| {
            trailing_block_declaration_error(
                span,
                message,
                self.elaborator,
                self.elaborator_module,
                tcx,
            )
        };
        for (index, declared) in self.layout.layers.iter().enumerate() {
            let Some(selected) = call.layers.get(index) else {
                return Err(error(
                    self.span,
                    "a trailing-block call must supply every public value input",
                ));
            };
            if (declared.value_param.is_some() && !selected.value_layer_consumed)
                || selected.type_slots.len() != declared.type_params.len()
            {
                return Err(error(
                    self.span,
                    "a trailing-block call cannot retain unsupplied public inputs",
                ));
            }
        }
        let mut sources: Vec<_> = call
            .layers
            .iter()
            .flat_map(|layer| &layer.sources)
            .collect();
        sources.sort_by_key(|source| source.source_index);
        let first = sources.len().checked_sub(blocks.len()).ok_or_else(|| {
            error(
                self.span,
                "each declared trailing block requires one value source",
            )
        })?;
        for (source, descriptor) in sources[first..].iter().zip(blocks) {
            let valid = match descriptor.exposure {
                crate::ast::BlockExposure::Product => true,
                crate::ast::BlockExposure::Thunk => {
                    let (ty, _) = crate::pass::typecheck_core::canonicalize_deep_for_comparison(
                        source.expected.as_type(),
                        &tcx.env.alias_ctx(),
                        source.expected.identity_is_canonical(),
                    );
                    matches!(ty, Type::Function { param, .. } if matches!(*param, Type::Unit { .. }))
                }
                crate::ast::BlockExposure::Sequence => {
                    sequence_slot_type(&source.expected, &tcx.env.alias_ctx())
                }
            };
            if !valid {
                return Err(error(
                    source.source.span(),
                    match descriptor.exposure {
                        crate::ast::BlockExposure::Thunk => {
                            "a thunk block requires an ordinary `. -> R` value slot"
                        }
                        crate::ast::BlockExposure::Sequence => {
                            "a sequence block requires an ordinary `Bind(F) -> F(R)` value slot"
                        }
                        crate::ast::BlockExposure::Product => unreachable!(),
                    },
                ));
            }
        }
        Ok(())
    }

    pub(crate) fn node_id(&self) -> NodeId {
        self.node_id
    }

    pub(crate) fn span(&self) -> Span {
        self.span
    }

    pub(crate) fn call_ty(&self) -> &InternedType {
        &self.call_ty
    }

    pub(crate) fn args(&self) -> &[CallArgRef<'m, Lowered>] {
        &self.args
    }

    pub(crate) fn schedule(&self) -> crate::ast::ElaboratorSchedule {
        self.elaborator.schedule
    }

    pub(crate) fn terminal_type_only_layer(&self) -> Option<(usize, &[TypeParam])> {
        let terminal = self.layout.layers.last()?;
        if terminal.value_param.is_some() || terminal.type_params.is_empty() {
            return None;
        }
        Some((self.layout.layers.len() - 1, &terminal.type_params))
    }

    pub(crate) fn type_slot_is_optional(&self, layer: usize, slot: usize) -> bool {
        let preceding_slots = self
            .layout
            .layers
            .iter()
            .take(layer)
            .map(|layer| layer.type_params.len())
            .sum::<usize>();
        assert!(
            slot < self.layout.layers[layer].type_params.len(),
            "an elaborator transcript type slot exceeded its declaration layer"
        );
        matches!(
            self.type_slot_modes[preceding_slots + slot],
            UserElaboratorTypeSlotMode::Optional
        )
    }

    pub(crate) fn type_slot_param(&self, layer: usize, slot: usize) -> &TypeParam {
        &self.layout.layers[layer].type_params[slot]
    }

    pub(crate) fn value_layer_forces_unrequested_source(&self, layer: usize) -> bool {
        self.layout.layers[layer].value_abi_arity == 0
    }

    pub(crate) fn projected_abi_plan(
        &self,
        call: &ProjectedUserElaboratorCallShape,
        tcx: &TypeCtx<'_, '_>,
    ) -> ProjectedUserElaboratorAbiPlan {
        let mut slots = Vec::with_capacity(self.layout.slots.len());
        let mut substitutions = HashMap::new();
        let mut lexical_binders = Vec::new();
        let mut reserved =
            generated_elaborator_type_names_projected(&self.layout, &call.observed_types, tcx);
        let type_count = self
            .layout
            .layers
            .iter()
            .map(|layer| layer.type_params.len())
            .sum();
        let value_count = self
            .layout
            .slots
            .iter()
            .filter(|slot| matches!(slot, UserElaboratorSignatureSlot::Value { .. }))
            .count();
        let mut generated_type_params = Vec::with_capacity(type_count);
        let mut bound_value_names = Vec::with_capacity(value_count);
        let mut value_index = 0usize;
        for (layer_index, layer) in self.layout.layers.iter().enumerate() {
            let call_layer = call.layers.get(layer_index);
            let consumed_type_slots = call_layer.map_or(0, |layer| layer.type_slots.len());
            for (layer_slot, param) in layer.type_params.iter().enumerate() {
                let shadowed = self.layout.layers.iter().enumerate().skip(layer_index).any(
                    |(index, later)| {
                        let later = if index == layer_index {
                            &later.type_params[layer_slot + 1..]
                        } else {
                            &later.type_params
                        };
                        later.iter().any(|later| later.name == param.name)
                    },
                );
                let residual = if layer_slot < consumed_type_slots {
                    let resolved = call_layer
                        .and_then(|layer| layer.type_slots[layer_slot].as_ref())
                        .unwrap_or_else(|| {
                            unreachable!(
                                "a fills projected type slot was absent at action readiness"
                            )
                        });
                    substitutions.insert(param.name.clone(), resolved.clone_type());
                    generated_type_params.push(None);
                    None
                } else {
                    let generated = generated_elaborator_type_param(param, &mut reserved);
                    let generated_ty = InternedType::fresh_canonical(Type::Path {
                        segments: vec![PathSegment::new(generated.name.clone(), self.span)],
                        args: Vec::new(),
                        meta: Meta::new(self.span),
                    });
                    substitutions.insert(param.name.clone(), generated_ty.clone_type());
                    lexical_binders.push(generated.clone());
                    generated_type_params.push(Some(generated));
                    Some(ProjectedResidualTypeInput {
                        ty: generated_ty,
                        lexical_binders: lexical_binders.clone(),
                    })
                };
                slots.push(ProjectedUserElaboratorSlot::Type {
                    layer: layer_index,
                    slot: layer_slot,
                    result_focus: !shadowed
                        && type_mentions_free_param(self.layout.result_ty.as_type(), &param.name),
                    residual,
                });
            }
            let final_value_slot = self.layout.slots.iter().rposition(
                |slot| matches!(slot, UserElaboratorSignatureSlot::Value { layer, .. } if *layer == layer_index),
            );
            slots.extend(
                self.layout
                    .slots
                    .iter()
                    .enumerate()
                    .filter_map(|(slot_index, slot)| match slot {
                        UserElaboratorSignatureSlot::Value {
                            ty,
                            layer,
                            expanded_start,
                            expanded_width,
                        } if *layer == layer_index => {
                            let consumed =
                                call_layer.is_some_and(|layer| layer.value_layer_consumed);
                            let (ty, expanded_start, expanded_width) =
                                projected_user_elaborator_value_slot(
                                    ty,
                                    &substitutions,
                                    *expanded_start,
                                    *expanded_width,
                                    (consumed && Some(slot_index) == final_value_slot).then(|| {
                                        call_layer
                                            .expect("a consumed projected layer has a call shape")
                                            .expanded_value_slots
                                    }),
                                );
                            let implicit_unit = consumed
                                && call_layer.is_some_and(|layer| {
                                    !layer.has_value_sources && layer.expanded_value_slots == 1
                                })
                                && matches!(
                                    crate::pass::typecheck_core::canonicalize_for_comparison(
                                        ty.as_type(),
                                        &tcx.env.alias_ctx(),
                                        ty.identity_is_canonical(),
                                    )
                                    .0,
                                    Type::Unit { .. }
                                );
                            let residual = (!consumed).then(|| {
                                let name = format!("__ct_elab_value{layer_index}_i{value_index}__");
                                ProjectedResidualValueInput {
                                    name,
                                    ty: ty.clone(),
                                    lexical_binders: lexical_binders.clone(),
                                }
                            });
                            bound_value_names
                                .push(residual.as_ref().map(|residual| residual.name.clone()));
                            value_index += 1;
                            Some(ProjectedUserElaboratorSlot::Value {
                                layer: *layer,
                                expanded_start,
                                expanded_width,
                                implicit_unit,
                                residual,
                            })
                        }
                        UserElaboratorSignatureSlot::Type { .. }
                        | UserElaboratorSignatureSlot::Value { .. } => None,
                    }),
            );
        }
        assert_eq!(slots.len(), self.layout.slots.len());
        assert_eq!(generated_type_params.len(), type_count);
        assert_eq!(bound_value_names.len(), value_count);
        let terminal_result = ProjectedResidualTypeInput {
            ty: InternedType::fresh_with_identity(
                subst_type(self.layout.result_ty.as_type(), &substitutions),
                self.layout.result_ty.identity_is_canonical(),
            ),
            lexical_binders,
        };
        ProjectedUserElaboratorAbiPlan {
            slots,
            frozen_residual: FrozenProjectedResidualAbi {
                generated_type_params,
                bound_value_names,
            },
            terminal_result,
        }
    }

    /// Whether this private ABI slot may be absent when an already-selected
    /// public call becomes an executable action. This is an action-readiness
    /// fact only; the shared call planner never consults it.
    pub(crate) fn optional_type_slot_can_be_absent(&self, layer: usize, slot: usize) -> bool {
        self.type_slot_is_optional(layer, slot)
            && type_slot_occurs_only_in_result(&self.layout, layer, slot)
    }

    pub(crate) fn into_ready(
        self,
        typed: TypedUserElaboratorCall,
        tcx: &mut TypeCtx<'m, '_>,
    ) -> Result<ReadyUserElaboratorAction, Error> {
        let captures = resolve_user_elaborator_captures_for_call(
            self.elaborator,
            tcx,
            self.elaborator_module,
        )?;
        self.into_ready_with_captures(typed, captures, None, tcx)
    }

    fn into_ready_with_captures(
        self,
        typed: TypedUserElaboratorCall,
        captures: ResolvedUserElaboratorCaptures,
        frozen_residual: Option<&FrozenProjectedResidualAbi>,
        tcx: &mut TypeCtx<'m, '_>,
    ) -> Result<ReadyUserElaboratorAction, Error> {
        self.validate_trailing_call(&typed, tcx)?;
        let completed = complete_user_elaborator_abi(
            &self.layout,
            &self.type_slot_modes,
            &typed,
            frozen_residual,
            tcx,
            self.span,
        )?;
        let mut abi_inputs = vec![UserElaboratorTemplateInput::ComptimeProof];
        abi_inputs.extend(captures.inputs);
        abi_inputs.extend(completed.inputs);
        let mut input_keys = user_elaborator_input_keys(&abi_inputs);
        if let Some(result_ty) = &typed.result_ty {
            input_keys.push(UserElaboratorTemplateInputKey::ResidualShape(
                crate::ast::convert_type::<Lowered, UncheckedPrime>(result_ty.as_type()),
            ));
        }
        Ok(ReadyUserElaboratorAction {
            schedule: self.elaborator.schedule,
            node_id: self.node_id,
            name: self.name,
            elaborator_module_path: self.elaborator_module.map(module_path_string),
            values: completed.values,
            abi_inputs,
            input_keys,
            capture_imports: captures.imports,
            value_adapter: completed.value_adapter,
            residual_abstraction: completed.residual_abstraction,
            ambient_type_names: completed.ambient_type_names,
            terminal_result_ty: completed.terminal_result_ty,
            span: self.span,
        })
    }

    pub(crate) fn into_projected_ready(
        self,
        declared_inputs: Vec<crate::normalization::Value>,
        frozen_residual: FrozenProjectedResidualAbi,
        proof: crate::pass::typecheck_core::apply::fills::MarkedComptimeProof,
        fills: crate::pass::typecheck_core::apply::fills::FillContext,
        tcx: &mut TypeCtx<'m, '_>,
    ) -> Result<ReadyProjectedUserElaboratorAction<'m>, Error> {
        assert_eq!(
            self.elaborator.schedule,
            crate::ast::ElaboratorSchedule::Fills
        );
        assert!(fills.matches_proof(&proof));
        assert_eq!(declared_inputs.len(), self.layout.slots.len());
        for (slot, value) in self.layout.slots.iter().zip(&declared_inputs) {
            match slot {
                UserElaboratorSignatureSlot::Type { .. } => {
                    let projected = crate::normalization::projected_value_from_value(value)
                        .expect("a projected elaborator type slot retained an ordinary value");
                    assert!(projected.is_type() && projected.matches_proof(&proof));
                }
                UserElaboratorSignatureSlot::Value { .. } => match value {
                    crate::normalization::Value::CheckedTerm(_) => {}
                    crate::normalization::Value::Projected(projected) => {
                        assert!(!projected.is_type() && projected.matches_proof(&proof));
                    }
                    _ => unreachable!("a projected elaborator value slot changed handle class"),
                },
            }
        }
        let captures = resolve_user_elaborator_captures_for_call(
            self.elaborator,
            tcx,
            self.elaborator_module,
        )?;
        Ok(ReadyProjectedUserElaboratorAction {
            action: self,
            captures,
            declared_inputs,
            frozen_residual,
            proof,
            fills,
        })
    }
}

pub(crate) struct ReadyProjectedUserElaboratorAction<'m> {
    action: PreparedUserElaboratorAction<'m>,
    captures: ResolvedUserElaboratorCaptures,
    declared_inputs: Vec<crate::normalization::Value>,
    frozen_residual: FrozenProjectedResidualAbi,
    proof: crate::pass::typecheck_core::apply::fills::MarkedComptimeProof,
    fills: crate::pass::typecheck_core::apply::fills::FillContext,
}

impl ReadyProjectedUserElaboratorAction<'_> {
    /// Exact declaration-order binders shared by residual input scopes and the
    /// eventual eta plan; recipe closure must not reconstruct them from names.
    pub(crate) fn residual_lexical_binders(&self) -> impl Iterator<Item = &TypeParam> {
        self.frozen_residual.generated_type_params.iter().flatten()
    }

    /// Whether materialization would wrap the evaluator recipe in a callable
    /// layer. A lifted recursive callback cannot cross that escaping boundary.
    pub(crate) fn has_residual_abstraction(&self) -> bool {
        self.frozen_residual.has_residual_abstraction()
    }

    pub(crate) fn eval_packet(&self) -> crate::normalization::Value {
        let (proof, fills) =
            crate::normalization::fills_capability_values(self.proof.clone(), self.fills.clone());
        let mut values =
            Vec::with_capacity(2 + self.captures.inputs.len() + self.declared_inputs.len());
        values.push(proof);
        values.push(fills);
        values.extend(
            self.captures
                .inputs
                .iter()
                .map(user_elaborator_template_input_value),
        );
        values.extend(self.declared_inputs.iter().cloned());
        crate::normalization::right_fold_product_values(values)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum UserElaboratorTypeSlotMode {
    Required,
    Optional,
}

#[derive(Clone, Debug)]
enum UserElaboratorTemplateInput {
    ComptimeProof,
    Type(ReflectableType),
    OptionalType(UserElaboratorOptionalTypeInput),
    Term {
        value_index: usize,
        value_ty: ReflectableType,
    },
    BoundTerm {
        name: String,
        value_ty: ReflectableType,
    },
    CapturedTerm {
        term: crate::normalization::EvalRef<crate::normalization::CheckedTerm>,
    },
}

#[derive(Clone, Debug)]
enum UserElaboratorOptionalTypeInput {
    Known(ReflectableType),
    Infer,
}

#[derive(Clone, Debug)]
enum UserElaboratorTemplateInputKey {
    ComptimeProof,
    Type(crate::ast::Type<UncheckedPrime>),
    OptionalTypeKnown(crate::ast::Type<UncheckedPrime>),
    OptionalTypeInfer,
    Term(crate::ast::Type<UncheckedPrime>),
    ResidualShape(crate::ast::Type<UncheckedPrime>),
    CapturedTerm(crate::ast::Type<UncheckedPrime>),
}

#[derive(Clone)]
struct ResolvedUserElaboratorCaptures {
    inputs: Vec<UserElaboratorTemplateInput>,
    imports: Vec<UserElaboratorTemplateGeneratedImport>,
}

impl ResolvedUserElaboratorCaptures {
    fn empty() -> Self {
        Self {
            inputs: Vec::new(),
            imports: Vec::new(),
        }
    }
}

struct ResolvedCaptureTermPath {
    /// The exact owner of the declaration named by the written path. This is
    /// distinct from `owner_module_path` for an identity alias: lexical order
    /// and alias visibility belong to the source alias, while replay targets
    /// the terminal newtype member.
    source_owner_module_path: Option<String>,
    /// The exact owner used when replaying the captured term.
    owner_module_path: Option<String>,
    visibility_edges: Vec<ResolvedCaptureVisibilityEdge>,
    replay_tail: Vec<String>,
}

#[derive(Debug, PartialEq, Eq)]
struct ResolvedCaptureVisibilityEdge {
    owner_module_path: Option<String>,
    visibility: crate::ast::Visibility,
    target: String,
}

fn user_elaborator_signature_layout(
    call_ty: &InternedType,
    alias_ctx: &AliasCtx<'_, '_>,
) -> UserElaboratorSignatureLayout {
    let mut slots = Vec::new();
    let mut layers = Vec::new();
    let mut cur = call_ty.clone();
    let mut bound = alias_ctx.binder_local_names();
    loop {
        let layer = layers.len();
        let mut type_params = Vec::new();
        loop {
            let scoped_aliases = AliasCtx {
                binder_locals: Some(&bound),
                ..*alias_ctx
            };
            let (head, canonical) = crate::pass::typecheck_core::canonicalize_for_comparison(
                cur.as_type(),
                &scoped_aliases,
                cur.identity_is_canonical(),
            );
            cur = InternedType::fresh_with_identity(head, canonical);
            let Type::Forall { param, body, .. } = cur.clone_type() else {
                break;
            };
            slots.push(UserElaboratorSignatureSlot::Type {
                param: param.clone(),
            });
            bound.insert(param.name.clone());
            type_params.push(param);
            cur = InternedType::fresh_with_identity(*body, cur.identity_is_canonical());
        }
        let identity_canonical = cur.identity_is_canonical();
        let Type::Function {
            param,
            ret,
            abi_arity,
            ..
        } = cur.clone_type()
        else {
            if !type_params.is_empty() {
                layers.push(UserElaboratorSignatureLayer {
                    type_params,
                    value_param: None,
                    value_abi_arity: 0,
                });
            }
            return UserElaboratorSignatureLayout {
                slots,
                layers,
                result_ty: cur,
            };
        };
        let value_param = InternedType::fresh_with_identity(*param, identity_canonical);
        let expanded_value_slots =
            user_elaborator_expanded_value_slot_count(&value_param, alias_ctx);
        let mut expanded_start = 0usize;
        for ty in user_elaborator_value_slot_types(&value_param, abi_arity) {
            let expanded_width = user_elaborator_expanded_value_slot_count(&ty, alias_ctx).max(1);
            slots.push(UserElaboratorSignatureSlot::Value {
                ty,
                layer,
                expanded_start,
                expanded_width,
            });
            expanded_start += expanded_width;
        }
        debug_assert!(
            abi_arity == 0 || expanded_start == expanded_value_slots,
            "the elaborator ABI view must cover the semantic value packet"
        );
        layers.push(UserElaboratorSignatureLayer {
            type_params,
            value_param: Some(value_param),
            value_abi_arity: abi_arity,
        });
        cur = InternedType::fresh_with_identity(*ret, identity_canonical);
    }
}

fn trailing_block_declaration_error(
    span: Span,
    message: &str,
    elaborator: &crate::ast::UserElaboratorDef<Lowered>,
    module: Option<&Module>,
    tcx: &TypeCtx<'_, '_>,
) -> Error {
    let error = Error::type_(span, message);
    match module {
        Some(module) if !std::ptr::eq(module, tcx.env.module) => {
            let entry = tcx
                .env
                .package
                .and_then(|package| package.module(&module_path_string(module)))
                .expect("a resolved imported elaborator has a package module entry");
            error.with_secondary_in_file(
                entry.file_path.clone(),
                elaborator.name_span,
                "trailing blocks declared here",
            )
        }
        _ => error.with_secondary(elaborator.name_span, "trailing blocks declared here"),
    }
}

fn validate_trailing_declaration(
    elaborator: &crate::ast::UserElaboratorDef<Lowered>,
    layout: &UserElaboratorSignatureLayout,
    aliases: &AliasCtx<'_, '_>,
    tcx: &TypeCtx<'_, '_>,
) -> Result<(), Error> {
    if elaborator.trailing_blocks.is_empty() {
        return Ok(());
    }
    let mut bound = aliases.binder_local_names();
    let mut params = Vec::new();
    let mut slots = Vec::new();
    let mut open_tails = Vec::new();
    let mut prior_inputs = HashSet::new();
    let mut final_layer = 0;
    for layer in &layout.layers {
        for param in &layer.type_params {
            prior_inputs.remove(&param.name);
        }
        bound.extend(layer.type_params.iter().map(|param| param.name.clone()));
        params.extend(layer.type_params.iter().cloned());
        let Some(param) = &layer.value_param else {
            continue;
        };
        final_layer = slots.len();
        let scoped = AliasCtx {
            binder_locals: Some(&bound),
            ..*aliases
        };
        let (mut tail, _) = crate::pass::typecheck_core::canonicalize_deep_for_comparison(
            param.as_type(),
            &scoped,
            param.identity_is_canonical(),
        );
        let mut input_params = HashSet::new();
        collect_free_type_vars(&tail, &mut input_params);
        loop {
            let value = match &tail {
                Type::Product { left, .. } => left.as_ref().clone(),
                _ => tail.clone(),
            };
            slots.push((value, tail.clone(), params.len()));
            open_tails.push(matches!(&tail, Type::Path { segments, .. }
                if segments.len() == 1 && prior_inputs.contains(&segments[0].name)
                    && params.iter().any(|param| param.name == segments[0].name)));
            match tail {
                Type::Product { right, .. } => tail = *right,
                _ => break,
            }
        }
        prior_inputs.extend(input_params);
    }

    // Every nonfinal written source takes one ordinary right-spine slot. The
    // final source can own the remaining product packet of the final layer.
    // This checks possible complete source layouts, not private ABI grouping.
    let blocks = &elaborator.trailing_blocks;
    for last in final_layer.max(blocks.len() - 1)..slots.len() {
        let first = last + 1 - blocks.len();
        if trailing_declaration_candidate(&slots[first..=last], &params, blocks, tcx)? {
            return Ok(());
        }
    }
    if open_tails.iter().any(|open| *open) {
        for last in final_layer..slots.len() {
            if trailing_declaration_open_candidate(
                &slots[..=last],
                &open_tails[..=last],
                &params,
                blocks,
                tcx,
            )? {
                return Ok(());
            }
        }
    }
    Err(Error::type_(
        blocks[0].meta.span,
        "trailing block descriptors are incompatible with the final public value inputs",
    )
    .with_secondary(elaborator.call_ty.span(), "public call type declared here"))
}

fn trailing_declaration_open_candidate(
    slots: &[(Type, Type, usize)],
    open_tails: &[bool],
    params: &[TypeParam],
    blocks: &[crate::ast::TrailingBlockDecl<Lowered>],
    tcx: &TypeCtx<'_, '_>,
) -> Result<bool, Error> {
    use crate::pass::typecheck_core::{
        GoalOrigin, GoalOwnerKind, GoalRole, GoalSolutionPolicy, GoalStore, ScopedType,
        ScopedTypeEdge,
    };

    fn abstract_params(params: &[TypeParam], ty: Type, span: Span) -> Type {
        params.iter().rev().fold(ty, |body, param| Type::Forall {
            param: param.clone(),
            body: Box::new(body),
            meta: Meta::new(span),
        })
    }

    fn abstract_goals(ty: &mut Type, captures: &HashMap<crate::ast::TypeGoalRef, String>) {
        match ty {
            Type::Goal {
                goal, args, meta, ..
            } => {
                for arg in args.iter_mut() {
                    abstract_goals(arg, captures);
                }
                let name = captures
                    .get(goal)
                    .expect("a declaration relation cannot capture an unregistered inference goal");
                *ty = Type::synth_path(vec![name.clone()], std::mem::take(args), meta.span);
            }
            Type::Path { args, .. } => {
                for arg in args {
                    abstract_goals(arg, captures);
                }
            }
            Type::Product { left, right, .. } | Type::Sum { left, right, .. } => {
                abstract_goals(left, captures);
                abstract_goals(right, captures);
            }
            Type::Function { param, ret, .. } => {
                abstract_goals(param, captures);
                abstract_goals(ret, captures);
            }
            Type::Forall { body, .. } => abstract_goals(body, captures),
            Type::Unit { .. } | Type::Bottom { .. } | Type::Infer { .. } => {}
            Type::LabelSugar { ext, .. } => match *ext {},
        }
    }

    let span = blocks[0].meta.span;
    let mut store = GoalStore::new();
    let owner = store.begin_owner(
        None,
        store.scope_from_type_ctx(tcx),
        GoalOwnerKind::Application,
        span,
    )?;
    let mut formals = params
        .iter()
        .enumerate()
        .map(|(index, param)| TypeParam {
            name: format!("\0block-public-{index}"),
            ..param.clone()
        })
        .collect::<Vec<_>>();
    for index in 0..blocks.len() {
        for (role, kind) in [
            ("result", None),
            ("carrier", Some(crate::ast::Kind::arrow_chain(1))),
        ] {
            formals.push(TypeParam {
                name: format!("\0block-descriptor-{index}-{role}"),
                span,
                kind,
            });
        }
    }
    let mut captures = HashMap::new();
    let mut arguments = Vec::new();
    for formal in &formals {
        let goal = store.alloc_goal(
            owner,
            formal.effective_kind(),
            GoalSolutionPolicy::PolytypeAllowed,
            GoalOrigin::named(span, GoalRole::TypeArgument, &formal.name),
        )?;
        captures.insert(goal, formal.name.clone());
        arguments.push(
            store
                .scoped_goal_at(goal, Vec::new(), owner, span)?
                .canonicalized_for_comparison(tcx),
        );
    }
    let mut pending = Vec::<(ScopedType, bool)>::new();
    for (index, (value, tail, count)) in slots.iter().enumerate() {
        let ty = if index + 1 == slots.len() {
            tail
        } else {
            value
        };
        let found = store.scoped_type(
            owner,
            InternedType::fresh_canonical(abstract_params(&params[..*count], ty.clone(), span)),
            span,
        )?;
        let found = found
            .projected_public_forall_prefix_application(&arguments[..*count])
            .expect("declaration source parameters share their exact root scope");
        pending.push((found, open_tails[index]));
    }
    let mut delta = store.begin_delta(owner, span)?;
    let mut remaining = blocks.len();
    while remaining != 0 {
        let Some((found, expand)) = pending.pop() else {
            return Ok(false);
        };
        let mut found = store.zonk_for_progress(&delta, found, tcx)?;
        if expand {
            let mut cells = Vec::new();
            while let Some(left) = found.projected_structural_child(ScopedTypeEdge::ProductLeft) {
                cells.push((left, false));
                found = found
                    .projected_structural_child(ScopedTypeEdge::ProductRight)
                    .expect("a product has both structural children");
            }
            if matches!(found.ty().as_type(), Type::Goal { .. }) {
                // Its public domain still has unknown source capacity after
                // all fixed suffix equations. The ordinary call transcript
                // supplies the concrete layout and validates every exposure.
                return Ok(true);
            }
            cells.push((found, false));
            pending.extend(cells);
            continue;
        }
        remaining -= 1;
        let block = &blocks[remaining];
        if block.exposure == crate::ast::BlockExposure::Product {
            continue;
        }
        // Reconstruct a schema through explicit same-store arguments, never
        // attach raw goals to a newly invented lexical scope.
        let mut template = found.ty().clone_type();
        abstract_goals(&mut template, &captures);
        let Some((required, _)) =
            trailing_declaration_slot_schema(&template, block.exposure, remaining, span)
        else {
            return Ok(false);
        };
        let expected = store.scoped_type(
            owner,
            InternedType::fresh_canonical(abstract_params(&formals, required, span)),
            span,
        )?;
        let expected = expected
            .projected_public_forall_prefix_application(&arguments)
            .expect("a declaration schema reapplies its exact captured goal arguments");
        if store
            .constrain_equation(&mut delta, found, expected.into(), span, tcx)
            .is_err()
        {
            return Ok(false);
        }
    }
    Ok(true)
}

fn trailing_declaration_candidate(
    slots: &[(Type, Type, usize)],
    params: &[TypeParam],
    blocks: &[crate::ast::TrailingBlockDecl<Lowered>],
    tcx: &TypeCtx<'_, '_>,
) -> Result<bool, Error> {
    use crate::pass::typecheck_core::{
        GoalOrigin, GoalOwnerKind, GoalRole, GoalSolutionPolicy, GoalStore, ScopedType,
    };

    fn abstract_params(params: &[TypeParam], ty: Type, span: Span) -> Type {
        params.iter().rev().fold(ty, |body, param| Type::Forall {
            param: param.clone(),
            body: Box::new(body),
            meta: Meta::new(span),
        })
    }

    fn allocate(
        store: &mut GoalStore,
        owner: crate::ast::TypeGoalOwner,
        param: &TypeParam,
        tcx: &TypeCtx<'_, '_>,
    ) -> Result<ScopedType, Error> {
        let goal = store.alloc_goal(
            owner,
            param.effective_kind(),
            GoalSolutionPolicy::PolytypeAllowed,
            GoalOrigin::named(param.span, GoalRole::TypeArgument, &param.name),
        )?;
        Ok(store
            .scoped_goal_at(goal, Vec::new(), owner, param.span)?
            .canonicalized_for_comparison(tcx))
    }

    let span = blocks[0].meta.span;
    let mut store = GoalStore::new();
    let owner = store.begin_owner(
        None,
        store.scope_from_type_ctx(tcx),
        GoalOwnerKind::Application,
        span,
    )?;
    let arguments = params
        .iter()
        .map(|param| allocate(&mut store, owner, param, tcx))
        .collect::<Result<Vec<_>, _>>()?;
    let mut equations = Vec::new();
    for (index, (block, (value, tail, count))) in blocks.iter().zip(slots).enumerate() {
        if block.exposure == crate::ast::BlockExposure::Product {
            continue;
        }
        let ty = if index + 1 == blocks.len() {
            tail
        } else {
            value
        };
        let Some((required, extra)) =
            trailing_declaration_slot_schema(ty, block.exposure, index, span)
        else {
            return Ok(false);
        };
        let found = store.scoped_type(
            owner,
            InternedType::fresh_canonical(abstract_params(&params[..*count], ty.clone(), span)),
            span,
        )?;
        let found = found
            .projected_public_forall_prefix_application(&arguments[..*count])
            .expect("public declaration arguments share their root scope");
        let mut expected_args = arguments[..*count].to_vec();
        for param in &extra {
            expected_args.push(allocate(&mut store, owner, param, tcx)?);
        }
        let required = abstract_params(&extra, required, span);
        let expected = store.scoped_type(
            owner,
            InternedType::fresh_canonical(abstract_params(&params[..*count], required, span)),
            span,
        )?;
        let expected = expected
            .projected_public_forall_prefix_application(&expected_args)
            .expect("descriptor schema arguments share their root scope");
        equations.push((found, expected, span));
    }
    // This disposable relation checks compatibility only. Unsolved public
    // parameters remain for ordinary calls; no substitution or publication
    // from a declaration check enters a caller's inference domain.
    let mut delta = store.begin_delta(owner, span)?;
    Ok(store
        .constrain_equations_atomically(&mut delta, equations, tcx)
        .is_ok())
}

fn trailing_declaration_slot_schema(
    ty: &Type,
    exposure: crate::ast::BlockExposure,
    index: usize,
    span: Span,
) -> Option<(Type, Vec<TypeParam>)> {
    let binder = |role: &str, kind| TypeParam {
        name: format!("\0block-descriptor-{index}-{role}"),
        span,
        kind,
    };
    let result = binder("result", None);
    let result_ty = Type::synth_path(vec![result.name.clone()], Vec::new(), span);
    if exposure == crate::ast::BlockExposure::Thunk {
        return Some((
            Type::synth_function(Vec::new(), result_ty, span),
            vec![result],
        ));
    }
    assert_eq!(exposure, crate::ast::BlockExposure::Sequence);
    let mut extra = vec![result];
    let known_carrier = match ty {
        Type::Function { param, .. } => match param.as_ref() {
            Type::Forall { param: a, body, .. } => match body.as_ref() {
                Type::Forall { param: b, body, .. } => match body.as_ref() {
                    Type::Function { param, .. } => match param.as_ref() {
                        Type::Product { left, .. } => {
                            Some((a.clone(), b.clone(), left.as_ref().clone()))
                        }
                        _ => None,
                    },
                    _ => None,
                },
                _ => None,
            },
            _ => None,
        },
        _ => None,
    };
    let (a, b, fa) = known_carrier.unwrap_or_else(|| {
        let a = binder("input", None);
        let b = binder("output", None);
        let carrier = binder("carrier", Some(crate::ast::Kind::arrow_chain(1)));
        let fa = Type::synth_path(
            vec![carrier.name.clone()],
            vec![Type::synth_path(vec![a.name.clone()], Vec::new(), span)],
            span,
        );
        extra.push(carrier);
        (a, b, fa)
    });
    if a.effective_kind() != crate::ast::Kind::Star
        || b.effective_kind() != crate::ast::Kind::Star
        || a.name == b.name
        || type_mentions_free_param(&fa, &b.name)
    {
        return None;
    }
    let a_ty = Type::synth_path(vec![a.name.clone()], Vec::new(), span);
    let b_ty = Type::synth_path(vec![b.name.clone()], Vec::new(), span);
    let fb = subst_type(&fa, &HashMap::from([(a.name.clone(), b_ty)]));
    let result_ty = subst_type(&fa, &HashMap::from([(a.name.clone(), result_ty)]));
    let bind = Type::synth_function(
        vec![fa, Type::synth_function(vec![a_ty], fb.clone(), span)],
        fb,
        span,
    );
    let bind = [a, b]
        .into_iter()
        .rev()
        .fold(bind, |body, param| Type::Forall {
            param,
            body: Box::new(body),
            meta: Meta::new(span),
        });
    Some((Type::synth_function(vec![bind], result_ty, span), extra))
}

fn sequence_slot_type(ty: &InternedType, aliases: &AliasCtx<'_, '_>) -> bool {
    let (ty, _) = crate::pass::typecheck_core::canonicalize_deep_for_comparison(
        ty.as_type(),
        aliases,
        ty.identity_is_canonical(),
    );
    let Type::Function {
        param: bind,
        ret: result,
        ..
    } = ty
    else {
        return false;
    };
    let Type::Forall { param: a, body, .. } = *bind else {
        return false;
    };
    let Type::Forall { param: b, body, .. } = *body else {
        return false;
    };
    if a.effective_kind() != crate::ast::Kind::Star
        || b.effective_kind() != crate::ast::Kind::Star
        || a.name == b.name
    {
        return false;
    }
    let Type::Function { param, ret, .. } = *body else {
        return false;
    };
    let Type::Product {
        left: fa,
        right: continuation,
        ..
    } = *param
    else {
        return false;
    };
    let Type::Function {
        param: input,
        ret: fb,
        ..
    } = *continuation
    else {
        return false;
    };
    if type_mentions_free_param(&fa, &b.name) {
        return false;
    }
    let mut bound = aliases.binder_local_names();
    bound.insert(a.name.clone());
    bound.insert(b.name.clone());
    let aliases = AliasCtx {
        binder_locals: Some(&bound),
        ..*aliases
    };
    let a_ty = Type::synth_path(vec![a.name.clone()], Vec::new(), a.span);
    let b_ty = Type::synth_path(vec![b.name.clone()], Vec::new(), b.span);
    let expected_fb = subst_type(&fa, &HashMap::from([(a.name.clone(), b_ty)]));
    let same = |left: &Type, right: &Type| {
        crate::pass::typecheck_core::require_type_equiv_state(
            left, right, a.span, &aliases, true, true,
        )
        .is_ok()
    };
    if !same(&input, &a_ty) || !same(&fb, &expected_fb) || !same(&ret, &expected_fb) {
        return false;
    }
    // Reuse ordinary closed-type matching to establish the same carrier at R;
    // no equation is added to the caller's inference domain by this validation.
    crate::pass::typecheck_core::unify_pattern_with_holes_state(
        &fa,
        &result,
        &HashSet::from([a.name]),
        &HashSet::new(),
        &mut HashMap::new(),
        a.span,
        &aliases,
        true,
        true,
    )
    .is_ok()
}

fn user_elaborator_value_slot_types(param: &InternedType, abi_arity: usize) -> Vec<InternedType> {
    Type::right_spine_take(param.as_type(), abi_arity)
        .into_iter()
        .map(|ty| InternedType::fresh_with_identity(ty.clone(), param.identity_is_canonical()))
        .collect()
}

fn user_elaborator_expanded_value_slot_count(
    param: &InternedType,
    alias_ctx: &AliasCtx<'_, '_>,
) -> usize {
    let mut count = 0usize;
    let mut current = param.clone();
    loop {
        let (unfolded, identity_canonical) =
            crate::pass::typecheck_core::canonicalize_for_comparison(
                current.as_type(),
                alias_ctx,
                current.identity_is_canonical(),
            );
        match unfolded {
            Type::Product { right, .. } => {
                count += 1;
                current = InternedType::fresh_with_identity(*right, identity_canonical);
            }
            // Unit is one explicit semantic packet even though the stable host
            // ABI has arity zero for it.
            Type::Unit { .. } => return count + 1,
            _ => return count + 1,
        }
    }
}

fn projected_user_elaborator_value_slot(
    ty: &InternedType,
    substitutions: &HashMap<String, Type>,
    expanded_start: usize,
    declared_expanded_width: usize,
    frozen_layer_width: Option<usize>,
) -> (InternedType, usize, usize) {
    let ty = InternedType::fresh_with_identity(
        subst_type(ty.as_type(), substitutions),
        ty.identity_is_canonical(),
    );
    // The public call freezes semantic source coordinates when its layer opens.
    // A later-solved type argument may expose a wider product, but the final
    // private ABI slot owns the already-selected remaining spine.
    let expanded_width = frozen_layer_width.map_or(declared_expanded_width, |layer_width| {
        layer_width
            .checked_sub(expanded_start)
            .filter(|width| *width != 0)
            .expect("a projected elaborator value slot exceeded its frozen call layer")
    });
    (ty, expanded_start, expanded_width)
}

struct CompletedUserElaboratorAbi {
    inputs: Vec<UserElaboratorTemplateInput>,
    values: Vec<Expr>,
    value_adapter: crate::normalization::CheckedTermTemplateValueAdapter,
    residual_abstraction: crate::pass::substitute::EtaPlan<UncheckedPrime>,
    /// Enclosing source binders complete the replay allocator's namespace but
    /// do not affect the reusable elaborator template or its memo key.
    ambient_type_names: HashSet<String>,
    terminal_result_ty: Option<InternedType>,
}

fn typed_source_slot_types(
    source: &TypedUserElaboratorCallSource,
    tcx: &TypeCtx<'_, '_>,
) -> Vec<InternedType> {
    if source.expanded_width == 1 {
        return vec![source.expected.clone()];
    }
    let (unfolded, identity_canonical) = crate::pass::typecheck_core::canonicalize_for_comparison(
        source.expected.as_type(),
        &tcx.env.alias_ctx(),
        source.expected.identity_is_canonical(),
    );
    let slots = Type::right_spine_take(&unfolded, source.expanded_width);
    assert_eq!(
        slots.len(),
        source.expanded_width,
        "a typed source width must match its expected product spine"
    );
    slots
        .into_iter()
        .map(|ty| InternedType::fresh_with_identity(ty.clone(), identity_canonical))
        .collect()
}

fn reserve_module_nominal_type_names(module: &Module, reserved: &mut HashSet<String>) {
    for item in &module.items {
        crate::pass::resolve::for_each_item_declaration(item, |declaration| {
            let name = declaration
                .type_alias()
                .map(|alias| alias.name.as_str())
                .or_else(|| declaration.newtype().map(|newtype| newtype.name.as_str()))
                .or_else(|| declaration.host_type().map(|host| host.name.as_str()));
            if let Some(name) = name {
                reserved.insert(name.to_owned());
            }
        });
    }
}

fn generated_elaborator_type_names(
    layout: &UserElaboratorSignatureLayout,
    typed: &TypedUserElaboratorCall,
    tcx: &TypeCtx<'_, '_>,
) -> HashSet<String> {
    let mut reserved = tcx.in_scope_type_param_binders();
    if let Some(package) = tcx.env.package {
        for (_, entry) in package.modules() {
            reserve_module_nominal_type_names(&entry.module, &mut reserved);
        }
    } else {
        reserve_module_nominal_type_names(tcx.env.module, &mut reserved);
    }

    collect_free_type_vars(layout.result_ty.as_type(), &mut reserved);
    for layer in &layout.layers {
        for param in &layer.type_params {
            reserved.insert(param.name.clone());
        }
        if let Some(value_param) = &layer.value_param {
            collect_free_type_vars(value_param.as_type(), &mut reserved);
        }
    }
    for layer in &typed.layers {
        for slot in &layer.type_slots {
            if let Some(resolved) = &slot.resolved {
                collect_free_type_vars(resolved.as_type(), &mut reserved);
            }
            if let Some(occurrence) = &slot.occurrence {
                collect_free_type_vars(occurrence.as_type(), &mut reserved);
            }
        }
        for source in &layer.sources {
            collect_free_type_vars(source.expected.as_type(), &mut reserved);
        }
    }
    if let Some(result_ty) = &typed.result_ty {
        collect_free_type_vars(result_ty.as_type(), &mut reserved);
    }
    reserved
}

fn generated_elaborator_type_names_projected(
    layout: &UserElaboratorSignatureLayout,
    observed_types: &[InternedType],
    tcx: &TypeCtx<'_, '_>,
) -> HashSet<String> {
    let mut reserved = tcx.in_scope_type_param_binders();
    if let Some(package) = tcx.env.package {
        for (_, entry) in package.modules() {
            reserve_module_nominal_type_names(&entry.module, &mut reserved);
        }
    } else {
        reserve_module_nominal_type_names(tcx.env.module, &mut reserved);
    }
    collect_free_type_vars(layout.result_ty.as_type(), &mut reserved);
    for layer in &layout.layers {
        for param in &layer.type_params {
            reserved.insert(param.name.clone());
        }
        if let Some(value_param) = &layer.value_param {
            collect_free_type_vars(value_param.as_type(), &mut reserved);
        }
    }
    for ty in observed_types {
        collect_free_type_vars(ty.as_type(), &mut reserved);
    }
    reserved
}

fn generated_elaborator_type_param(
    original: &TypeParam,
    reserved: &mut HashSet<String>,
) -> TypeParam {
    // Declaration binders are reserved before allocation, so the generated
    // name always differs from the source binder while retaining its legal
    // TypeParam spelling and exact kind.
    let name = fresh_type_var(&original.name, reserved);
    assert!(
        reserved.insert(name.clone()),
        "a generated elaborator type binder must be fresh"
    );
    TypeParam {
        name,
        span: original.span,
        kind: original.kind.clone(),
    }
}

fn type_mentions_free_param(ty: &Type, name: &str) -> bool {
    let mut free = HashSet::new();
    collect_free_type_vars(ty, &mut free);
    free.contains(name)
}

fn type_slot_occurs_only_in_result(
    layout: &UserElaboratorSignatureLayout,
    layer_index: usize,
    layer_slot: usize,
) -> bool {
    // A later same-spelled binder shadows this one, so any result occurrence
    // after that boundary belongs to the later binder rather than this slot.
    let name = &layout.layers[layer_index].type_params[layer_slot].name;
    for (index, layer) in layout.layers.iter().enumerate().skip(layer_index) {
        let later_params = if index == layer_index {
            &layer.type_params[layer_slot + 1..]
        } else {
            &layer.type_params[..]
        };
        if later_params.iter().any(|param| param.name == *name) {
            return false;
        }
        if layer
            .value_param
            .as_ref()
            .is_some_and(|value| type_mentions_free_param(value.as_type(), name))
        {
            return false;
        }
    }
    type_mentions_free_param(layout.result_ty.as_type(), name)
}

#[allow(clippy::too_many_arguments)]
fn complete_user_elaborator_abi(
    layout: &UserElaboratorSignatureLayout,
    type_slot_modes: &[UserElaboratorTypeSlotMode],
    typed: &TypedUserElaboratorCall,
    frozen_residual: Option<&FrozenProjectedResidualAbi>,
    tcx: &TypeCtx<'_, '_>,
    span: Span,
) -> Result<CompletedUserElaboratorAbi, Error> {
    assert!(
        typed.layers.len() <= layout.layers.len(),
        "the shared call transcript exceeded the elaborator declaration"
    );
    let source_count = typed
        .layers
        .iter()
        .flat_map(|layer| layer.sources.iter().map(|source| source.source_index + 1))
        .max()
        .unwrap_or(0);
    let mut adapter_sources = vec![None; source_count];
    let mut values = vec![None; source_count];
    for (layer_index, layer) in typed.layers.iter().enumerate() {
        for source in &layer.sources {
            let reflected = reflect_elaborator_interned_type(&source.expected, tcx)?;
            let replacement = crate::normalization::CheckedTermTemplateSource {
                ty: reflected.as_type().clone(),
                force_if_unused: layout.layers[layer_index].value_abi_arity == 0,
            };
            assert!(
                adapter_sources[source.source_index]
                    .replace(replacement)
                    .is_none(),
                "one source expression appeared twice in the call transcript"
            );
            assert!(
                values[source.source_index]
                    .replace(source.source.clone())
                    .is_none(),
                "one source expression appeared twice in the call transcript"
            );
        }
    }
    let mut adapter_sources = adapter_sources
        .into_iter()
        .map(|source| source.expect("source indices in a call transcript are contiguous"))
        .collect::<Vec<_>>();
    let mut values = values
        .into_iter()
        .map(|source| source.expect("source indices in a call transcript are contiguous"))
        .collect::<Vec<_>>();

    let mut substitutions = HashMap::new();
    let mut inputs = Vec::new();
    let mut adapter_slots = Vec::new();
    let mut residual_layers = Vec::new();
    let mut residual_prefix_type_params = Vec::new();
    let mut residual_prefix_has_value_layer = false;
    let mut residual_reflection_binders = Vec::new();
    let mut generated_type_names = generated_elaborator_type_names(layout, typed, tcx);
    let mut type_mode_index = 0usize;
    let mut abi_value_index = 0usize;

    for (layer_index, layer) in layout.layers.iter().enumerate() {
        let typed_layer = typed.layers.get(layer_index);
        let consumed_type_slots = typed_layer.map_or(0, |layer| layer.type_slots.len());
        assert!(
            consumed_type_slots <= layer.type_params.len(),
            "the call transcript consumed too many declaration type slots"
        );
        let value_layer_consumed = typed_layer.is_some_and(|layer| layer.value_layer_consumed);
        let mut residual_type_params = Vec::new();

        for (layer_slot, param) in layer.type_params.iter().enumerate() {
            let frozen_type_index = type_mode_index;
            let mode = type_slot_modes[type_mode_index];
            type_mode_index += 1;
            let resolved = if layer_slot < consumed_type_slots {
                let slot = &typed_layer
                    .expect("a consumed type slot has a transcript layer")
                    .type_slots[layer_slot];
                match slot.resolved.clone() {
                    Some(resolved) => {
                        substitutions.insert(
                            param.name.clone(),
                            slot.occurrence.as_ref().unwrap_or(&resolved).clone_type(),
                        );
                        resolved
                    }
                    None => {
                        if !matches!(mode, UserElaboratorTypeSlotMode::Optional) {
                            return Err(Error::type_(
                                span,
                                format!(
                                    "cannot infer type argument `[{}]` of this elaborator call",
                                    param.name
                                ),
                            ));
                        }
                        assert!(
                            type_slot_occurs_only_in_result(layout, layer_index, layer_slot),
                            "an open elaborator ABI dependency passed action-readiness checking"
                        );
                        if let Some(occurrence) = &slot.occurrence {
                            substitutions.insert(param.name.clone(), occurrence.clone_type());
                        }
                        inputs.push(UserElaboratorTemplateInput::OptionalType(
                            UserElaboratorOptionalTypeInput::Infer,
                        ));
                        continue;
                    }
                }
            } else {
                let generated = frozen_residual
                    .and_then(|frozen| frozen.generated_type_params[frozen_type_index].as_ref())
                    .cloned()
                    .unwrap_or_else(|| {
                        generated_elaborator_type_param(param, &mut generated_type_names)
                    });
                let generated_ty = Type::Path {
                    segments: vec![PathSegment::new(generated.name.clone(), span)],
                    args: Vec::new(),
                    meta: Meta::new(span),
                };
                residual_type_params.push(generated.clone());
                residual_reflection_binders.push(generated);
                InternedType::fresh_canonical(generated_ty)
            };
            substitutions
                .entry(param.name.clone())
                .or_insert_with(|| resolved.clone_type());
            let reflected = reflect_elaborator_interned_type_with_binders(
                &resolved,
                tcx,
                &residual_reflection_binders,
            )?;
            inputs.push(match mode {
                UserElaboratorTypeSlotMode::Required => {
                    UserElaboratorTemplateInput::Type(reflected)
                }
                UserElaboratorTypeSlotMode::Optional => UserElaboratorTemplateInput::OptionalType(
                    UserElaboratorOptionalTypeInput::Known(reflected),
                ),
            });
        }

        let source_slots = typed_layer
            .map(|typed_layer| {
                typed_layer
                    .sources
                    .iter()
                    .map(|source| (source, typed_source_slot_types(source, tcx)))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let mut residual_values = Vec::new();
        for slot in layout.slots.iter().filter(|slot| {
            matches!(slot, UserElaboratorSignatureSlot::Value { layer, .. } if *layer == layer_index)
        }) {
            let UserElaboratorSignatureSlot::Value {
                ty,
                expanded_start,
                expanded_width,
                ..
            } = slot
            else {
                unreachable!()
            };
            let resolved = InternedType::fresh_with_identity(
                subst_type(ty.as_type(), &substitutions),
                ty.identity_is_canonical(),
            );
            let reflected = reflect_elaborator_interned_type_with_binders(
                &resolved,
                tcx,
                &residual_reflection_binders,
            )?;
            if value_layer_consumed {
                let mut pieces = Vec::with_capacity(*expanded_width);
                for expanded_slot in *expanded_start..(*expanded_start + *expanded_width) {
                    let source_piece = source_slots
                        .iter()
                        .find(|(source, _)| {
                            expanded_slot >= source.expanded_start
                                && expanded_slot < source.expanded_start + source.expanded_width
                        });
                    if let Some((source, slot_tys)) = source_piece {
                        pieces.push(crate::normalization::CheckedTermTemplatePiece {
                            source_index: source.source_index,
                            source_slot: expanded_slot - source.expanded_start,
                            source_slot_tys: slot_tys
                                .iter()
                                .map(|ty| {
                                    reflect_elaborator_interned_type(ty, tcx)
                                        .map(|reflected| reflected.as_type().clone())
                                })
                                .collect::<Result<_, _>>()?,
                        });
                        continue;
                    }

                    let (unfolded, _) =
                        crate::pass::typecheck_core::canonicalize_for_comparison(
                            resolved.as_type(),
                            &tcx.env.alias_ctx(),
                            resolved.identity_is_canonical(),
                        );
                    assert!(
                        source_slots.is_empty()
                            && *expanded_width == 1
                            && matches!(unfolded, Type::Unit { .. }),
                        "only a source-empty implicit Unit may omit an elaborator source"
                    );
                    let source_index = values.len();
                    let source_ty = reflected.as_type().clone();
                    values.push(Expr::Unit { occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
                        meta: Meta::new(span),
                    });
                    adapter_sources.push(crate::normalization::CheckedTermTemplateSource {
                        ty: source_ty.clone(),
                        force_if_unused: false,
                    });
                    pieces.push(crate::normalization::CheckedTermTemplatePiece {
                        source_index,
                        source_slot: 0,
                        source_slot_tys: vec![source_ty],
                    });
                }
                inputs.push(UserElaboratorTemplateInput::Term {
                    value_index: abi_value_index,
                    value_ty: reflected,
                });
                adapter_slots.push(crate::normalization::CheckedTermTemplateSlot { pieces });
            } else {
                let name = frozen_residual
                    .and_then(|frozen| frozen.bound_value_names[abi_value_index].as_ref())
                    .cloned()
                    .unwrap_or_else(|| {
                        format!("__ct_elab_value{layer_index}_i{abi_value_index}__")
                    });
                inputs.push(UserElaboratorTemplateInput::BoundTerm {
                    name: name.clone(),
                    value_ty: reflected.clone(),
                });
                residual_values.push(crate::pass::substitute::EtaValueParam {
                    name,
                    ty: reflected.as_type().clone(),
                });
            }
            abi_value_index += 1;
        }

        if !value_layer_consumed {
            if layer.value_param.is_some() {
                let mut type_params = std::mem::take(&mut residual_prefix_type_params);
                residual_prefix_has_value_layer = false;
                type_params.extend(residual_type_params);
                residual_layers.push(crate::pass::substitute::EtaLayer {
                    type_params,
                    value_params: residual_values,
                    has_value_layer: true,
                });
            } else {
                residual_prefix_has_value_layer |= typed_layer.is_some();
                residual_prefix_type_params.extend(residual_type_params);
            }
        } else {
            assert!(
                residual_type_params.is_empty(),
                "a consumed value layer cannot retain declaration binders"
            );
        }
    }
    if !residual_prefix_type_params.is_empty() {
        residual_layers.push(crate::pass::substitute::EtaLayer {
            type_params: residual_prefix_type_params,
            value_params: Vec::new(),
            has_value_layer: residual_prefix_has_value_layer,
        });
    }
    assert_eq!(
        type_mode_index,
        type_slot_modes.len(),
        "the elaborator type-mode ABI drifted from its callable layout"
    );
    let terminal_result_ty = if residual_layers.is_empty() {
        typed.result_ty.clone()
    } else {
        // Ordinary typing observes the residual callable scheme, while the
        // evaluator produces only the body placed beneath the EtaPlan. Keep
        // its coherence target at that terminal boundary.
        Some(InternedType::fresh_with_identity(
            subst_type(layout.result_ty.as_type(), &substitutions),
            layout.result_ty.identity_is_canonical(),
        ))
    };
    Ok(CompletedUserElaboratorAbi {
        inputs,
        values,
        value_adapter: crate::normalization::CheckedTermTemplateValueAdapter {
            sources: adapter_sources,
            slots: adapter_slots,
        },
        residual_abstraction: crate::pass::substitute::EtaPlan {
            layers: residual_layers,
        },
        ambient_type_names: tcx.in_scope_type_param_binders(),
        terminal_result_ty,
    })
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum UserElaboratorCaptureSpelling {
    Type,
    Value,
    Member,
}

fn classify_user_elaborator_capture(
    capture: &crate::ast::UserElaboratorCapture,
) -> Result<UserElaboratorCaptureSpelling, Error> {
    let Some(first) = capture.segments.first() else {
        return Err(Error::type_(capture.span, "empty elaborator capture"));
    };
    let Some(last) = capture.segments.last() else {
        return Err(Error::type_(capture.span, "empty elaborator capture"));
    };
    if capture.segments.len() == 1 && crate::naming::is_type_name(first.as_str()) {
        return Ok(UserElaboratorCaptureSpelling::Type);
    }
    if capture.segments.len() == 1 && crate::naming::is_value_name(first.as_str()) {
        return Ok(UserElaboratorCaptureSpelling::Value);
    }
    if capture.segments.len() > 1 && crate::naming::is_value_name(last.as_str()) {
        return Ok(UserElaboratorCaptureSpelling::Member);
    }
    Err(Error::type_(
        capture.span,
        "elaborator captures must be a type name, a value name, or a dotted path ending in a \
         value member name",
    ))
}

fn capture_path_segments(names: impl IntoIterator<Item = String>, span: Span) -> Vec<PathSegment> {
    names
        .into_iter()
        .map(|name| PathSegment::new(name, span))
        .collect()
}

fn type_from_capture_path(names: impl IntoIterator<Item = String>, span: Span) -> Type {
    crate::ast::Type::synth_path(names.into_iter().collect(), Vec::new(), span)
}

fn expr_from_capture_path(names: impl IntoIterator<Item = String>, span: Span) -> Expr {
    Expr::Path {
        occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
        segments: capture_path_segments(names, span),
        meta: Meta::new(span),
        ext: (),
    }
}

fn module_path_for_capture_owner<'m>(
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
) -> String {
    env.module_path.clone()
}

#[cfg(all(test, feature = "surface"))]
fn reset_capture_type_owner_item_visits() {
    crate::pass::resolve::reset_nominal_provider_work();
}

#[cfg(all(test, feature = "surface"))]
fn capture_type_owner_item_visits() -> usize {
    crate::pass::resolve::nominal_provider_work().declaration_items_indexed
}

fn find_fn_owner<'m>(
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    f: &'m crate::ast::FnDef<Lowered>,
) -> Option<String> {
    if let Some(package) = env.package {
        for (path, entry) in package.modules() {
            for item in &entry.module.items {
                if let crate::ast::Item::FnDef(candidate) = item
                    && std::ptr::eq(candidate, f)
                {
                    return Some((*path).to_owned());
                }
            }
        }
    }
    if env
        .fn_defs
        .get(f.name.as_str())
        .is_some_and(|candidate| std::ptr::eq(*candidate, f))
    {
        return Some(module_path_for_capture_owner(env));
    }
    None
}

fn env_owner<'m>(env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>) -> String {
    env.module_path
        .split('/')
        .next()
        .filter(|root| !root.is_empty())
        .unwrap_or(env.module_path.as_str())
        .to_owned()
}

fn resolve_capture_type_owner_with_provider<'m>(
    capture: &crate::ast::UserElaboratorCapture,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    provider: &NominalProvider<'m, Lowered>,
) -> Result<(String, crate::ast::Visibility), Error> {
    let name = capture.segments[0].as_str();
    if let Some(owner) = resolve_type_name_owner_with_provider(name, env, provider) {
        return Ok(owner);
    }
    Err(Error::name_res(
        capture.span,
        format!("elaborator capture `{name}` does not resolve to a type in this module"),
    ))
}

#[cfg(all(test, feature = "surface"))]
fn resolve_type_name_owner<'m>(
    name: &str,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
) -> Option<(String, crate::ast::Visibility)> {
    let provider = NominalProvider::new(Some(env.module), env.package);
    resolve_type_name_owner_with_provider(name, env, &provider)
}

fn resolve_type_name_owner_with_provider<'m>(
    name: &str,
    _env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    provider: &NominalProvider<'m, Lowered>,
) -> Option<(String, crate::ast::Visibility)> {
    let segments = [PathSegment::new(name.to_owned(), Span::new(0, 0))];
    let NominalSelection::Selected(declaration) =
        provider.select(provider.root(), &segments, false)
    else {
        return None;
    };
    let visibility = if let Some(newtype) = declaration.declaration.newtype() {
        newtype.vis.clone()
    } else if let Some(alias) = declaration.declaration.type_alias() {
        alias.vis.clone()
    } else {
        return None;
    };
    Some((module_path_string(declaration.owner.module()?), visibility))
}

fn resolve_capture_fn_owner<'m>(
    capture: &crate::ast::UserElaboratorCapture,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
) -> Result<ResolvedCaptureTermPath, Error> {
    let name = capture.segments[0].as_str();
    if let Some(f) = env
        .fn_defs
        .get(name)
        .copied()
        .or_else(|| env.cross_module_fn_defs.get(name).copied())
    {
        let owner = find_fn_owner(env, f).unwrap_or_else(|| env.module_path.clone());
        return Ok(ResolvedCaptureTermPath {
            source_owner_module_path: Some(owner.clone()),
            owner_module_path: Some(owner.clone()),
            visibility_edges: vec![ResolvedCaptureVisibilityEdge {
                owner_module_path: Some(owner),
                visibility: f.vis.clone(),
                target: format!("captured function `{name}`"),
            }],
            replay_tail: vec![name.to_owned()],
        });
    }
    if env.env_fn_defs.contains_key(name) {
        let owner = env_owner(env);
        return Ok(ResolvedCaptureTermPath {
            source_owner_module_path: Some(owner.clone()),
            owner_module_path: Some(owner.clone()),
            visibility_edges: vec![ResolvedCaptureVisibilityEdge {
                owner_module_path: Some(owner),
                visibility: crate::ast::Visibility::Public,
                target: format!("captured function `{name}`"),
            }],
            replay_tail: vec![name.to_owned()],
        });
    }
    Err(Error::name_res(
        capture.span,
        format!("elaborator capture `{name}` does not resolve to a function in this module"),
    ))
}

#[cfg(all(test, feature = "surface"))]
fn resolve_capture_member_owner<'m>(
    capture: &crate::ast::UserElaboratorCapture,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
) -> Result<ResolvedCaptureTermPath, Error> {
    let nominal_provider = NominalProvider::new(Some(env.module), env.package);
    resolve_capture_member_owner_with_provider(capture, env, &nominal_provider)
}

fn resolve_capture_member_owner_with_provider<'m>(
    capture: &crate::ast::UserElaboratorCapture,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    _nominal_provider: &NominalProvider<'m, Lowered>,
) -> Result<ResolvedCaptureTermPath, Error> {
    if capture.segments.len() == 2 {
        let type_name = capture.segments[0].as_str();
        let member = capture.segments[1].as_str();
        let type_segments = &capture.segments[..1];
        if let Some(resolved) =
            resolve_capture_newtype_member(capture, env, type_segments, type_name, member)?
        {
            return Ok(resolved);
        }
    }
    if capture.segments.len() == 2 {
        let alias = capture.segments[0].as_str();
        let member = capture.segments[1].as_str();
        if let Some(module) = env.qualified_imports.get(alias) {
            for item in &module.items {
                if let crate::ast::Item::FnDef(f) = item
                    && f.name == member
                {
                    let owner = env
                        .package
                        .and_then(|package| {
                            package.modules().find_map(|(path, entry)| {
                                std::ptr::eq(&entry.module, *module).then(|| (*path).to_owned())
                            })
                        })
                        .unwrap_or_else(|| env.module_path.clone());
                    return Ok(ResolvedCaptureTermPath {
                        source_owner_module_path: Some(owner.clone()),
                        owner_module_path: Some(owner.clone()),
                        visibility_edges: vec![ResolvedCaptureVisibilityEdge {
                            owner_module_path: Some(owner),
                            visibility: f.vis.clone(),
                            target: format!("captured member `{alias}.{member}`"),
                        }],
                        replay_tail: vec![member.to_owned()],
                    });
                }
            }
        }
    }
    if capture.segments.len() == 3 {
        let type_name = capture.segments[1].as_str();
        let member = capture.segments[2].as_str();
        let type_segments = &capture.segments[..2];
        let display_name = format!("{}.{type_name}", capture.segments[0].as_str());
        if let Some(resolved) =
            resolve_capture_newtype_member(capture, env, type_segments, &display_name, member)?
        {
            return Ok(resolved);
        }
    }
    Err(Error::name_res(
        capture.span,
        format!(
            "elaborator capture `{}` does not resolve to a supported function or newtype member",
            capture
                .segments
                .iter()
                .map(|segment| segment.as_str())
                .collect::<Vec<_>>()
                .join(".")
        ),
    ))
}

fn resolve_capture_newtype_member<'m>(
    capture: &crate::ast::UserElaboratorCapture,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    type_segments: &[PathSegment],
    display_name: &str,
    member: &str,
) -> Result<Option<ResolvedCaptureTermPath>, Error> {
    let Some(resolved) = env.resolve_member_newtype(type_segments) else {
        return Ok(None);
    };
    let member_vis = if member == resolved.newtype.constructor.name {
        resolved.newtype.constructor.vis.clone()
    } else if member == resolved.newtype.projector.name {
        resolved.newtype.projector.vis.clone()
    } else {
        return Err(Error::name_res(
            capture.span,
            format!("newtype `{display_name}` has no member `{member}`"),
        ));
    };
    let source_visibility = resolved.source.visibility();
    let source_owner = module_path_string(resolved.source_module);
    let terminal_owner = module_path_string(resolved.declaring_module);
    let source_kind = if resolved.source.type_alias().is_some() {
        "type alias"
    } else {
        "newtype"
    };
    Ok(Some(ResolvedCaptureTermPath {
        source_owner_module_path: Some(source_owner.clone()),
        owner_module_path: Some(terminal_owner.clone()),
        visibility_edges: vec![
            ResolvedCaptureVisibilityEdge {
                owner_module_path: Some(source_owner),
                visibility: source_visibility,
                target: format!("captured {source_kind} `{display_name}`"),
            },
            ResolvedCaptureVisibilityEdge {
                owner_module_path: Some(terminal_owner),
                visibility: member_vis,
                target: format!("captured member `{display_name}.{member}`"),
            },
        ],
        replay_tail: vec![resolved.newtype.name.clone(), member.to_owned()],
    }))
}

fn validate_user_elaborator_capture_source_order<'m>(
    elaborator: &'m crate::ast::UserElaboratorDef<Lowered>,
    item_index: usize,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
) -> Result<(), Error> {
    fn item_declares_type(item: &Item<Lowered>, name: &str) -> bool {
        match item {
            Item::TypeAlias(alias) => alias.name == name,
            Item::Newtype(newtype) => newtype.name == name,
            Item::TypeRecGroup(group) => group.members.iter().any(|member| match member {
                crate::ast::TypeRecMember::TypeAlias(alias) => alias.name == name,
                crate::ast::TypeRecMember::Newtype(newtype) => newtype.name == name,
                crate::ast::TypeRecMember::Labels(labels, _) => {
                    labels.type_alias_name.as_deref() == Some(name)
                }
            }),
            _ => false,
        }
    }

    let nominal_provider = NominalProvider::new(Some(env.module), env.package);
    let visible_items = env
        .module
        .items
        .get(..item_index)
        .expect("elaborator item index belongs to its module");
    for capture in &elaborator.captures {
        let in_scope = match classify_user_elaborator_capture(capture)? {
            UserElaboratorCaptureSpelling::Type => {
                let name = capture.segments[0].as_str();
                if env.env_type_names.contains(name) {
                    env.module
                        .items
                        .iter()
                        .position(|item| matches!(item, Item::HostType(host) if host.name == name))
                        .is_none_or(|declaration| declaration < item_index)
                } else {
                    let (owner, _) =
                        resolve_capture_type_owner_with_provider(capture, env, &nominal_provider)?;
                    owner != env.module_path
                        || visible_items
                            .iter()
                            .any(|item| item_declares_type(item, name))
                }
            }
            UserElaboratorCaptureSpelling::Value => {
                let name = capture.segments[0].as_str();
                if env.env_fn_defs.contains_key(name) {
                    env.module
                        .items
                        .iter()
                        .position(|item| matches!(item, Item::HostFn(host) if host.name == name))
                        .is_none_or(|declaration| declaration < item_index)
                } else {
                    let resolved = resolve_capture_fn_owner(capture, env)?;
                    resolved.owner_module_path.as_deref() != Some(env.module_path.as_str())
                        || visible_items.iter().any(
                            |item| matches!(item, Item::FnDef(function) if function.name == name),
                        )
                }
            }
            UserElaboratorCaptureSpelling::Member => {
                let qualifier = capture.segments[0].as_str();
                if let Some(target) = env.qualified_imports.get(qualifier) {
                    if module_path_string(target) != env.module_path {
                        true
                    } else {
                        match capture.segments.as_slice() {
                            [_, member] => visible_items.iter().any(
                                |item| matches!(item, Item::FnDef(function) if function.name == member.as_str()),
                            ),
                            [_, type_name, _] => visible_items
                                .iter()
                                .any(|item| item_declares_type(item, type_name.as_str())),
                            _ => true,
                        }
                    }
                } else {
                    let resolved = resolve_capture_member_owner_with_provider(
                        capture,
                        env,
                        &nominal_provider,
                    )?;
                    resolved.source_owner_module_path.as_deref() != Some(env.module_path.as_str())
                        || visible_items
                            .iter()
                            .any(|item| item_declares_type(item, qualifier))
                }
            }
        };
        if !in_scope {
            let rendered = capture
                .segments
                .iter()
                .map(PathSegment::as_str)
                .collect::<Vec<_>>()
                .join(".");
            return Err(Error::name_res(
                capture.span,
                format!(
                    "elaborator capture `{rendered}` is not in scope before elaborator `{}`",
                    elaborator.name
                ),
            )
            .with_help(format!(
                "move the declaration of `{rendered}` above elaborator `{}`",
                elaborator.name
            )));
        }
    }
    Ok(())
}

fn capture_import(
    imports: &mut Vec<UserElaboratorTemplateGeneratedImport>,
    owner_module_path: &str,
    module: &Module,
) -> UserElaboratorTemplateGeneratedImport {
    if let Some(import) = imports
        .iter()
        .find(|import| import.module_path == owner_module_path)
    {
        return import.clone();
    }
    let mut requalifier = crate::pass::typecheck_core::PrimeTypeRequalifier::new(module);
    for import in imports.iter() {
        requalifier.add_generated_import(&import.module_path, &import.alias);
    }
    let import = UserElaboratorTemplateGeneratedImport {
        module_path: owner_module_path.to_owned(),
        alias: requalifier.ensure_module_import(owner_module_path),
    };
    if !imports.iter().any(|existing| existing == &import) {
        imports.push(import.clone());
    }
    import
}

fn captured_term_for_replay(
    capture: &crate::ast::UserElaboratorCapture,
    resolved: &ResolvedCaptureTermPath,
    imports: &mut Vec<UserElaboratorTemplateGeneratedImport>,
    module: &Module,
) -> Expr {
    if let Some(owner_module_path) = &resolved.owner_module_path {
        let import = capture_import(imports, owner_module_path, module);
        expr_from_capture_path(
            std::iter::once(import.alias).chain(resolved.replay_tail.clone()),
            capture.span,
        )
    } else {
        expr_from_capture_path(resolved.replay_tail.clone(), capture.span)
    }
}

fn captured_type_for_term_replay<'m>(
    ty: &Type,
    owner_module_path: &str,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    nominal_provider: &NominalProvider<'m, Lowered>,
    imports: &mut Vec<UserElaboratorTemplateGeneratedImport>,
    identity_canonical: bool,
) -> Type {
    match ty {
        Type::Path {
            segments,
            args,
            meta,
        } => {
            let args = args
                .iter()
                .map(|arg| {
                    captured_type_for_term_replay(
                        arg,
                        owner_module_path,
                        env,
                        nominal_provider,
                        imports,
                        identity_canonical,
                    )
                })
                .collect();
            if identity_canonical
                && let Some((module_path, name)) = canonical_nominal_identity(segments)
            {
                let import = capture_import(imports, &module_path, env.module);
                return Type::synth_path(vec![import.alias, name], args, meta.span);
            }
            if segments.len() == 1
                && resolve_type_name_owner_with_provider(
                    segments[0].as_str(),
                    env,
                    nominal_provider,
                )
                .is_some_and(|(owner, _)| owner == owner_module_path)
            {
                let import = capture_import(imports, owner_module_path, env.module);
                return Type::synth_path(
                    vec![import.alias, segments[0].name.clone()],
                    args,
                    meta.span,
                );
            }
            Type::synth_path_segments(segments.clone(), args, meta.span)
        }
        Type::Product { left, right, meta } => Type::Product {
            left: Box::new(captured_type_for_term_replay(
                left,
                owner_module_path,
                env,
                nominal_provider,
                imports,
                identity_canonical,
            )),
            right: Box::new(captured_type_for_term_replay(
                right,
                owner_module_path,
                env,
                nominal_provider,
                imports,
                identity_canonical,
            )),
            meta: meta.clone(),
        },
        Type::Sum { left, right, meta } => Type::Sum {
            left: Box::new(captured_type_for_term_replay(
                left,
                owner_module_path,
                env,
                nominal_provider,
                imports,
                identity_canonical,
            )),
            right: Box::new(captured_type_for_term_replay(
                right,
                owner_module_path,
                env,
                nominal_provider,
                imports,
                identity_canonical,
            )),
            meta: meta.clone(),
        },
        Type::Function {
            param,
            ret,
            meta,
            abi_arity,
            caps,
        } => {
            let param = captured_type_for_term_replay(
                param,
                owner_module_path,
                env,
                nominal_provider,
                imports,
                identity_canonical,
            );
            Type::Function {
                param: Box::new(param),
                ret: Box::new(captured_type_for_term_replay(
                    ret,
                    owner_module_path,
                    env,
                    nominal_provider,
                    imports,
                    identity_canonical,
                )),
                meta: meta.clone(),
                abi_arity: *abi_arity,
                caps: *caps,
            }
        }
        Type::Forall { param, body, meta } => Type::Forall {
            param: param.clone(),
            body: Box::new(captured_type_for_term_replay(
                body,
                owner_module_path,
                env,
                nominal_provider,
                imports,
                identity_canonical,
            )),
            meta: meta.clone(),
        },
        Type::Unit { meta } => Type::Unit { meta: meta.clone() },
        Type::Bottom { meta } => Type::Bottom { meta: meta.clone() },
        Type::Infer { meta, ext } => Type::Infer {
            meta: meta.clone(),
            ext: *ext,
        },
        Type::Goal { .. } => unreachable!(
            "captured term replay requires a closed type; Type::Goal must be zonked first"
        ),
        Type::LabelSugar { ext, .. } => match *ext {},
    }
}

fn captured_term_type_for_replay<'m>(
    ty: &InternedType,
    resolved: &ResolvedCaptureTermPath,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    nominal_provider: &NominalProvider<'m, Lowered>,
    imports: &mut Vec<UserElaboratorTemplateGeneratedImport>,
) -> Type {
    if ty.identity_is_canonical() {
        return captured_type_for_term_replay(
            ty.as_type(),
            "",
            env,
            nominal_provider,
            imports,
            true,
        );
    }
    if let Some(owner_module_path) = &resolved.owner_module_path {
        captured_type_for_term_replay(
            ty.as_type(),
            owner_module_path,
            env,
            nominal_provider,
            imports,
            false,
        )
    } else {
        ty.clone_type()
    }
}

fn canonicalize_captured_generated_imports<P>(
    ty: &crate::ast::Type<P>,
    imports: &[UserElaboratorTemplateGeneratedImport],
) -> crate::ast::Type<P>
where
    P: crate::ast::Phase<TypeLabelSugar = crate::ast::Never> + Clone,
{
    canonicalize_captured_generated_imports_with_bound(ty, imports, &HashSet::new())
}

fn canonicalize_captured_generated_imports_with_bound<P>(
    ty: &crate::ast::Type<P>,
    imports: &[UserElaboratorTemplateGeneratedImport],
    bound: &HashSet<String>,
) -> crate::ast::Type<P>
where
    P: crate::ast::Phase<TypeLabelSugar = crate::ast::Never> + Clone,
{
    match ty {
        crate::ast::Type::Path {
            segments,
            args,
            meta,
        } => {
            let args = args
                .iter()
                .map(|arg| canonicalize_captured_generated_imports_with_bound(arg, imports, bound))
                .collect();
            let segments = segments
                .first()
                .filter(|head| !bound.contains(head.as_str()))
                .and_then(|head| {
                    imports
                        .iter()
                        .rev()
                        .find(|import| import.alias == head.as_str())
                })
                .map(|import| {
                    import
                        .module_path
                        .split('/')
                        .filter(|segment| !segment.is_empty())
                        .map(|segment| PathSegment::new(segment.to_owned(), meta.span))
                        .chain(segments.iter().skip(1).cloned())
                        .collect()
                })
                .unwrap_or_else(|| segments.clone());
            crate::ast::Type::synth_path_segments(segments, args, meta.span)
        }
        crate::ast::Type::Product { left, right, meta } => crate::ast::Type::Product {
            left: Box::new(canonicalize_captured_generated_imports_with_bound(
                left, imports, bound,
            )),
            right: Box::new(canonicalize_captured_generated_imports_with_bound(
                right, imports, bound,
            )),
            meta: meta.clone(),
        },
        crate::ast::Type::Sum { left, right, meta } => crate::ast::Type::Sum {
            left: Box::new(canonicalize_captured_generated_imports_with_bound(
                left, imports, bound,
            )),
            right: Box::new(canonicalize_captured_generated_imports_with_bound(
                right, imports, bound,
            )),
            meta: meta.clone(),
        },
        crate::ast::Type::Function {
            param,
            ret,
            meta,
            abi_arity,
            caps,
        } => crate::ast::Type::Function {
            param: Box::new(canonicalize_captured_generated_imports_with_bound(
                param, imports, bound,
            )),
            ret: Box::new(canonicalize_captured_generated_imports_with_bound(
                ret, imports, bound,
            )),
            meta: meta.clone(),
            abi_arity: *abi_arity,
            caps: caps.clone(),
        },
        crate::ast::Type::Forall { param, body, meta } => {
            let mut nested = bound.clone();
            nested.insert(param.name.clone());
            crate::ast::Type::Forall {
                param: param.clone(),
                body: Box::new(canonicalize_captured_generated_imports_with_bound(
                    body, imports, &nested,
                )),
                meta: meta.clone(),
            }
        }
        crate::ast::Type::Unit { .. }
        | crate::ast::Type::Bottom { .. }
        | crate::ast::Type::Infer { .. } => ty.clone(),
        crate::ast::Type::Goal {
            goal,
            args,
            meta,
            ext,
        } => crate::ast::Type::Goal {
            goal: *goal,
            args: args
                .iter()
                .map(|arg| canonicalize_captured_generated_imports_with_bound(arg, imports, bound))
                .collect(),
            meta: meta.clone(),
            ext: ext.clone(),
        },
        crate::ast::Type::LabelSugar { ext, .. } => match *ext {},
    }
}

fn visibility_owner_path(path: &str, span: Span) -> crate::ast::ModulePath {
    crate::ast::ModulePath {
        segments: path
            .split('/')
            .filter(|segment| !segment.is_empty())
            .map(|segment| PathSegment::new(segment.to_owned(), span))
            .collect(),
        span,
    }
}

fn require_elaborator_target_visibility(
    elaborator: &crate::ast::UserElaboratorDef<Lowered>,
    owner_module_path: Option<&str>,
    visibility: &crate::ast::Visibility,
    env: &crate::pass::typecheck_core::ModuleEnv<'_, Lowered>,
    target: &str,
    span: Span,
) -> Result<(), Error> {
    let owner = owner_module_path
        .map(|path| visibility_owner_path(path, span))
        .unwrap_or_else(|| env.module.path.clone());
    if crate::pass::resolve::visibility_covers(
        visibility,
        &owner,
        &elaborator.vis,
        &env.module.path,
    ) {
        Ok(())
    } else {
        let error = Error::type_(
            span,
            format!(
                "{target} must be at least as visible as elaborator `{}`",
                elaborator.name
            ),
        );
        if owner.segments == env.module.path.segments {
            Err(error.with_help(format!(
                "give {target} visibility equal to or wider than elaborator `{}`",
                elaborator.name
            )))
        } else {
            Err(error)
        }
    }
}

fn validate_user_elaborator_implementation_binding<'m>(
    elaborator: &crate::ast::UserElaboratorDef<Lowered>,
    tcx: &TypeCtx<'m, '_>,
) -> Result<(), Error> {
    let segments = elaborator.implementation.segments();
    let Some(last) = segments.last() else {
        unreachable!("the parser emits a nonempty elaborator implementation path")
    };
    let rendered = segments
        .iter()
        .map(PathSegment::as_str)
        .collect::<Vec<_>>()
        .join(".");
    let is_unshadowed_comptime_value = segments.len() == 1
        && tcx.env.comptime_in_scope
        && !tcx.env.fn_defs.contains_key(last.as_str())
        && !tcx.env.cross_module_fn_defs.contains_key(last.as_str())
        && !tcx.env.env_fn_defs.contains_key(last.as_str())
        && crate::comptime::ComptimeBuiltin::from_public_name(last.as_str())
            .is_some_and(crate::comptime::ComptimeBuiltin::is_value_name);
    let binder = match tcx
        .elaborations
        .position_index()
        .binder_at(&tcx.env.module_path, last.span)
    {
        Some(binder) => binder,
        None if is_unshadowed_comptime_value => return Ok(()),
        None => unreachable!(
            "synthesized elaborator implementation path `{rendered}` did not record a binder"
        ),
    };
    if matches!(binder, ResolvedBinder::NewtypeMember { .. }) {
        return Err(Error::type_(
            elaborator.implementation.span(),
            format!(
                "newtype member `{rendered}` cannot implement elaborator `{}` because it does not have the elaborator ABI",
                elaborator.name
            ),
        )
        .with_help(
            "define a function that accepts the elaborator's reflected ABI inputs and returns `__Checked_term__`, then name that function after `impl`",
        ));
    }
    Ok(())
}

fn resolve_user_elaborator_captures<'m>(
    elaborator: &'m crate::ast::UserElaboratorDef<Lowered>,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    tcx: &mut TypeCtx<'m, '_>,
) -> Result<ResolvedUserElaboratorCaptures, Error> {
    if elaborator.captures.is_empty() {
        return Ok(ResolvedUserElaboratorCaptures::empty());
    }
    let nominal_provider = NominalProvider::new(Some(env.module), env.package);
    let mut inputs = Vec::new();
    let mut imports = Vec::new();
    for capture in &elaborator.captures {
        match classify_user_elaborator_capture(capture)? {
            UserElaboratorCaptureSpelling::Type => {
                let name = capture.segments[0].as_str();
                let host_capture = env.env_type_names.contains(name);
                let owner_visibility = if host_capture {
                    None
                } else {
                    Some(resolve_capture_type_owner_with_provider(
                        capture,
                        env,
                        &nominal_provider,
                    )?)
                };
                if let Some((owner, vis)) = &owner_visibility {
                    require_elaborator_target_visibility(
                        elaborator,
                        Some(owner),
                        vis,
                        env,
                        &format!("captured type `{name}`"),
                        capture.span,
                    )?;
                }
                let source_ty = type_from_capture_path([name.to_owned()], capture.span);
                compute_kind(&source_ty, capture.span, tcx)?;
                let replay_ty = if let Some((owner, _)) = owner_visibility {
                    captured_type_for_term_replay(
                        &source_ty,
                        &owner,
                        env,
                        &nominal_provider,
                        &mut imports,
                        false,
                    )
                } else {
                    source_ty
                };
                let replay_ty = canonicalize_captured_generated_imports(&replay_ty, &imports);
                let reflected = if host_capture {
                    reflect_elaborator_type(replay_ty, tcx)?
                } else {
                    user_elaborator_reflectable_type(replay_ty)?
                };
                inputs.push(UserElaboratorTemplateInput::Type(reflected));
            }
            UserElaboratorCaptureSpelling::Value => {
                let resolved = resolve_capture_fn_owner(capture, env)?;
                for edge in &resolved.visibility_edges {
                    require_elaborator_target_visibility(
                        elaborator,
                        edge.owner_module_path.as_deref(),
                        &edge.visibility,
                        env,
                        &edge.target,
                        capture.span,
                    )?;
                }
                let synth = synth_path(&capture.segments, capture.span, tcx)?;
                let term_expr =
                    captured_term_for_replay(capture, &resolved, &mut imports, env.module);
                let replay_ty = captured_term_type_for_replay(
                    &synth.ty,
                    &resolved,
                    env,
                    &nominal_provider,
                    &mut imports,
                );
                let term_ty = canonicalize_captured_generated_imports(&replay_ty, &imports);
                let term_expr = substitute::substitute_expr_for_eval(
                    &term_expr,
                    tcx.elaborations,
                    &env.module_path,
                    env.package,
                    Some(env.module),
                );
                let term_ty = crate::ast::convert_type::<Lowered, UncheckedPrime>(&term_ty);
                let term = crate::normalization::CheckedTerm::new(term_expr, term_ty);
                inputs.push(UserElaboratorTemplateInput::CapturedTerm {
                    term: crate::normalization::EvalRef::new(term),
                });
            }
            UserElaboratorCaptureSpelling::Member => {
                let resolved =
                    resolve_capture_member_owner_with_provider(capture, env, &nominal_provider)?;
                for edge in &resolved.visibility_edges {
                    require_elaborator_target_visibility(
                        elaborator,
                        edge.owner_module_path.as_deref(),
                        &edge.visibility,
                        env,
                        &edge.target,
                        capture.span,
                    )?;
                }
                let synth = synth_path(&capture.segments, capture.span, tcx)?;
                let term_expr =
                    captured_term_for_replay(capture, &resolved, &mut imports, env.module);
                let replay_ty = captured_term_type_for_replay(
                    &synth.ty,
                    &resolved,
                    env,
                    &nominal_provider,
                    &mut imports,
                );
                let term_ty = canonicalize_captured_generated_imports(&replay_ty, &imports);
                let term_expr = substitute::substitute_expr_for_eval(
                    &term_expr,
                    tcx.elaborations,
                    &env.module_path,
                    env.package,
                    Some(env.module),
                );
                let term_ty = crate::ast::convert_type::<Lowered, UncheckedPrime>(&term_ty);
                let term = crate::normalization::CheckedTerm::new(term_expr, term_ty);
                inputs.push(UserElaboratorTemplateInput::CapturedTerm {
                    term: crate::normalization::EvalRef::new(term),
                });
            }
        }
    }
    Ok(ResolvedUserElaboratorCaptures { inputs, imports })
}

fn user_elaborator_semantic_function_type(
    ty: &InternedType,
    span: Span,
    alias_ctx: &AliasCtx<'_, '_>,
) -> Result<(Vec<InternedType>, InternedType), Error> {
    let (unfolded, identity_canonical) = crate::pass::typecheck_core::canonicalize_for_comparison(
        ty.as_type(),
        alias_ctx,
        ty.identity_is_canonical(),
    );
    match unfolded {
        Type::Function { param, ret, .. } => Ok((
            user_elaborator_semantic_value_slot_types(
                InternedType::fresh_with_identity(*param, identity_canonical),
                alias_ctx,
            ),
            InternedType::fresh_with_identity(*ret, identity_canonical),
        )),
        other => Err(Error::type_(
            span,
            format!(
                "user elaborator implementation must be a function, found `{}`",
                display_type(&other)
            ),
        )),
    }
}

fn user_elaborator_semantic_value_slot_types(
    mut param: InternedType,
    alias_ctx: &AliasCtx<'_, '_>,
) -> Vec<InternedType> {
    let mut slots = Vec::new();
    let mut at_root = true;
    loop {
        let (unfolded, identity_canonical) =
            crate::pass::typecheck_core::canonicalize_for_comparison(
                param.as_type(),
                alias_ctx,
                param.identity_is_canonical(),
            );
        match unfolded {
            Type::Unit { .. } if at_root => return slots,
            Type::Product { left, right, .. } => {
                slots.push(InternedType::fresh_with_identity(*left, identity_canonical));
                param = InternedType::fresh_with_identity(*right, identity_canonical);
                at_root = false;
            }
            terminal => {
                slots.push(InternedType::fresh_with_identity(
                    terminal,
                    identity_canonical,
                ));
                return slots;
            }
        }
    }
}

fn check_user_elaborator_param(
    actual: &InternedType,
    expected: &Type,
    span: Span,
    description: &str,
    alias_ctx: &AliasCtx<'_, '_>,
) -> Result<(), Error> {
    if crate::pass::typecheck_core::require_type_equiv_state(
        actual.as_type(),
        expected,
        span,
        alias_ctx,
        actual.identity_is_canonical(),
        false,
    )
    .is_ok()
    {
        Ok(())
    } else {
        Err(Error::type_(
            span,
            format!(
                "user elaborator implementation has `{}` for {description}, but the ABI expects \
                 `{}`",
                display_type(actual.as_type()),
                display_type(expected)
            ),
        ))
    }
}

fn user_elaborator_implementation_type_slot_modes<'m>(
    elaborator: &'m crate::ast::UserElaboratorDef<Lowered>,
    layout: &UserElaboratorSignatureLayout,
    tcx: &mut TypeCtx<'m, '_>,
) -> Result<Vec<UserElaboratorTypeSlotMode>, Error> {
    let span = elaborator.meta.span;
    let refl_type_ty = refl_type("__Type__", span);
    let checked_term_ty = checked_term_type(span);
    let optional_type_ty = optional_type_slot_type(span);
    let alias_ctx = tcx.env.alias_ctx();
    let implementation = &elaborator.implementation;
    #[cfg(test)]
    record_user_elaborator_implementation_synthesis();
    let implementation_synth = synth_path(implementation.segments(), implementation.span(), tcx)?;
    let implementation_leaf = implementation
        .last()
        .expect("the parser emits a nonempty elaborator implementation path");
    <LoweredTyper as crate::pass::typecheck_core::Typer<Lowered>>::record_position_type(
        implementation.span(),
        implementation_synth.ty.clone(),
        tcx,
    );
    if implementation_leaf.span != implementation.span() {
        <LoweredTyper as crate::pass::typecheck_core::Typer<Lowered>>::record_position_type(
            implementation_leaf.span,
            implementation_synth.ty.clone(),
            tcx,
        );
    }
    validate_user_elaborator_implementation_binding(elaborator, tcx)?;
    let implementation_ty = implementation_synth.into_mono_interned()?;
    // The implementation contract is one semantic product packet. Its
    // concrete function value may bind that packet as one value or flatten
    // the product into multiple binders, so stored ABI arity is not the
    // definition-side slot authority.
    let (params, ret) =
        user_elaborator_semantic_function_type(&implementation_ty, span, &alias_ctx)?;
    let capture_spellings = elaborator
        .captures
        .iter()
        .map(classify_user_elaborator_capture)
        .collect::<Result<Vec<_>, _>>()?;
    let fills_schedule = elaborator.schedule == crate::ast::ElaboratorSchedule::Fills;
    let capability_count = if fills_schedule { 2 } else { 1 };
    let expected_param_count = capability_count + capture_spellings.len() + layout.slots.len();
    if params.len() != expected_param_count {
        return Err(Error::type_(
            span,
            format!(
                "user elaborator implementation ABI expects {expected_param_count} value \
                 parameters, but implementation has {}",
                params.len()
            ),
        ));
    }

    let mut param_index = 0usize;
    check_user_elaborator_param(
        &params[param_index],
        &comptime_proof_type(span),
        span,
        "the compile-time proof parameter",
        &alias_ctx,
    )?;
    param_index += 1;

    if fills_schedule {
        check_user_elaborator_param(
            &params[param_index],
            &fill_ctx_type(span),
            span,
            "the fill-context parameter",
            &alias_ctx,
        )?;
        param_index += 1;
    }

    for spelling in capture_spellings {
        let expected = match spelling {
            UserElaboratorCaptureSpelling::Type => refl_type_ty.clone(),
            UserElaboratorCaptureSpelling::Value | UserElaboratorCaptureSpelling::Member => {
                checked_term_ty.clone()
            }
        };
        check_user_elaborator_param(
            &params[param_index],
            &expected,
            span,
            "a capture parameter",
            &alias_ctx,
        )?;
        param_index += 1;
    }

    let mut type_slot_modes = Vec::new();
    for slot in &layout.slots {
        match slot {
            UserElaboratorSignatureSlot::Type { param, .. } => {
                let actual = &params[param_index];
                if crate::pass::typecheck_core::require_type_equiv_state(
                    actual.as_type(),
                    &refl_type_ty,
                    span,
                    &alias_ctx,
                    actual.identity_is_canonical(),
                    false,
                )
                .is_ok()
                {
                    type_slot_modes.push(UserElaboratorTypeSlotMode::Required);
                } else if !fills_schedule
                    && crate::pass::typecheck_core::require_type_equiv_state(
                        actual.as_type(),
                        &optional_type_ty,
                        span,
                        &alias_ctx,
                        actual.identity_is_canonical(),
                        false,
                    )
                    .is_ok()
                {
                    type_slot_modes.push(UserElaboratorTypeSlotMode::Optional);
                } else {
                    let expected = if fills_schedule {
                        "`__Type__`"
                    } else {
                        "either `__Type__` or `__Type__ | .`"
                    };
                    return Err(Error::type_(
                        span,
                        format!(
                            "user elaborator implementation has `{}` for type slot `[{}]`, but \
                             the ABI expects {expected}",
                            display_type(actual.as_type()),
                            param.name
                        ),
                    ));
                }
            }
            UserElaboratorSignatureSlot::Value { .. } => {
                check_user_elaborator_param(
                    &params[param_index],
                    &checked_term_ty,
                    span,
                    "a value slot parameter",
                    &alias_ctx,
                )?;
            }
        }
        param_index += 1;
    }
    let expected_return = if fills_schedule {
        ty_product(checked_term_ty.clone(), fill_ctx_type(span), span)
    } else {
        checked_term_ty
    };
    check_user_elaborator_param(
        &ret,
        &expected_return,
        span,
        "the implementation return type",
        &alias_ctx,
    )?;
    Ok(type_slot_modes)
}

