fn check_user_elaborator_item<'m>(
    elaborator: &'m crate::ast::UserElaboratorDef<Lowered>,
    item_index: usize,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    elaborations: &mut Elaborations,
) -> Result<(), Error> {
    check_well_formed_type(&elaborator.call_ty)?;
    let mut tcx = TypeCtx::new(env, elaborations).at_item(item_index);
    crate::pass::typecheck_core::check_callable_spine_kinds(&elaborator.call_ty, &mut tcx)?;
    let alias_ctx = env.alias_ctx();
    let call_ty = InternedType::fresh(elaborator.call_ty.clone());
    let layout = user_elaborator_signature_layout(&call_ty, &alias_ctx);
    validate_trailing_declaration(elaborator, &layout, &alias_ctx, &tcx)?;
    validate_user_elaborator_capture_source_order(elaborator, item_index, env)?;
    resolve_user_elaborator_captures(elaborator, env, &mut tcx)?;
    tcx.pure_context = true;
    user_elaborator_implementation_type_slot_modes(elaborator, &layout, &mut tcx)?;
    Ok(())
}

#[derive(Default)]
struct CapabilitySignatureUses {
    bound: Vec<String>,
    handle: Option<(crate::comptime::ComptimeBuiltin, Span)>,
    fill_ctx: Option<Span>,
}

fn direct_capability_identity(
    ty: &Type,
    is_bound: impl Fn(&str) -> bool,
) -> Option<crate::comptime::ComptimeBuiltin> {
    let Type::Path { segments, args, .. } = ty else {
        return None;
    };
    let [name] = segments.as_slice() else {
        return None;
    };
    (!is_bound(name.as_str()) && args.is_empty())
        .then(|| crate::comptime::ComptimeBuiltin::from_public_name(name.as_str()))
        .flatten()
        .filter(|builtin| builtin.is_type_name())
}

impl crate::pass::visit_mut::TypecheckVisitMut<Lowered> for CapabilitySignatureUses {
    fn visit_type(&mut self, ty: &mut Type) {
        if let Some(builtin) =
            direct_capability_identity(ty, |name| self.bound.iter().any(|bound| bound == name))
        {
            self.handle.get_or_insert((builtin, ty.span()));
            if builtin == crate::comptime::ComptimeBuiltin::FillCtx {
                self.fill_ctx.get_or_insert(ty.span());
            }
        }
        crate::pass::visit_mut::walk_type(self, ty);
    }

    fn enter_type_binder(&mut self, param: &mut TypeParam, _scope: Span) {
        self.bound.push(param.name.clone());
    }

    fn exit_type_binder(&mut self, param: &mut TypeParam, _scope: Span) {
        debug_assert_eq!(self.bound.pop().as_deref(), Some(param.name.as_str()));
    }
}

impl TyperPhase for Lowered {
    type Elaborations = Elaborations;
    type Typer = LoweredTyper;

    fn merge_elaborations(target: &mut Self::Elaborations, source: Self::Elaborations) {
        target.merge(source);
    }

    fn check_fn_capability_signature<'m>(
        definition: &'m crate::ast::FnDef<Self>,
        tcx: &TypeCtx<'m, '_>,
    ) -> Result<(), Error> {
        if definition.purity != crate::ast::Purity::Pure {
            return Ok(());
        }
        let mut bound = HashSet::new();
        let mut direct = [None; 2];
        let mut value_index = 0;
        let mut imports = CapabilitySignatureUses::default();
        let missing_receiver = |span, used: &str, required: &str, position: &str| {
            Error::type_(
                span,
                format!(
                    "pure function `{}` uses `{used}`, but its {position} value parameter is not exactly `{required}`",
                    definition.name,
                ),
            )
            .with_help(format!("declare a direct `{required}` {position} value parameter"))
        };
        let canonicalize = |ty: &Type, bound: &HashSet<String>| {
            let alias_ctx = AliasCtx {
                binder_locals: Some(bound),
                ..tcx.env.alias_ctx()
            };
            crate::pass::typecheck_core::canonicalize_deep_for_comparison(ty, &alias_ctx, false).0
        };
        for param in &definition.sig.params {
            if value_index == direct.len() {
                break;
            }
            match param {
                crate::ast::SignatureParam::Type(param) => {
                    bound.insert(param.name.clone());
                }
                crate::ast::SignatureParam::Value(param) => {
                    let canonical = canonicalize(
                        param
                            .ty
                            .as_ref()
                            .expect("named function parameters are annotated"),
                        &bound,
                    );
                    direct[value_index] =
                        direct_capability_identity(&canonical, |name| bound.contains(name));
                    value_index += 1;
                }
            }
        }
        let signature = definition
            .sig
            .signature_ty(definition.ret.clone(), definition.meta.span);
        let mut signature = canonicalize(&signature, &HashSet::new());
        crate::pass::visit_mut::TypecheckVisitMut::visit_type(&mut imports, &mut signature);
        if let Some((handle, span)) = imports.handle
            && direct[0] != Some(crate::comptime::ComptimeBuiltin::ComptimeProof)
        {
            return Err(missing_receiver(
                span,
                handle.public_name(),
                "__Comptime__",
                "first",
            ));
        }
        if let Some(span) = imports.fill_ctx
            && direct[1] != Some(crate::comptime::ComptimeBuiltin::FillCtx)
        {
            return Err(missing_receiver(
                span,
                "__Fill_ctx__",
                "__Fill_ctx__",
                "second",
            ));
        }
        Ok(())
    }
}

// =========================================================================
// Public entry point
// =========================================================================

/// Type-check every module in `package`, produce a
/// [`Prime`](crate::ast::Prime)-phase package with the elaborator-position
/// elaborations substituted into the AST in place of the surface
/// `into!` / `onto!` / `match!` nodes, then validate the substituted
/// package with the standalone Kio' typer. Bails on the first error.
///
/// `Package<Prime>` is the semantic contract every backend
/// ultimately realizes: the Prime AST carries no `Expr::Elaborator`
/// / `Expr::UserElaborator` nodes (their extension types are `Never`),
/// so the elaboration the typer recorded lives in-tree rather than
/// in a pointer-keyed side table — the type system enforces the contract.
pub fn check_package(
    package: &Package,
) -> Result<crate::pass::resolve::Package<Prime>, LocatedError> {
    let checked = check_package_preserving_normalization(package)?;
    validate_substituted_package(checked.substituted())
}

pub(crate) fn validate_substituted_package(
    substituted: crate::pass::alpha_normalize::AlphaNormalizedPackage<Prime>,
) -> Result<Package<Prime>, LocatedError> {
    crate::prime::typer::check_normalized_package(substituted)
}

/// A checked Lowered package together with the proof-bearing normalized tree
/// the elaborations were recorded against.
pub(crate) struct CheckedLoweredPackage {
    normalized: crate::pass::alpha_normalize::AlphaNormalizedPackage<Lowered>,
    elaborations: Elaborations,
}

impl CheckedLoweredPackage {
    pub(crate) fn normalized(
        &self,
    ) -> &crate::pass::alpha_normalize::AlphaNormalizedPackage<Lowered> {
        &self.normalized
    }

    #[cfg(any(feature = "cli", test))]
    pub(crate) fn package(&self) -> &Package {
        self.normalized.package()
    }

    #[cfg(any(feature = "cli", test))]
    pub(crate) fn elaborations(&self) -> &Elaborations {
        &self.elaborations
    }

    #[cfg(any(feature = "lsp", test))]
    pub(crate) fn into_elaborations(self) -> Elaborations {
        self.elaborations
    }

    pub(crate) fn substituted(
        &self,
    ) -> crate::pass::alpha_normalize::AlphaNormalizedPackage<Prime> {
        substitute::substitute_normalized_package(self.normalized.clone(), &self.elaborations)
    }

    pub(crate) fn eval_artifact(&self) -> Result<crate::normalization::EvalArtifact, LocatedError> {
        substitute::substitute_package_for_eval(&self.normalized, &self.elaborations)
    }
}

pub(crate) fn check_package_preserving_normalization(
    package: &Package,
) -> Result<CheckedLoweredPackage, LocatedError> {
    check_package_preserving_normalization_collect_errors(package).map_err(|errors| {
        errors
            .into_iter()
            .next()
            .expect("collected package errors are non-empty")
    })
}

pub(crate) fn check_package_preserving_normalization_collect_errors(
    package: &Package,
) -> Result<CheckedLoweredPackage, Vec<LocatedError>> {
    let type_interner = std::sync::Arc::new(crate::pass::typecheck_core::TypeInterner::default());
    check_package_preserving_normalization_with_interner_and_execution(
        package,
        type_interner,
        crate::pass::typecheck_core::TypecheckExecution::AllowParallel,
    )
}

#[cfg(feature = "cli")]
pub(crate) fn check_normalized_package_collect_errors(
    normalized: crate::pass::alpha_normalize::AlphaNormalizedPackage<Lowered>,
) -> Result<CheckedLoweredPackage, Vec<LocatedError>> {
    let typecheck_scope =
        crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
            &normalized,
            std::sync::Arc::new(crate::pass::typecheck_core::TypeInterner::default()),
        );
    check_normalized_package_with_scope_and_execution(
        normalized,
        typecheck_scope,
        crate::pass::typecheck_core::TypecheckExecution::AllowParallel,
    )
}

#[cfg(feature = "lsp")]
pub(crate) fn check_normalized_package_collect_errors_with_scope(
    normalized: crate::pass::alpha_normalize::AlphaNormalizedPackage<Lowered>,
    typecheck_scope: std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
) -> Result<CheckedLoweredPackage, Vec<LocatedError>> {
    check_normalized_package_with_scope_and_execution(
        normalized,
        typecheck_scope,
        crate::pass::typecheck_core::TypecheckExecution::AllowParallel,
    )
}

fn check_package_preserving_normalization_with_interner_and_execution(
    package: &Package,
    type_interner: std::sync::Arc<crate::pass::typecheck_core::TypeInterner<Lowered>>,
    execution: crate::pass::typecheck_core::TypecheckExecution,
) -> Result<CheckedLoweredPackage, Vec<LocatedError>> {
    let normalized = crate::pass::alpha_normalize::normalize_package(package);
    let typecheck_scope =
        crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
            &normalized,
            type_interner,
        );
    check_normalized_package_with_scope_and_execution(normalized, typecheck_scope, execution)
}

fn check_normalized_package_with_scope_and_execution(
    normalized: crate::pass::alpha_normalize::AlphaNormalizedPackage<Lowered>,
    typecheck_scope: std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
    execution: crate::pass::typecheck_core::TypecheckExecution,
) -> Result<CheckedLoweredPackage, Vec<LocatedError>> {
    let mut elaborations = Elaborations::new();
    crate::pass::typecheck_core::check_package_modules_with_typecheck_scope_collect_errors_with_execution(
        normalized.package(),
        &mut elaborations,
        typecheck_scope,
        execution,
    )?;
    elaborations.present_binder_names(normalized.presentation_arc());
    Ok(CheckedLoweredPackage {
        normalized,
        elaborations,
    })
}

#[cfg(feature = "lsp")]
mod presentation;
pub(crate) mod publication;
pub(crate) mod rec_quote;
mod rec_quote_source;
pub use crate::pass::binder_presentation::TypeBinderScope;
pub(crate) use rec_quote::QuotedPublicRecipe;

#[derive(Debug, Default)]
struct RecordedCallPlan {
    splits: Vec<usize>,
    implicit_unit_slots: Vec<usize>,
    residual_eta_type: Option<RecordedTypeResolution>,
}

/// Carries typer-time replacement trees for surface elaboration forms and
/// compiler-private Lowered carriers. Surface forms such as `into!`, `onto!`,
/// and `match!` record the Kio' trees that realize their runtime semantics;
/// `Expr::RecOrder` resolves an explicit recursive-CPS ordering/type-flow
/// direction and records either an ordinary `let` (with its exact binder type
/// retained alongside) or its type-only body. Entries are keyed by [`NodeId`],
/// whether parser- or desugar-issued, and IDs survive `Clone` and phase
/// rebuilds. Pointer-based keying would not survive subtree clones because
/// each clone has a fresh address.
///
/// Also carries the typer's **position-keyed index** for IDE / LSP
/// queries: per-expression synthesized types and per-path-segment
/// resolved binders. See [`PositionIndex`] for the contract — the
/// index is populated on every `synth_expr` / `synth_path` walk so
/// downstream LSP queries (hover, goto-definition, references) can
/// look up "what's at this cursor position" without re-running the
/// typer.
#[derive(Debug, Default)]
pub struct Elaborations {
    /// Sparse, occurrence-keyed public type inventory for recursive quotation.
    /// Entries become readable only when their ordinary publication closes.
    rec_quote: Option<Box<rec_quote::RecQuoteCaptures>>,
    /// Keyed by `(module_path, NodeId)`. A `NodeId` alone is file-local, so the
    /// module-path prefix disambiguates package modules exactly as for the
    /// occurrence-keyed fields below. `NodeId` (not span/pointer) is retained in the
    /// key so it survives the typer's subtree clones.
    entries: HashMap<(String, NodeId), RecordedElaboration>,
    /// Compiler-private recursive-order replacements paired with the exact
    /// binder type that substitution must put on their root `let`. Keeping
    /// these out of [`RecordedElaboration`] preserves that public enum's
    /// surface while retaining the same stable module-and-node identity.
    rec_order_runtime: HashMap<(String, NodeId), RecordedRecOrderRuntime>,
    /// Solved type arguments keyed by the actual call occurrence and canonical
    /// slot. Copied syntax can share a source span while independently checked
    /// instances require different substitutions.
    type_resolutions:
        HashMap<(String, crate::ast::ExpressionOccurrenceId, usize), RecordedTypeResolution>,
    /// `(module_path, call_id, slot_index)` triples where the
    /// user supplied a value-shaped expression at a type-arg slot
    /// (e.g. `nil(B)` where `B` is a tparam, or `List(B) & List(A)`
    /// written without `[…]` brackets). The substitute pass uses
    /// this marker to distinguish "user wrote a value here,
    /// reclassify it" from "user fully elided this type-arg,
    /// insert it" — without the marker, the substitute pass
    /// treats both as the elided case and leaves the value-shaped
    /// expression in place at the next value-arg slot, where
    /// downstream emitters then see an unrecognized callee.
    value_at_type_slot:
        std::collections::HashSet<(String, crate::ast::ExpressionOccurrenceId, usize)>,
    value_at_type_slot_index:
        HashMap<String, HashMap<crate::ast::ExpressionOccurrenceId, Vec<usize>>>,
    /// Canonical argument boundaries and any residual eta plan for one Full
    /// Kio call. Keeping both in one record makes the Lowered → PrePrime
    /// consumer observe exactly the call plan that committed with inference.
    call_plans: HashMap<(String, crate::ast::ExpressionOccurrenceId), RecordedCallPlan>,
    /// The typer's three-tier-resolved host type for each literal,
    /// keyed by `(module_path, literal_id)`. The substitution
    /// pass bakes these into the literal's `annotation` so every
    /// post-`Prime` literal carries its concrete type — `backends::js::emit`
    /// and `backends::kio_prime` then need no resolution of their own.
    literal_resolutions:
        HashMap<(String, crate::ast::ExpressionOccurrenceId), RecordedTypeResolution>,
    /// Checked value-parameter types for `Expr::FnExpr` nodes. These
    /// are needed when a lambda was checked against a call-site
    /// expected function type and its parameter type is not recoverable
    /// from the lambda body alone.
    fn_param_types:
        HashMap<(String, crate::ast::ExpressionOccurrenceId, usize), RecordedTypeResolution>,
    generated_imports: HashMap<String, Vec<UserElaboratorTemplateGeneratedImport>>,
    prime_requalification_imports: HashMap<String, Vec<UserElaboratorTemplateGeneratedImport>>,
    generated_type_aliases: HashMap<String, Vec<PrimeLocalTypeAlias>>,
    /// Position-keyed index of the typer's output — per-expression
    /// synthesized types and per-path-segment resolved binders.
    /// Populated by the `Typer<Lowered>` impl on every `synth_expr`
    /// return and by `synth_path` on every binder resolution. The
    /// LSP consumes this to answer hover / goto-definition / references queries
    /// without re-running the typer. See [`PositionIndex`] for the data shape
    /// and the merge / disjointness contract.
    position_index: PositionIndex,
    /// **Deferred-elaboration queue.** A closed-result user elaborator can
    /// leave glue production until the module boundary: its ordinary call
    /// plan already fixes the result type, and the queued obligation later
    /// runs the elaborator and checks its returned term against that type.
    /// A type-producing elaborator instead runs while its application frontier
    /// is live; the returned checked term constrains that owner's output goal,
    /// and its already-computed template is queued only for uniform recording.
    /// Draining happens in [`Self::discharge_deferred`] while the module's alias
    /// context remains available, and records each resulting Kio' tree into
    /// `entries` for the Lowered → Prime substitution pass.
    ///
    /// The queue is keyed by `(elaborator name, reified source, reified
    /// target)` so structurally identical obligations are comparable
    /// across sites before glue production.
    deferred: Vec<DeferredElaboration>,
}

#[derive(Debug, Clone)]
pub enum RecordedElaboration {
    Lowered(Expr),
    UncheckedPrime(UncheckedPrimeExpr),
}

#[derive(Debug)]
struct RecordedRecOrderRuntime {
    replacement: Expr,
    binding_type: RecordedTypeResolution,
}

/// A single deferred elaboration obligation. Closed-result obligations carry
/// the result type against which discharge checks the elaborator's returned
/// term. Type-producing obligations carry a template already evaluated on the
/// live application frontier, where that returned term constrained the output
/// goal; discharge reuses the template without running the elaborator again.
///
/// Owned (not borrowed): the discharge runs after the per-fn-body typer
/// borrows have dropped, so `value` is a clone of the elaborator's inner
/// expression and the types are owned. The clone shares `NodeId`s with
/// the original (the parser issues them and they survive `Clone`), so
/// the elaboration the discharge records under `node_id` lands on the
/// surface node the `substitute` pass looks up.
#[derive(Debug)]
enum DeferredElaboration {
    UserElaborator(Box<DeferredUserElaboratorElaboration>),
}

#[derive(Debug)]
pub(crate) struct DeferredUserElaboratorElaboration {
    node_id: NodeId,
    name: String,
    elaborator_module_path: Option<String>,
    values: Vec<Expr>,
    abi_inputs: Vec<UserElaboratorTemplateInput>,
    input_keys: Vec<UserElaboratorTemplateInputKey>,
    capture_imports: Vec<UserElaboratorTemplateGeneratedImport>,
    value_adapter: crate::normalization::CheckedTermTemplateValueAdapter,
    residual_abstraction: crate::pass::substitute::EtaPlan<UncheckedPrime>,
    ambient_type_names: HashSet<String>,
    result_ty: Option<InternedType>,
    precomputed_template: Option<UserElaboratorTemplateResult>,
    quoted_public_recipe: Option<Box<QuotedPublicRecipe>>,
    span: Span,
}

