    #[test]
    fn recursive_quotation_storage_stays_absent_for_ordinary_elaborators() {
        let package = lowered_package(&[
            ("elab.kio", "module elab; import __comptime__;
             pure fn identity_impl(_ct: __Comptime__, _ty: __Type__, value: __Checked_term__) -> __Checked_term__ { value }
             pub elab identity : [A] A -> A { impl identity_impl }"),
            ("main.kio", "module main; import elab(identity);
             fn id[A](value: A) -> A { value }
             fn run() -> . { let value = identity!(id(())); value }"),
        ]);
        let checked = check_package_preserving_normalization(&package).unwrap();
        assert!(checked.elaborations.rec_quote.is_none());
        eprintln!(
            "quotation layout: elaborations={}, deferred={}, optional_inventory={}, optional_recipe={}",
            std::mem::size_of::<Elaborations>(),
            std::mem::size_of::<DeferredUserElaboratorElaboration>(),
            std::mem::size_of::<Option<Box<rec_quote::RecQuoteCaptures>>>(),
            std::mem::size_of::<Option<Box<QuotedPublicRecipe>>>()
        );
        validate_substituted_package(checked.substituted()).unwrap();
    }

    #[test]
    fn recursive_quotation_order_replay_uses_recorded_disposition_iteratively() {
        std::thread::Builder::new()
            .stack_size(8 * 1024 * 1024)
            .spawn(run_recursive_quotation_order_replay)
            .unwrap()
            .join()
            .unwrap();
    }

    fn run_recursive_quotation_order_replay() {
        use crate::ast::{ExpressionOccurrence, RecQuotePlan};
        // This consumer fixture supplies completed dispositions directly;
        // retained-source inference is covered independently.
        let module = module("module main; host fn suspended(k: . -> .) -> .;");
        let env = ModuleEnv::build(&module, None, None, None).unwrap();
        let span = Span::new(0, 0);
        let unit_ty = || Type::Unit {
            meta: Meta::new(span),
        };
        for runtime_binding in [false, true] {
            for depth in [1, 16, 256] {
                let mut source = Expr::RecQuote {
                    occurrence: ExpressionOccurrence::fresh(),
                    plan: Box::new(RecQuotePlan::Operand {
                        public_ty: Some(unit_ty()),
                        runtime_ty: unit_ty(),
                        computation: Box::new(Expr::Path {
                            occurrence: ExpressionOccurrence::fresh(),
                            segments: vec![PathSegment::new("suspended", span)],
                            meta: Meta::new(span),
                            ext: (),
                        }),
                    }),
                    meta: Meta::new(span),
                    ext: NodeId(1000),
                };
                let mut elaborations = Elaborations::new();
                let mut captured = vec![source.site().id];
                for index in 0..depth {
                    let value = Expr::Unit {
                        occurrence: ExpressionOccurrence::fresh(),
                        meta: Meta::new(span),
                    };
                    captured.push(value.site().id);
                    let name = format!("saved{index}");
                    let replacement = if runtime_binding {
                        Expr::Let {
                            occurrence: ExpressionOccurrence::fresh(),
                            name: name.clone(),
                            name_span: span,
                            ty: None,
                            pattern: (),
                            value: Box::new(value.clone()),
                            body: Box::new(source.clone()),
                            meta: Meta::new(span),
                        }
                    } else {
                        source.clone()
                    };
                    source = Expr::RecOrder {
                        occurrence: ExpressionOccurrence::fresh(),
                        plan: Box::new(RecOrderPlan {
                            tail_continuation: None,
                            name,
                            disposition: RecOrderDisposition::Ordered(if runtime_binding {
                                RecOrderTypeFlow::SynthesizedValue
                            } else {
                                RecOrderTypeFlow::ExpectedFromBody
                            }),
                            annotation: None,
                            value: Box::new(value),
                            body: Box::new(source),
                            runtime_ty: unit_ty(),
                        }),
                        meta: Meta::new(span),
                        ext: NodeId(1001 + index),
                    };
                    captured.push(source.site().id);
                    if runtime_binding {
                        elaborations.record_rec_order_elaboration(
                            "main",
                            &source,
                            replacement,
                            InternedType::fresh_canonical(unit_ty()),
                        );
                    } else {
                        elaborations.record_elaboration("main", &source, replacement);
                    }
                }
                elaborations.register_rec_quote_sources(&source);
                for id in captured {
                    elaborations
                        .record_rec_quote_source_type(id, InternedType::fresh_canonical(unit_ty()));
                }
                let mut replay = UserElaboratorReplayEnv {
                    module_path: "main",
                    module: &module,
                    elaborations: &mut elaborations,
                    package: None,
                    memo: &env.memo,
                };
                let result = rec_quote_source::compose(
                    &source,
                    &crate::ast::convert_type::<Lowered, crate::pass::substitute::PrePrime>(
                        &unit_ty(),
                    ),
                    &HashSet::new(),
                    &mut replay,
                )
                .unwrap()
                .expect("suspension survives");
                let mut pending = vec![&result];
                let (mut bindings, mut callbacks, mut suspensions) = (0, 0, 0);
                while let Some(node) = pending.pop() {
                    match node {
                        crate::ast::Expr::Let {
                            name, value, body, ..
                        } => {
                            assert!(name.starts_with("saved"));
                            bindings += 1;
                            pending.extend([value.as_ref(), body.as_ref()]);
                        }
                        crate::ast::Expr::FnExpr { body, .. } => {
                            callbacks += 1;
                            pending.push(body);
                        }
                        crate::ast::Expr::Call { callee, args, .. } => {
                            pending.push(callee);
                            for arg in args {
                                if let crate::ast::CallArg::Value(value) = arg {
                                    pending.push(value);
                                }
                            }
                        }
                        crate::ast::Expr::Path { segments, .. } => {
                            suspensions += usize::from(segments[0].as_str() == "suspended");
                        }
                        _ => {}
                    }
                }
                assert_eq!(bindings, if runtime_binding { depth } else { 0 });
                assert_eq!(
                    callbacks,
                    if runtime_binding { depth } else { 0 },
                    "runtime bindings compose once; type-only ordering is erased"
                );
                assert_eq!(
                    suspensions, 1,
                    "composition never duplicates the suspended source"
                );
            }
        }
    }

    fn module_file_path_from_parsed<P: crate::ast::Phase>(
        module: &crate::ast::Module<P>,
    ) -> PathBuf {
        let mut path = PathBuf::new();
        let segs = &module.path.segments;
        for seg in &segs[..segs.len().saturating_sub(1)] {
            path.push(&seg.name);
        }
        let stem = segs.last().map(|seg| seg.name.as_str()).unwrap_or("module");
        path.push(format!("{stem}.kio"));
        path
    }

    fn parse_package_entry(src: &str) -> (PathBuf, crate::ast::Module<crate::ast::Surface>) {
        let parsed = parse(src).expect("parse");
        let path = module_file_path_from_parsed(&parsed);
        (path, parsed)
    }

    #[cfg(feature = "prime")]
    fn prime_package(src: &str) -> Package<Prime> {
        let parsed = parse(src).expect("parse");
        let prime = crate::prime::lower::lower_module(parsed).expect("prime lower");
        let path = module_file_path_from_parsed(&prime);
        let package =
            Package::build(Path::new(""), vec![(path, prime)], None).expect("Package::build");
        package.resolve_imports().expect("resolve imports");
        package.check_no_value_cycles().expect("cycle check");
        package.check_in_body_resolution().expect("body resolution");
        package
    }

