    #[test]
    fn ordinary_optional_rec_callback_legacy_routes_publish_only_success() {
        use crate::ast::{ExpressionOccurrence, RecOrderTailRequirement};
        let module = module(
            "module main;
            host fn make[A]() -> A;
            fn contextual() -> . { make() }
            fn ordinary() -> . { () }",
        );
        let normalized = crate::pass::alpha_normalize::normalize_module(&module);
        let module = normalized.module();
        let env = ModuleEnv::build(module, None, None, None).unwrap();
        let span = Span::new(0, 0);
        for contextual in [false, true] {
            let name = if contextual { "contextual" } else { "ordinary" };
            let value = module
                .items
                .iter()
                .find_map(|item| match item {
                    Item::FnDef(def) if def.name == name => Some(def.body.clone()),
                    _ => None,
                })
                .unwrap();
            for requirement in [
                RecOrderTailRequirement::Optional,
                RecOrderTailRequirement::Required,
            ] {
                // A consumer fixture: the body is deliberately unusable so only
                // successful ordinary bypass may publish its original value.
                let source = Expr::RecOrder {
                    occurrence: ExpressionOccurrence::fresh(),
                    plan: Box::new(RecOrderPlan {
                        tail_continuation: None,
                        name: "__rec_tail_value_test__".into(),
                        disposition: RecOrderDisposition::DeferredTail {
                            requirement,
                            lifted_flow: RecOrderTypeFlow::ExpectedFromBody,
                        },
                        annotation: None,
                        value: Box::new(value.clone()),
                        body: Box::new(Expr::Path {
                            occurrence: ExpressionOccurrence::fresh(),
                            segments: vec![PathSegment::new("must_not_check", span)],
                            meta: Meta::new(span),
                            ext: (),
                        }),
                        runtime_ty: Type::Unit {
                            meta: Meta::new(span),
                        },
                    }),
                    meta: Meta::new(span),
                    ext: NodeId(900_000),
                };
                let mut elaborations = Elaborations::new();
                let mut tcx = TypeCtx::new(&env, &mut elaborations);
                let result = if contextual {
                    let expected = tcx.intern_type(&Type::Unit {
                        meta: Meta::new(span),
                    });
                    check_value_against(&source, &expected, &mut tcx)
                } else {
                    synth_expr(&source, &mut tcx).map(|_| ())
                };
                if requirement == RecOrderTailRequirement::Optional {
                    result.expect("both legacy routes consume an optional ordinary value");
                    assert!(elaborations.elaboration_for("main", &source).is_some());
                } else {
                    assert!(matches!(result, Err(Error::Parse(_))), "{result:?}");
                    assert!(elaborations.elaboration_for("main", &source).is_none());
                }
            }
        }
    }

    #[test]
    fn fills_recursive_recipe_applies_the_outer_continuation_to_an_ordinary_tail() {
        let elaborator = "module elab; import __comptime__; \
            pure fn select_impl(ct: __Comptime__, fills: __Fill_ctx__, \
                _condition_type: __Type__, result_type: __Type__, condition: __Checked_term__, \
                callback: __Checked_term__, fallback: __Checked_term__) -> __Checked_term__ & __Fill_ctx__ { \
                let result = __term_call__(ct, __term_type__(ct, callback), callback, __term_unit__(ct)); \
                let fills = __fill__(ct, fills, result_type, __term_type__(ct, result)); \
                (__intrinsic_if_then_else__(ct, result_type, condition, \
                    .() -> __Checked_term__ { result }, .() -> __Checked_term__ { fallback }), fills) \
            } \
            pub elab select : [Condition][Result] Condition -> (. -> Result) -> Result -> Result { impl(fills) select_impl }";
        let main = "module main; import elab(select); \
            host type Bool role(bool); \
            host fn loop[S][R](step: S -> (S | R), initial: S) -> R; \
            newtype Box[A] : A { constructor box; projector unbox; }; \
            rec(loop) fn go(condition: Bool) -> . { \
                Box.unbox(select!(condition, .() { \
                    let next = rec(cont) go(condition); Box.box(next) \
                }, Box.box(()))) \
            }";
        let package = lowered_package(&[("elab.kio", elaborator), ("main.kio", main)]);
        let (checked, scope) = check_retained_success(&package);
        assert_eq!(scope.memo().user_elaborator_template_executions(), 1);
        validate_substituted_package(checked.substituted())
            .expect("ordinary tail uses its continuation");
    }

