    #[test]
    fn sequence_recipe_failed_root_rolls_back_replacements_and_call_facts() {
        for invalid in [true, false] {
            let output = if invalid { "Other" } else { "Box" };
            let package = lowered_elab_package(&format!("module main;
                import sequence(do);
                newtype Box[A] : A {{ constructor box; projector unbox; }};
                newtype Other[A] : A {{ constructor box; projector unbox; }};
                fn good[A][B](input: Box(A), next: A -> Box(B)) -> Box(B) {{ next(Box.unbox(input)) }}
                fn second[A][B](input: Box(A), next: A -> {output}(B)) -> {output}(B) {{ next(Box.unbox(input)) }}
                fn collect(_first: Box(.), _second: {output}(.)) -> . {{ () }}
                fn run() -> . {{ collect(
                    do! good {{ let x <- Box.box(()); Box.box(x) }},
                    do! second {{ let x <- Box.box(()); {output}.box(x) }}
                ) }}")).expect("lower ordinary sequence package");
            let normalized = crate::pass::alpha_normalize::normalize_package(&package);
            let scope =
                crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                    &normalized,
                    std::sync::Arc::new(crate::pass::typecheck_core::TypeInterner::default()),
                );
            let module = &normalized.package().module("main").expect("main").module;
            let env = ModuleEnv::build_with_typecheck_scope(
                module,
                None,
                None,
                Some(normalized.package()),
                scope,
            )
            .expect("env");
            let run = module
                .items
                .iter()
                .find_map(|item| match item {
                    Item::FnDef(def) if def.name == "run" => Some(def),
                    _ => None,
                })
                .expect("run");
            let mut elabs = Elaborations::new();
            let mut tcx = TypeCtx::new(&env, &mut elabs);
            let result = synth_expr(&run.body, &mut tcx);
            if invalid {
                assert_eq!(
                    result.err().expect("invalid receiver").diag().1,
                    "a sequence block requires an ordinary `Bind(F) -> F(R)` value slot"
                );
                assert!(elabs.entries.is_empty());
                assert!(elabs.type_resolutions.is_empty());
                assert!(elabs.value_at_type_slot.is_empty());
                assert!(elabs.call_plans.is_empty());
                assert!(elabs.literal_resolutions.is_empty());
                assert!(elabs.fn_param_types.is_empty());
                assert!(elabs.deferred.is_empty());
                assert!(
                    elabs
                        .position_index
                        .types
                        .keys()
                        .all(|(module, _)| module != "main"),
                    "a failed root must not publish its caller's position types"
                );
            } else {
                result.expect("same-container control");
                elabs
                    .discharge_deferred(&env)
                    .expect("publish successful recipes");
                assert!(!elabs.type_resolutions.is_empty());
                assert!(!elabs.fn_param_types.is_empty());
                let Expr::Call { args, .. } = &run.body else {
                    panic!("collect")
                };
                let CallArg::Value(scope) = &args[0] else {
                    panic!("scope")
                };
                let retained = scope.clone();
                assert_eq!(scope.site().id, retained.site().id);
                assert!(elabs.elaboration_for("main", &retained).is_some());
                let CallArg::Value(other_scope) = &args[1] else {
                    panic!("second scope")
                };
                assert_ne!(elaboration_node_id(scope), elaboration_node_id(other_scope));
                assert!(elabs.elaboration_for("main", other_scope).is_some());
                assert!(elabs.elaboration_for("other_module", &retained).is_none());
            }
        }
    }

    fn type_diag(src: &str) -> Diagnostic {
        let result = if source_imports_control_support(src) {
            check_package_sources(&[src])
        } else if source_uses_imported_elaborator(src) {
            check_elab_src(src)
        } else {
            check_module(&module(src))
        };
        match result {
            Err(Error::Type(diagnostic)) => diagnostic,
            Err(other) => panic!("expected Error::Type, got {other:?}"),
            Ok(()) => panic!("expected type error"),
        }
    }

    fn err(src: &str) -> String {
        type_diag(src).message
    }

    fn package_type_err(sources: &[&str]) -> String {
        match check_package_sources(sources) {
            Err(Error::Type(Diagnostic { message, .. })) => message,
            Err(other) => panic!("expected Error::Type, got {other:?}"),
            Ok(()) => panic!("expected type error"),
        }
    }

    fn name_err(src: &str) -> String {
        match check_module(&module(src)) {
            Err(Error::NameRes(Diagnostic { message, .. })) => message,
            Err(other) => panic!("expected Error::NameRes, got {other:?}"),
            Ok(()) => panic!("expected name-resolution error"),
        }
    }

    fn capture_source_order_err(src: &str) -> String {
        match capture_source_order_check(&[src], "x") {
            Err(Error::NameRes(Diagnostic { message, .. })) => message,
            Err(other) => panic!("expected Error::NameRes, got {other:?}"),
            Ok(()) => panic!("expected name-resolution error"),
        }
    }

    fn capture_source_order_check(sources: &[&str], module_name: &str) -> Result<(), Error> {
        let modules = sources
            .iter()
            .map(|source| {
                let module = lowered_module(source);
                (module_file_path_from_parsed(&module), module)
            })
            .collect();
        let package = Package::build(Path::new(""), modules, None).expect("package builds");
        package.resolve_imports().expect("uses resolve");
        let module = &package
            .module(module_name)
            .unwrap_or_else(|| panic!("{module_name} module"))
            .module;
        let env = crate::pass::typecheck_core::ModuleEnv::build(module, None, None, Some(&package))
            .expect("module environment");
        let (item_index, elaborator) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::Elaborator(elaborator, _) => Some((index, elaborator)),
                _ => None,
            })
            .expect("one elaborator");
        validate_user_elaborator_capture_source_order(elaborator, item_index, &env)
    }

