    #[test]
    fn unchecked_prime_recorded_elaboration_substitutes_to_prime() {
        let span = test_span();
        let node_id = NodeId(42);
        let original = Expr::UserElaborator {
            occurrence: Default::default(),
            form: crate::ast::UserElaboratorCallForm::Ordinary,
            name: "demo".to_owned(),
            args: Vec::new(),
            meta: Meta::new(span),
            ext: node_id,
        };
        let replay = crate::ast::Expr::<UncheckedPrime>::Unit {
            occurrence: Default::default(),
            meta: Meta::new(span),
        };
        let mut module = module("module x; fn replay() -> . { () }");
        let def = module
            .items
            .iter_mut()
            .find_map(|item| match item {
                crate::ast::Item::FnDef(def) if def.name == "replay" => Some(def),
                _ => None,
            })
            .expect("replay fn");
        def.body = original;
        let mut elaborations = Elaborations::new();
        elaborations.record_unchecked_prime_elaboration("x", node_id, replay);

        let prime = crate::pass::substitute::substitute_module(&module, &elaborations);

        let body = prime
            .items
            .iter()
            .find_map(|item| match item {
                crate::ast::Item::FnDef(def) if def.name == "replay" => Some(&def.body),
                _ => None,
            })
            .expect("replay fn");
        assert!(matches!(body, crate::ast::Expr::Unit { .. }));
    }

