    #[test]
    fn monadic_receiver_instances_keep_distinct_inferred_types() {
        use crate::pass::visit_mut::{TypecheckVisitMut, walk_expr};

        #[derive(Default)]
        struct ProjectorSites(Vec<crate::ast::ExpressionSite>);
        impl TypecheckVisitMut<Lowered> for ProjectorSites {
            fn visit_expr(&mut self, expr: &mut Expr) {
                if let Expr::Call { callee, .. } = expr
                    && let Expr::Path { segments, .. } = callee.as_ref()
                    && segments
                        .last()
                        .is_some_and(|segment| segment.name == "unbox")
                {
                    self.0.push(expr.site());
                }
                walk_expr(self, expr);
            }
        }

        let source = r#"module main; import sequence(do);
newtype Left : . { constructor left; projector unleft; };
newtype Right : . { constructor right; projector unright; };
newtype Box[A] : A { constructor box; projector unbox; };
fn pure[A](value: A) -> Box(A) { Box.box(value) }
fn run[A](first: Left, second: Right) -> Box(Right) {
  do! (.[A][B](value: Box(A), next: A -> Box(B)) -> Box(B) {
    next(Box.unbox(value))
  }) {
    let first_value <- pure(first);
    let second_value <- pure(second);
    pure(second_value)
  }
}
"#;
        let package = lowered_package(&[("main.kio", source)]);
        let checked = check_package_preserving_normalization(&package)
            .expect("explicit polymorphic receiver checks in each lexical context");
        let mut sites = ProjectorSites::default();
        sites.visit_package(&mut checked.normalized().package().clone());
        let [receiver] = sites.0.as_slice() else {
            panic!("the receiver expression is checked once");
        };
        checked
            .elaborations()
            .type_resolution_for("main", receiver.id, 0)
            .expect("the one polymorphic receiver retains its projector fact");

        #[derive(Default)]
        struct BindCalls(Vec<(Vec<crate::ast::PathSegment>, Vec<crate::ast::Type<Prime>>)>);
        impl TypecheckVisitMut<Prime> for BindCalls {
            fn visit_expr(&mut self, expr: &mut crate::ast::Expr<Prime>) {
                if let crate::ast::Expr::Call { callee, args, .. } = expr
                    && let crate::ast::Expr::Path { segments, .. } = callee.as_ref()
                {
                    let types = args
                        .iter()
                        .filter_map(|arg| match arg {
                            crate::ast::CallArg::Type(ty) => Some(ty.clone()),
                            crate::ast::CallArg::Value(_) => None,
                        })
                        .collect::<Vec<_>>();
                    if types.len() == 2 {
                        self.0.push((segments.clone(), types));
                    }
                }
                walk_expr(self, expr);
            }
        }
        let mut prime = checked
            .substituted()
            .package()
            .module("main")
            .expect("main survives")
            .module
            .clone();
        let mut calls = BindCalls::default();
        calls.visit_module(&mut prime);
        let [first, second] = calls.0.as_slice() else {
            panic!("two bind steps specialize the one receiver: {:?}", calls.0);
        };
        assert_eq!(
            first.0, second.0,
            "both calls use the same lexical receiver"
        );
        assert_ne!(
            first.1[0], second.1[0],
            "the input types remain independent"
        );
        assert_eq!(first.1[1], second.1[1], "both continuations return Right");
        for (ty, name) in [
            (&first.1[0], "Left"),
            (&second.1[0], "Right"),
            (&first.1[1], "Right"),
        ] {
            assert!(matches!(ty, crate::ast::Type::Path { segments, .. }
                if segments.last().is_some_and(|segment| segment.as_str() == name)));
        }
        validate_substituted_package(checked.substituted())
            .expect("substitution preserves each bind call's checked type arguments");
    }

    #[test]
    fn monadic_bind_types_remain_independent_across_phases() {
        for body in [
            "do! bind {
                let first_value <- pure(first);
                let second_value <- pure(second);
                pure(second_value)
            }",
            "do! bind {
                pure(());
                let first_value <- pure(first);
                pure(());
                let second_value <- pure(second);
                pure(second_value)
            }",
            "do! bind {
                let first_value <- do! bind {
                    pure(());
                    let value <- pure(first);
                    pure(value)
                };
                let second_value <- pure(second);
                pure(second_value)
            }",
            "bind(pure(first), .(first_value: Left) {
                bind(pure(second), .(second_value: Right) { pure(second_value) })
            })",
        ] {
            let source = "module main; import sequence(do);
            newtype Left : . { constructor left; projector unleft; };
            newtype Right : . { constructor right; projector unright; };
            newtype Box[A] : A { constructor box; projector unbox; };
            fn pure[A](value: A) -> Box(A) { Box.box(value) }
            fn bind[A][B](value: Box(A), next: A -> Box(B)) -> Box(B) {
                next(Box.unbox(value))
            }
            fn run(first: Left, second: Right) -> Box(Right) { BODY }"
                .replace("BODY", body);
            let package = lowered_package(&[("main.kio", &source)]);
            let checked = check_package_preserving_normalization(&package)
                .unwrap_or_else(|error| panic!("Lowered rejected {body}: {error:?}"));
            validate_substituted_package(checked.substituted())
                .unwrap_or_else(|error| panic!("Prime rejected {body}: {error:?}"));
        }
    }

    #[test]
    fn monadic_polymorphic_receiver_and_ordinary_lambda_calls() {
        for (receiver, first, second, final_expr, result, typed_continuations) in [
            (
                ".[A][B](value: Box(A), next: A -> Box(B)) -> Box(B) { next(Box.unbox(value)) }",
                "pure(first)",
                "pure(second)",
                "pure(second_value)",
                "Box(Right)",
                false,
            ),
            (
                ".(value, next) { next(value) }",
                "first",
                "second",
                "second_value",
                "Right",
                false,
            ),
            (
                ".(value, next) { next(value) }",
                "first",
                "second",
                "second_value",
                "Right",
                true,
            ),
        ] {
            let (first_let, second_let, first_param, second_param) = if typed_continuations {
                (
                    ".(first_value: Left)",
                    ".(second_value: Right)",
                    "first_value: Left",
                    "second_value: Right",
                )
            } else {
                ("first_value", "second_value", "first_value", "second_value")
            };
            let mut bodies = vec![format!(
                "({receiver})({first}, .({first_param}) {{ ({receiver})({second}, .({second_param}) {{ {final_expr} }}) }})"
            )];
            if result == "Box(Right)" {
                bodies.push(format!("do! ({receiver}) {{ let {first_let} <- {first}; let {second_let} <- {second}; {final_expr} }}"));
            }
            for body in bodies {
                let source = "module main; import sequence(do);
                    newtype Left : . { constructor left; projector unleft; };
                    newtype Right : . { constructor right; projector unright; };
                    newtype Box[A] : A { constructor box; projector unbox; };
                    fn pure[A](value: A) -> Box(A) { Box.box(value) }
                    fn run(first: Left, second: Right) -> RESULT { BODY }"
                    .replace("RESULT", result)
                    .replace("BODY", &body);
                let package = lowered_package(&[("main.kio", &source)]);
                if result == "Right" && !typed_continuations {
                    let error = check_package_preserving_normalization(&package)
                        .err()
                        .expect("untyped continuations lack independent parameter types");
                    assert!(
                        error
                            .error
                            .diagnostic()
                            .message
                            .contains("cannot synthesize the type of `fn` parameter `first_value`")
                    );
                } else {
                    let checked = check_package_preserving_normalization(&package)
                        .unwrap_or_else(|error| panic!("Lowered rejected {body}: {error:?}"));
                    validate_substituted_package(checked.substituted())
                        .unwrap_or_else(|error| panic!("Prime rejected {body}: {error:?}"));
                }
            }
        }
    }

    #[test]
    fn explicit_nominal_type_argument_keeps_callee_binder_local_across_phases() {
        let source = "module pkg/provider;\n\
            pub newtype Token : . { pub constructor mk; pub projector get; };\n\
            type Alias = Token;\n\
            newtype Carrier : Token { constructor pack; projector unpack; };\n\
            type Pair = Token & Token;\n\
            type Choice = Token | .;\n\
            type Applied[A] = A;\n\
            type Nested = Applied(Token);\n\
            type Transform = Token -> Token;\n\
            type Scheme = [A] A -> Token;\n\
            type Shadow = [Token] Token -> Token;\n\
            fn identity(value: Token) -> Token { let .(local: Token) = value; local }\n\
            fn closure() -> Token -> Token { .(input: Token) { input } }\n\
            fn generic[Token](value: Token) -> Token { value }\n\
            fn make() -> Token { Token.mk(()) }\n\
            fn project(value: Token) -> . { Token.get(value) }\n\
            fn explicit(value: Token) -> Token { generic(Token, value) }\n";
        let (modules, package_file) =
            FullPipeline::lower_package(vec![parse_package_entry(source)], None)
                .expect("lower the ordinary nominal application");
        assert!(package_file.is_none());
        let package = Package::build(Path::new(""), modules, None).expect("build package");
        package.resolve_imports().expect("resolve package uses");
        let checked = check_package_preserving_normalization(&package)
            .unwrap_or_else(|error| panic!("Lowered checking rejected the application: {error:?}"));
        eprintln!("Lowered checking accepted the nominal application");
        match validate_substituted_package(checked.substituted()) {
            Ok(_) => eprintln!("standalone Prime accepted the nominal application"),
            Err(error) => {
                let span = error.error.diagnostic().span;
                panic!(
                    "standalone Prime rejected the application at {}..{} ({:?}): {error:?}",
                    span.start,
                    span.end,
                    source.get(span.start as usize..span.end as usize)
                );
            }
        }
    }

    #[test]
    fn callee_binder_scope_preserves_caller_binders_and_nominal_mismatches() {
        for callee in ["Token", "A"] {
            let source = format!(
                "module x;
                 newtype Token : . {{ constructor mk; projector get; }};
                 fn generic[{callee}](value: {callee}) -> {callee} {{ value }}
                 fn caller[Token](value: Token) -> Token {{ generic(Token, value) }}"
            );
            let package = lowered_package(&[("x.kio", &source)]);
            let checked = check_package_preserving_normalization(&package)
                .expect("the caller's real type binder remains lexical");
            validate_substituted_package(checked.substituted())
                .expect("standalone Prime preserves the caller's real type binder");
        }
        let source = "module x;
            newtype Token : . { constructor mk; projector get; };
            newtype Other : . { constructor mk_other; projector get_other; };
            fn generic[Token](value: Token) -> Token { value }
            fn mismatch(value: Other) -> Token { generic(Token, value) }";
        let diagnostic = type_diag(source);
        assert!(diagnostic.message.contains("type mismatch"));
        assert!(diagnostic.message.contains("Token"));
        assert!(diagnostic.message.contains("Other"));
        assert_eq!(
            source.get(diagnostic.span.start as usize..diagnostic.span.end as usize),
            Some("value")
        );
    }

