    #[test]
    fn fn_expression_returning_unit() {
        // The declared `. -> .` flows into the lambda parameter and
        // body.
        ok("module x; \
            fn make() -> (. -> .) { .(x) { x } } \
            fn use_it() -> . { make()(()) }");
    }

    #[test]
    fn fn_body_type_mismatch_errors() {
        // The fn promises `. -> Foo` but the body is the
        // identity, returning the parameter (a `.`). The expected
        // parameter slot makes the body's synthesized type `.`, which the
        // require_type_equiv against `Foo` rejects.
        let msg = err("module x; \
                       newtype Foo : . { pub constructor mk_foo; pub projector foo; };\
                       fn make() -> (. -> Foo) { .(x) { x } }");
        assert!(msg.contains("type mismatch"), "got: {msg}");
    }

    #[test]
    fn fn_in_let_rhs_without_use_site_is_ambiguous() {
        // The let RHS is synthesized standalone. With no parameter
        // annotation or immediate call, `a` has no type before the
        // body is visited.
        let msg = err("module x; \
             host type String role(str); host fn print(s: String) -> .; \
             fn run() -> . { let f = .(a) { a }; print(f(\"hi\")) }");
        assert!(
            msg.contains("cannot infer")
                || msg.contains("cannot synthesize")
                || msg.contains("ambiguous"),
            "got: {msg}"
        );
    }

    // ---- Deferred constructs surface clear errors ----------------------

    #[test]
    fn literal_without_role_in_scope_errors() {
        // A bare literal with no annotation and no expected type
        // resolves via tier 3 — the current root's unique role-admitted
        // host type. With no root env at all, there is no
        // candidate, so the typer errors.
        let msg = err("module x; fn f() -> . { \"hi\" }");
        assert!(msg.contains("string literal has no type"), "got: {msg}");
    }

    #[test]
    fn string_literal_typed_against_role_str() {
        // With `role(str) String` in the host, a string
        // literal types as String.
        let m = module(
            "module main; \
             host type String role(str); \
             fn echo(x: String) -> String { x } \
             fn use_lit() -> String { \"hi\" }",
        );
        check_module(&m).unwrap();
    }

    #[test]
    fn int_literal_typed_against_role_i32() {
        // A bare integer literal resolves to the root host's unique
        // int-admitted host type (tier 3).
        let m = module(
            "module main; \
             host type I32 role(i32); \
             fn use_lit() -> I32 { 42 }",
        );
        check_module(&m).unwrap();
    }

    #[test]
    fn literal_annotation_to_non_admitting_role_errors() {
        // A float literal explicitly annotated with an int-shaped
        // role: the literal's shape does not admit that role, so the
        // tier-1 annotation check errors.
        let m = module(
            "module main; \
             host type I32 role(i32); \
             fn use_lit() -> I32 { 3.14(I32) }",
        );
        let res = check_module(&m);
        match res {
            Err(Error::Type(Diagnostic { message, .. })) => {
                assert!(
                    message.contains("float literal cannot be typed as `I32`"),
                    "got: {message}"
                );
            }
            other => panic!("expected Type error, got {other:?}"),
        }
    }

    #[test]
    fn if_then_else_typechecks_with_role_bool() {
        let m = module(
            "module main; \
             import __intrinsics__; \
             host type Bool role(bool); \
             fn pick(c: Bool) -> . { \
               __if_then_else__(., c, .() { () }, .() { () }) \
             }",
        );
        check_module(&m).unwrap();
    }

    fn lowered_control_package_result(sources: &[(&str, &str)]) -> Result<Package, Error> {
        let mut parsed = Vec::new();
        for (_, source) in sources {
            let source = if source_uses_imported_elaborator(source) {
                add_elab_imports(source)
            } else {
                (*source).to_owned()
            };
            parsed.push(parse_package_entry(&source));
        }
        for (path, support) in ELAB_SUPPORT_SOURCES {
            parsed.push((
                PathBuf::from(path),
                parse_module_file(support).expect("support").module,
            ));
        }
        let (modules, _) =
            FullPipeline::lower_package(parsed, None).map_err(|error| error.error)?;
        let package = Package::build(Path::new(""), modules, None).map_err(|error| error.error)?;
        package.resolve_imports().map_err(|error| error.error)?;
        Ok(package)
    }

    fn lowered_control_package(sources: &[(&str, &str)]) -> Package {
        lowered_control_package_result(sources).expect("ordinary control package")
    }

    fn control_ok(source: &str) {
        check_package(&lowered_control_package(&[("main.kio", source)]))
            .expect("ordinary conditional source checks");
    }

    fn control_err(source: &str) -> String {
        let error = check_package(&lowered_control_package(&[("main.kio", source)]))
            .expect_err("ordinary conditional source rejects");
        match error.error {
            Error::Type(diagnostic) => diagnostic.message,
            other => panic!("expected Type error, got {other:?}"),
        }
    }

