    #[test]
    fn fills_relation_restart_completes_a_three_producer_two_wave_cohort() {
        let main = "module main; \
            import common(common3); \
            import elab(finish); \
            host fn make[A]() -> A; \
            fn run() -> . { \
              let _selected = common3!( \
                .() { make() }, .() { make() }, .() { finish!((), _) } \
              ); \
              () \
            }";
        let package = lowered_package(&[
            ("common.kio", COMMON_RESULT_FILLS),
            ("elab.kio", FINAL_SUCCESSOR_ELABORATORS),
            ("main.kio", main),
        ]);
        crate::pass::typecheck_core::apply::fills::reset_fill_relation_work();
        let (checked, scope) = check_retained_success(&package);

        assert_eq!(
            scope.memo().user_elaborator_template_executions(),
            2,
            "common3 and its independently ready action must each execute once"
        );
        let work = crate::pass::typecheck_core::apply::fills::fill_relation_work();
        assert_eq!(
            work.batch_attempts, 2,
            "the action wave and the restarted two-producer wave must each attempt one batch: {work:?}"
        );
        assert_eq!(
            work.batch_commits, work.batch_attempts,
            "both causal relation waves must commit: {work:?}"
        );
        assert_eq!(
            work.equations_submitted, 3,
            "each producer must submit exactly one proposal equation: {work:?}"
        );
        assert_eq!(
            work.accepted_producers, 3,
            "each producer must be accepted exactly once: {work:?}"
        );
        assert_eq!(
            work.soft_restarts, 1,
            "the first nonempty wave must restart one soft sweep before hard preflight: {work:?}"
        );
        assert_eq!(
            work.physical_closes, 3,
            "each accepted producer must close physically exactly once: {work:?}"
        );
        assert_eq!(
            work.producer_request_visits, 18,
            "the bounded two-wave cohort must retain its exact producer request count: {work:?}"
        );
        assert_eq!(
            work.producer_advance_visits, 13,
            "completed producers must skip exactly five re-advances across those requests: {work:?}"
        );
        assert_eq!(
            work.relation_wave_scan_visits, 6,
            "the two committed waves must each scan the cohort once: {work:?}"
        );
        validate_substituted_package(checked.substituted())
            .expect("the two-wave fills result survives standalone Prime validation");
    }

