    #[test]
    fn fills_common_result_stages_one_residual_eta_plan_per_partial_call() {
        let main = r#"module main;
import common(common2);

host type Output;

fn identity[A](value: A) -> A { value }

fn concrete(value: Output) -> Output { value }

fn generic_first() -> . {
  let _selected = common2!(.() { identity(_) }, .() { concrete });
  ()
}

fn generic_last() -> . {
  let _selected = common2!(.() { concrete }, .() { identity(_) });
  ()
}
"#;
        let parsed = [COMMON_RESULT_FILLS, main]
            .iter()
            .map(|source| parse_package_entry(source))
            .collect();
        let (lowered_modules, lowered_package_file) =
            FullPipeline::lower_package(parsed, None).expect("common-result package lowers");
        assert!(lowered_package_file.is_none());
        let package = Package::build(Path::new(""), lowered_modules, None)
            .expect("common-result package builds");
        package
            .resolve_imports()
            .expect("common-result package resolves imports");
        let checked = check_package_preserving_normalization(&package)
            .expect("both partial-call orders typecheck and retain their publication plans");
        let call_spans = main
            .match_indices("identity(_)")
            .map(|(start, call)| {
                Span::new(
                    u32::try_from(start).expect("test source fits in a span"),
                    u32::try_from(start + call.len()).expect("test source fits in a span"),
                )
            })
            .collect::<Vec<_>>();
        assert_eq!(call_spans.len(), 2);
        for call_span in call_spans {
            let sites = call_sites_at(checked.normalized().package(), "main", call_span);
            assert_eq!(sites.len(), 1);
            assert!(
                checked
                    .elaborations()
                    .call_residual_eta_type_for("main", sites[0].id)
                    .is_some(),
                "a partial call omitted its unique residual eta plan"
            );
        }
        validate_substituted_package(checked.substituted())
            .expect("each unique residual eta plan survives standalone Prime validation");
    }

