    #[test]
    fn fills_elaborator_implementation_has_a_split_capability_abi() {
        ok("module main; \
            import __comptime__; \
            pure fn marked( \
              ct: __Comptime__, fills: __Fill_ctx__, source: __Type__, value: __Checked_term__ \
            ) -> (__Checked_term__ & __Fill_ctx__) { (value, fills) } \
            elab demo : [Source] Source -> Source { impl(fills) marked; };");

        let missing_context = err("module main; \
            import __comptime__; \
            pure fn ordinary(ct: __Comptime__) -> __Checked_term__ { __term_unit__(ct) } \
            elab demo : . -> . { impl(fills) ordinary; };");
        assert!(
            missing_context.contains("ABI expects 2 value parameters")
                && missing_context.contains("implementation has 1"),
            "got: {missing_context}"
        );

        let context_in_late_mode = err("module main; \
            import __comptime__; \
            pure fn marked(ct: __Comptime__, fills: __Fill_ctx__) \
              -> (__Checked_term__ & __Fill_ctx__) { (__term_unit__(ct), fills) } \
            elab demo : . -> . { impl marked; };");
        assert!(
            context_in_late_mode.contains("ABI expects 1 value parameters")
                && context_in_late_mode.contains("implementation has 2"),
            "got: {context_in_late_mode}"
        );
    }

    #[test]
    fn ordinary_elaborator_skips_marked_projection_and_adoption_work() {
        use crate::pass::typecheck_core::apply::fills::{
            FillRelationWork, ProjectedHeaderWorkEvent, ProjectedLeafObservation,
            ReturnedFillRelationObservation,
        };

        #[derive(Debug)]
        struct Work {
            projected_sources: Vec<Vec<ProjectedLeafObservation>>,
            header_events: Vec<ProjectedHeaderWorkEvent>,
            returned_relations: Vec<Vec<ReturnedFillRelationObservation>>,
            adoption: FillRelationWork,
        }

        fn observe(implementation: &str) -> Work {
            let call = "demo!(.() { () })";
            let source = format!(
                "module main; \
                 import __comptime__; \
                 {implementation} \
                 fn run() -> . -> . {{ {call} }}"
            );
            let package = lowered_package(&[("main.kio", &source)]);
            let original = retained_call_at(&package, "main", source_span(&source, call));
            let Expr::UserElaborator { args, .. } = &original else {
                panic!("the same-shape call lost its retained elaborator form")
            };
            let value_span = args
                .iter()
                .find_map(|arg| match arg {
                    crate::ast::CallArg::Value(value) => Some(value.span()),
                    crate::ast::CallArg::Type(_) => None,
                })
                .expect("the same-shape call retains its lambda source");

            crate::pass::typecheck_core::apply::fills::reset_projected_source_observations(
                "main", value_span,
            );
            crate::pass::typecheck_core::apply::fills::reset_projected_header_work();
            crate::pass::typecheck_core::apply::fills::reset_fill_relation_work();
            let relation_observer =
                crate::pass::typecheck_core::apply::fills::observe_returned_fill_relations_at(
                    "main",
                    original.span(),
                );

            let (checked, scope) = check_retained_success(&package);
            assert_eq!(
                scope.memo().user_elaborator_template_executions(),
                1,
                "the same-shape implementation must execute exactly once"
            );
            assert_retained_call_published(checked.elaborations(), "main", &original);
            validate_substituted_package(checked.substituted())
                .expect("the same-shape replacement must survive Prime validation");

            Work {
                projected_sources:
                    crate::pass::typecheck_core::apply::fills::take_projected_source_observations(),
                header_events: crate::pass::typecheck_core::apply::fills::projected_header_work(),
                returned_relations: relation_observer.take(),
                adoption: crate::pass::typecheck_core::apply::fills::fill_relation_work(),
            }
        }

        let ordinary = observe(
            "pure fn implementation( \
               _ct: __Comptime__, _target: __Type__, value: __Checked_term__ \
             ) -> __Checked_term__ { value } \
             elab demo : [Target] Target -> Target { impl implementation; };",
        );
        assert!(
            ordinary.projected_sources.is_empty()
                && ordinary.header_events.is_empty()
                && ordinary.returned_relations.is_empty()
                && ordinary.adoption == FillRelationWork::default(),
            "ordinary scheduling performed marked-only compiler work: {ordinary:#?}"
        );

        let marked = observe(
            "pure fn implementation( \
               ct: __Comptime__, fills: __Fill_ctx__, \
               target: __Type__, value: __Checked_term__ \
             ) -> (__Checked_term__ & __Fill_ctx__) { \
               (value, __fill__(ct, fills, target, __term_type__(ct, value))) \
             } \
             elab demo : [Target] Target -> Target { impl(fills) implementation; };",
        );
        assert_eq!(
            marked.projected_sources.len(),
            1,
            "marked scheduling must construct one projected source: {marked:#?}"
        );
        assert_eq!(
            marked.projected_sources[0],
            vec![ProjectedLeafObservation {
                path: Vec::new(),
                template_index: 0,
                producer: Some(0),
            }],
            "marked scheduling changed its one-lambda producer topology"
        );
        assert!(
            marked
                .header_events
                .iter()
                .any(|event| matches!(event, ProjectedHeaderWorkEvent::Work(_, _)))
                && marked
                    .header_events
                    .iter()
                    .any(|event| matches!(event, ProjectedHeaderWorkEvent::Link(_)))
                && marked
                    .header_events
                    .iter()
                    .any(|event| matches!(event, ProjectedHeaderWorkEvent::Seal(_))),
            "marked scheduling must prepare and link a sealed projected header: {marked:#?}"
        );
        assert_eq!(
            marked.returned_relations.len(),
            1,
            "marked scheduling must return one relation transcript: {marked:#?}"
        );
        assert_eq!(
            marked.returned_relations[0].len(),
            1,
            "marked scheduling must authenticate one relation: {marked:#?}"
        );
        assert!(
            marked.adoption.batch_attempts > 0
                && marked.adoption.batch_commits > 0
                && marked.adoption.equations_submitted > 0
                && marked.adoption.accepted_producers > 0
                && marked.adoption.physical_closes > 0
                && marked.adoption.producer_request_visits > 0
                && marked.adoption.producer_advance_visits > 0
                && marked.adoption.relation_wave_scan_visits > 0,
            "marked scheduling skipped positive relation/adoption work: {marked:#?}"
        );
    }

    #[test]
    fn fills_partial_application_reuses_the_residual_eta_plan() {
        crate::pass::typecheck_core::apply::reset_terminal_public_layer_work();
        check_package_sources(&["module main; \
            import __comptime__; \
            pure fn relay_impl( \
                _ct: __Comptime__, \
                fills: __Fill_ctx__, \
                _a_type: __Type__, \
                _first: __Checked_term__, \
                _b_type: __Type__, \
                second: __Checked_term__ \
              ) -> (__Checked_term__ & __Fill_ctx__) { (second, fills) } \
            elab relay : [A] A -> [B] (A & B) -> A & B { impl(fills) relay_impl; }; \
            fn run[A](first: A) -> A & . { \
              let residual = relay!(first); \
              residual((first, ())) \
            }"])
        .expect("a partial fills call closes through its ordinary residual eta plan");
        assert_terminal_public_layer_work(0, 0, 0, 0, 0, 0);
    }

    #[test]
    fn fills_partial_application_rejects_a_lifted_callback_escape() {
        crate::normalization::reset_runtime_callback_adapter_work();
        let error = check_package_sources(&["module main; \
            import __intrinsics__; \
            import __comptime__; \
            host type Later; \
            host fn loop[S][R](step: S -> S | R, state: S) -> R; \
            host fn later() -> Later; \
            pure fn invoke_then_impl( \
              ct: __Comptime__, fills: __Fill_ctx__, \
              _s: __Type__, callback: __Checked_term__, _later: __Checked_term__ \
            ) -> (__Checked_term__ & __Fill_ctx__) { \
              let unit_type = __reflect_type__(ct, .); \
              let zero = __type_arity_zero__(ct); \
              let callback_type = __type_arrow__(ct, unit_type, zero, unit_type); \
              (__term_call__(ct, callback_type, callback, __term_unit__(ct)), fills) \
            } \
            elab invoke_then : [S] (S -> S) -> Later -> . { \
              impl(fills) invoke_then_impl; \
            }; \
            rec(loop) fn repeat(state: .) -> . { \
              let residual = invoke_then!(.(_unit: .) { rec(cont) repeat(state) }); \
              residual(later()) \
            }"])
        .expect_err("a residual function must not capture a lifted recursive callback");
        let Error::Parse(Diagnostic { message, .. }) = error else {
            panic!("expected a recursion escape diagnostic, got {error:?}");
        };
        assert!(
            message.contains("`rec(escape)` is reserved"),
            "got: {message}"
        );
        assert_eq!(
            crate::normalization::runtime_callback_adapter_work().0,
            0,
            "an escaping callback must be rejected before runtime adaptation"
        );
    }

    #[test]
    fn projected_residual_abi_classifies_every_callable_layer() {
        let type_only = FrozenProjectedResidualAbi {
            generated_type_params: vec![Some(TypeParam {
                name: "Later".into(),
                span: test_span(),
                kind: None,
            })],
            bound_value_names: Vec::new(),
        };
        assert!(type_only.has_residual_abstraction());

        let value_only = FrozenProjectedResidualAbi {
            generated_type_params: vec![None],
            bound_value_names: vec![Some("value".into())],
        };
        assert!(value_only.has_residual_abstraction());

        let saturated = FrozenProjectedResidualAbi {
            generated_type_params: vec![None],
            bound_value_names: vec![None],
        };
        assert!(!saturated.has_residual_abstraction());
    }

