    #[test]
    fn fills_relations_are_order_invariant_and_contradictions_roll_back() {
        for (
            case,
            relations,
            expected_roots,
            expected_paths,
            expected_closed,
            expected_candidates,
        ) in [
            (
                "forward",
                "__fill__(ct, \
                   __fill__(ct, __fill__(ct, fills, a, b), b, __type_unit__(ct)), \
                   fixed, __type_unit__(ct))",
                vec![0, 1, 2],
                vec![vec![], vec![], vec![]],
                vec![false, false, true],
                vec!["_", ".", "."],
            ),
            (
                "reverse",
                "__fill__(ct, \
                   __fill__(ct, __fill__(ct, fills, fixed, __type_unit__(ct)), \
                     b, __type_unit__(ct)), \
                   a, b)",
                vec![2, 1, 0],
                vec![vec![], vec![], vec![]],
                vec![true, false, false],
                vec![".", ".", "_"],
            ),
        ] {
            let source = format!(
                "module main; \
                 import __comptime__; \
                 pure fn solve_impl( \
                   ct: __Comptime__, fills: __Fill_ctx__, \
                   a: __Type__, b: __Type__, fixed: __Type__, value: __Checked_term__ \
                 ) -> (__Checked_term__ & __Fill_ctx__) {{ \
                   ( \
                     __intrinsic_pair__( \
                       ct, __term_unit__(ct), \
                       __intrinsic_pair__(ct, __term_unit__(ct), value) \
                     ), \
                     {relations} \
                   ) \
                 }} \
                 elab solve : [A] [B] [Fixed] Fixed -> A & B & Fixed {{ \
                   impl(fills) solve_impl; \
                 }}; \
                 fn run() -> . {{ let _result = solve!(()); () }}"
            );
            let package = lowered_package(&[("main.kio", &source)]);
            let original = retained_call_at(&package, "main", source_span(&source, "solve!(())"));
            let observer =
                crate::pass::typecheck_core::apply::fills::observe_returned_fill_relations_at(
                    "main",
                    original.span(),
                );
            let (checked, scope) = check_retained_success(&package);
            assert_eq!(scope.memo().user_elaborator_template_executions(), 1);
            assert_retained_call_published(checked.elaborations(), "main", &original);
            let observations = observer.take();
            assert_eq!(
                observations.len(),
                1,
                "{case} must return one authored transcript: {observations:#?}"
            );
            let observed = &observations[0];
            assert_eq!(observed.len(), 3, "{case}: {observed:#?}");
            assert_eq!(
                observed
                    .iter()
                    .map(|relation| relation.destination_root)
                    .collect::<Vec<_>>(),
                expected_roots,
                "{case} changed the independent public destination order"
            );
            assert_eq!(
                observed
                    .iter()
                    .map(|relation| relation.destination_path.clone())
                    .collect::<Vec<_>>(),
                expected_paths,
                "{case} changed the two-open/one-preclosed destination order"
            );
            assert_eq!(
                observed
                    .iter()
                    .map(|relation| relation.destination_closed)
                    .collect::<Vec<_>>(),
                expected_closed,
                "{case} changed which destination was already closed"
            );
            assert_eq!(
                observed
                    .iter()
                    .map(|relation| relation.candidate_display.as_str())
                    .collect::<Vec<_>>(),
                expected_candidates,
                "{case} changed candidate transcript order"
            );
            validate_substituted_package(checked.substituted())
                .unwrap_or_else(|error| panic!("{case} must survive Prime validation: {error:?}"));
        }

        let contradictory = "module main; \
            import __comptime__; \
            pure fn conflict_impl( \
              ct: __Comptime__, fills: __Fill_ctx__, a: __Type__ \
            ) -> (__Checked_term__ & __Fill_ctx__) { \
              ( \
                __term_unit__(ct), \
                __fill__( \
                  ct, \
                  __fill__(ct, fills, a, __type_unit__(ct)), \
                  a, \
                  __type_product__(ct, __type_unit__(ct), __type_unit__(ct)) \
                ) \
              ) \
            } \
            elab conflict : [A] . -> A { impl(fills) conflict_impl; }; \
            fn run() -> . { let _result = conflict!(()); () }";
        let package = lowered_package(&[("main.kio", contradictory)]);
        let original = retained_call_at(
            &package,
            "main",
            source_span(contradictory, "conflict!(())"),
        );
        let (elaborations, scope, errors) = check_retained_module_error(&package, "main");
        assert!(
            errors.iter().any(|error| matches!(
                error,
                Error::Type(diagnostic) if diagnostic.message.contains("type mismatch")
            )),
            "contradictory fill relations must fail: {errors:?}"
        );
        assert_eq!(scope.memo().user_elaborator_template_executions(), 1);
        assert_retained_call_unpublished(&elaborations, "main", &original);
    }

    #[test]
    fn fills_sparse_private_value_abi_forces_every_unrequested_source_once() {
        let source = "module main; \
            import __comptime__; \
            host type I32 role(i32); \
            host fn probe() -> .; \
            pure fn sparse_impl( \
              _ct: __Comptime__, fills: __Fill_ctx__, \
              _first: __Checked_term__, second: __Checked_term__ \
            ) -> (__Checked_term__ & __Fill_ctx__) { (second, fills) } \
            elab sparse : . -> I32 -> . -> I32 -> . -> I32 { \
              impl(fills) sparse_impl; \
            }; \
            fn run() -> I32 { sparse!(probe(), 0, probe(), 1, probe()) }";
        let package = lowered_package(&[("main.kio", source)]);
        let original = retained_call_at(
            &package,
            "main",
            source_span(source, "sparse!(probe(), 0, probe(), 1, probe())"),
        );
        let (checked, scope) = check_retained_success(&package);

        assert!(
            checked
                .elaborations()
                .elaboration_for("main", &original)
                .is_some(),
            "the sparse private ABI must still publish its public call"
        );
        assert_eq!(scope.memo().user_elaborator_template_executions(), 1);

        struct ProbeCalls(usize);
        impl crate::pass::visit_mut::TypecheckVisitMut<Prime> for ProbeCalls {
            fn visit_expr(&mut self, expr: &mut crate::ast::Expr<Prime>) {
                if matches!(expr,
                    crate::ast::Expr::Call { callee, .. }
                        if matches!(callee.as_ref(), crate::ast::Expr::Path { segments, .. }
                            if segments.last().is_some_and(|segment| segment.as_str() == "probe")))
                {
                    self.0 += 1;
                }
                crate::pass::visit_mut::walk_expr(self, expr);
            }
        }

        let mut substituted = checked
            .substituted()
            .package()
            .module("main")
            .expect("main module survives substitution")
            .module
            .clone();
        let mut probe_calls = ProbeCalls(0);
        crate::pass::visit_mut::TypecheckVisitMut::visit_module(&mut probe_calls, &mut substituted);
        assert_eq!(
            probe_calls.0, 3,
            "leading, middle, and trailing zero-ABI sources must each replay exactly once"
        );
        validate_substituted_package(checked.substituted())
            .expect("the sparse private ABI survives standalone Prime validation");
    }

    #[test]
    fn fills_open_specialization_argument_closes_before_recipe_materialization() {
        let elaborator = "module elab; \
            import __intrinsics__; \
            import __comptime__; \
            type Type_pair = __Type__ & __Type__; \
            type Function_view = __Type__ & __Type_arity__ & __Type__; \
            type Forall_view = __Type_var__ & __Type_arity__ & __Type__; \
            type Type_view_tail7 = __Type_name__; \
            type Type_view_tail6 = __Type_var__ | Type_view_tail7; \
            type Type_view_tail5 = Forall_view | Type_view_tail6; \
            type Type_view_tail4 = Function_view | Type_view_tail5; \
            type Type_view_tail3 = Type_pair | Type_view_tail4; \
            type Type_view_tail2 = Type_pair | Type_view_tail3; \
            type Type_view_tail1 = . | Type_view_tail2; \
            type Maybe_forall_view = Forall_view | .; \
            type Specialize_tail = . | __Diagnostic_text__; \
            pure fn some_forall_view( \
              _ct: __Comptime__, view: Forall_view \
            ) -> Maybe_forall_view { __left__(Forall_view, ., view) } \
            pure fn no_forall_view(_ct: __Comptime__) -> Maybe_forall_view { \
              __right__(Forall_view, ., ()) \
            } \
            pure fn forall_view(ct: __Comptime__, typ: __Type__) -> Maybe_forall_view { \
              __either__( \
                ., Type_view_tail1, Maybe_forall_view, __type_view__(ct, typ), \
                .(_unit: .) -> Maybe_forall_view { no_forall_view(ct) }, \
                .(tail1: Type_view_tail1) -> Maybe_forall_view { \
                  __either__( \
                    ., Type_view_tail2, Maybe_forall_view, tail1, \
                    .(_bottom: .) -> Maybe_forall_view { no_forall_view(ct) }, \
                    .(tail2: Type_view_tail2) -> Maybe_forall_view { \
                      __either__( \
                        Type_pair, Type_view_tail3, Maybe_forall_view, tail2, \
                        .(_product: Type_pair) -> Maybe_forall_view { no_forall_view(ct) }, \
                        .(tail3: Type_view_tail3) -> Maybe_forall_view { \
                          __either__( \
                            Type_pair, Type_view_tail4, Maybe_forall_view, tail3, \
                            .(_sum: Type_pair) -> Maybe_forall_view { no_forall_view(ct) }, \
                            .(tail4: Type_view_tail4) -> Maybe_forall_view { \
                              __either__( \
                                Function_view, Type_view_tail5, Maybe_forall_view, tail4, \
                                .(_function: Function_view) -> Maybe_forall_view { \
                                  no_forall_view(ct) \
                                }, \
                                .(tail5: Type_view_tail5) -> Maybe_forall_view { \
                                  __either__( \
                                    Forall_view, Type_view_tail6, Maybe_forall_view, tail5, \
                                    .(view: Forall_view) -> Maybe_forall_view { \
                                      some_forall_view(ct, view) \
                                    }, \
                                    .(_tail6: Type_view_tail6) -> Maybe_forall_view { \
                                      no_forall_view(ct) \
                                    } \
                                  ) \
                                } \
                              ) \
                            } \
                          ) \
                        } \
                      ) \
                    } \
                  ) \
                } \
              ) \
            } \
            pub pure fn specialize_open_impl( \
              ct: __Comptime__, \
              fills: __Fill_ctx__, \
              target: __Type__, \
              clause: __Checked_term__ \
            ) -> (__Checked_term__ & __Fill_ctx__) { \
              __either__( \
                Forall_view, ., __Checked_term__ & __Fill_ctx__, \
                forall_view(ct, __term_type__(ct, clause)), \
                .(view: Forall_view) -> (__Checked_term__ & __Fill_ctx__) { \
                  let var = __fst__(__Type_var__, __Type_arity__ & __Type__, view); \
                  __either__( \
                    __Checked_term__, Specialize_tail, __Checked_term__ & __Fill_ctx__, \
                    __term_specialize__(ct, clause, __type_var__(ct, var), target), \
                    .(specialized: __Checked_term__) -> (__Checked_term__ & __Fill_ctx__) { \
                      ( \
                        __term_call__( \
                          ct, \
                          __term_type__(ct, specialized), \
                          specialized, \
                          __term_unit__(ct) \
                        ), \
                        __fill__(ct, fills, target, __type_unit__(ct)) \
                      ) \
                    }, \
                    .(_failed: Specialize_tail) -> (__Checked_term__ & __Fill_ctx__) { \
                      (__elab_error__(ct, \"specialization failed\"), fills) \
                    } \
                  ) \
                }, \
                .() -> (__Checked_term__ & __Fill_ctx__) { \
                  (__elab_error__(ct, \"expected forall\"), fills) \
                } \
              ) \
            } \
            pub elab specialize_open : [Target] ([A] . -> A) -> Target { \
              impl(fills) specialize_open_impl; \
            };";
        let main = "module main; \
            import elab(specialize_open); \
            host fn make[A]() -> A; \
            fn run() -> . { specialize_open!(make) }";
        let package = lowered_package(&[("elab.kio", elaborator), ("main.kio", main)]);
        let original = retained_call_at(
            &package,
            "main",
            source_span(main, "specialize_open!(make)"),
        );
        let (checked, scope) = check_retained_success(&package);
        assert!(matches!(
            checked
                .elaborations()
                .position_index()
                .type_at("main", original.span()),
            Some(Type::Unit { .. })
        ));
        assert_eq!(scope.memo().user_elaborator_template_executions(), 1);
        validate_substituted_package(checked.substituted())
            .expect("the open specialization argument must zonk before TermTypeApp recipe replay");
    }

    #[test]
