    #[test]
    fn user_elaborator_semantic_packet_rejects_explicit_unit_slots() {
        for (case, domain, tail, expected) in [
            (
                "trailing Unit",
                "__Comptime__ & __Type__ & __Checked_term__ & .",
                "__Type__ & __Checked_term__ & .",
                "implementation has 4",
            ),
            (
                "middle Unit",
                "__Comptime__ & . & __Type__ & __Checked_term__",
                ". & __Type__ & __Checked_term__",
                "implementation has 4",
            ),
            (
                "nested Unit product",
                "__Comptime__ & (__Type__ & .) & __Checked_term__",
                "(__Type__ & .) & __Checked_term__",
                "for type slot `[Source]`",
            ),
            (
                "aliased trailing Unit",
                "__Comptime__ & __Type__ & __Checked_term__ & Unit_alias",
                "__Type__ & __Checked_term__ & Unit_alias",
                "implementation has 4",
            ),
        ] {
            let source = format!(
                "module main; \
                 import __comptime__; \
                 type Unit_alias = .; \
                 pure fn identity_impl(packet: {domain}) -> __Checked_term__ {{ \
                     __term_unit__(__fst__(__Comptime__, {tail}, packet)) \
                   }} \
                 elab identity : [Source] Source -> Source {{ impl identity_impl; }};"
            );
            let message = err(&source);
            assert!(
                message.contains(expected),
                "{case} must remain an explicit semantic slot: {message}"
            );
        }
    }

    #[test]
    fn user_elaborator_semantic_packet_invokes_a_direct_flat_implementation() {
        ok("module main; \
            import __comptime__; \
            pure fn identity_impl( \
              _ct: __Comptime__, \
              _source: __Type__, \
              value: __Checked_term__ \
            ) -> __Checked_term__ { value } \
            elab identity : [Source] Source -> Source { impl identity_impl; }; \
            fn run() -> . { identity!(()) }");
    }

    #[test]
    fn user_elaborator_named_implementation_can_invoke_a_flat_fold_result() {
        let source = "module main; \
            import __comptime__; \
            type Identity_impl = \
              (__Comptime__ & __Type__ & __Checked_term__) -> __Checked_term__; \
            pure fn identity_impl( \
              _ct: __Comptime__, \
              _source: __Type__, \
              value: __Checked_term__ \
            ) -> __Checked_term__ { value } \
            pure fn right_base[A](value: A) -> A { value } \
            pure fn right_step[A][B]( \
              _value: A, \
              acc: B \
            ) -> B { acc } \
            varop [* *] { \
              foldr1 right_step right_base; \
            }; \
            pure fn entry_base[A][B]((_key: A, value: B)) -> B { value } \
            pure fn entry_step[A][B][C]( \
              (_key: A, _value: B), \
              acc: C \
            ) -> C { acc } \
            varop [% %] { \
              foldr1 entry_step entry_base; \
            }; \
            pure fn folded_identity_impl( \
              ct: __Comptime__, source: __Type__, value: __Checked_term__ \
            ) -> __Checked_term__ { \
              let selected = [% ((), [* (), identity_impl *]) %]; \
              selected(ct, source, value) \
            } \
            elab identity : [Source] Source -> Source { impl folded_identity_impl; }; \
            fn run() -> . { identity!(()) }";
        check_package_sources(&[source])
            .unwrap_or_else(|error| panic!("expected ok, got {error:?}"));
    }

