    #[test]
    fn generated_elaborator_type_imports_are_injective_and_binder_safe() {
        let module = lowered_module("module current; fn _q0() -> . { () }");
        let mut imports = Vec::new();
        let slash = capture_import(&mut imports, "a/b", &module);
        let underscore = capture_import(&mut imports, "a_b", &module);
        assert_ne!(slash.alias, underscore.alias);

        let span = test_span();
        let bound = Type::Forall {
            param: TypeParam {
                name: slash.alias.clone(),
                span,
                kind: None,
            },
            body: Box::new(Type::synth_path(
                vec![slash.alias.clone()],
                Vec::new(),
                span,
            )),
            meta: Meta::new(span),
        };
        let Type::Forall { body, .. } =
            canonicalize_captured_generated_imports(&bound, std::slice::from_ref(&slash))
        else {
            panic!("expected forall")
        };
        let Type::Path { segments, .. } = *body else {
            panic!("expected bound path")
        };
        assert_eq!(segments[0].as_str(), slash.alias);

        let generated = Type::synth_path(
            vec![slash.alias.clone(), "Leaf".to_owned()],
            Vec::new(),
            span,
        );
        let Type::Path { segments, .. } =
            canonicalize_captured_generated_imports(&generated, &[slash])
        else {
            panic!("expected generated path")
        };
        assert_eq!(
            segments.iter().map(PathSegment::as_str).collect::<Vec<_>>(),
            vec!["a", "b", "Leaf"]
        );
    }

