    #[test]
    fn imported_elaborator_and_field_slots_keep_declaring_module_identity() {
        use crate::pass::resolve::Package;
        use crate::pass::typecheck_core::ModuleEnv;
        use std::path::{Path, PathBuf};

        let modules = vec![
            (
                PathBuf::from("types.kio"),
                lowered_module("module types; pub host type Value role(bool);"),
            ),
            (
                PathBuf::from("other.kio"),
                lowered_module("module other; pub host type Value role(i32);"),
            ),
            (
                PathBuf::from("dep.kio"),
                lowered_module(
                    "module dep; import types as types; \
                     pub type Pair = types.Value & types.Value;",
                ),
            ),
            (
                PathBuf::from("shadow.kio"),
                lowered_module(
                    "module shadow; import other as other; \
                     pub type Pair = other.Value & other.Value;",
                ),
            ),
            (
                PathBuf::from("label_dep.kio"),
                lowered_module(
                    "module label_dep; import types as types; \
                     pub newtype Slot : types.Value { constructor mk; projector un; };",
                ),
            ),
            (
                PathBuf::from("label_shadow.kio"),
                lowered_module(
                    "module label_shadow; import other as other; \
                     pub newtype Slot : other.Value { constructor mk; projector un; };",
                ),
            ),
            (
                PathBuf::from("main.kio"),
                lowered_module(
                    "module main; \
                     import __comptime__; \
                     import dep(Pair); import types(Value); \
                     import label_dep(Slot); import label_shadow as label_dep; \
                     import shadow as dep; import other as types; \
                     pure fn local_impl(ct: __Comptime__, _source: __Type__) -> __Checked_term__ { \
                         __elab_error__(ct, \"not evaluated\") \
                       } \
                     elab local : [A] . -> A { impl local_impl; };",
                ),
            ),
        ];
        let package = Package::build(Path::new(""), modules, None).expect("package");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package)
            .into_parts()
            .0;
        let main = &package.module("main").expect("main module").module;
        let env = ModuleEnv::build(main, None, None, Some(&package)).expect("env");
        let canonical_pair = InternedType::fresh_canonical(Type::synth_path(
            vec!["dep".to_owned(), "Pair".to_owned()],
            Vec::new(),
            test_span(),
        ));
        let abi_slots = user_elaborator_value_slot_types(&canonical_pair, 1);
        assert_eq!(abi_slots.len(), 1);
        let Type::Path { segments, .. } = abi_slots[0].as_type() else {
            panic!("expected nominal ABI slot");
        };
        assert_eq!(
            segments
                .iter()
                .map(|segment| segment.as_str())
                .collect::<Vec<_>>(),
            vec!["dep", "Pair"]
        );
        assert!(abi_slots[0].identity_is_canonical());

        let visible_slots = visible_product_slots(&canonical_pair, &env.alias_ctx());
        assert_eq!(visible_slots.len(), 2);
        for slot in visible_slots {
            let Type::Path { segments, .. } = slot.as_type() else {
                panic!("expected nominal visible slot");
            };
            assert_eq!(
                segments
                    .iter()
                    .map(|segment| segment.as_str())
                    .collect::<Vec<_>>(),
                vec!["types", "Value"]
            );
            assert!(slot.identity_is_canonical());
        }

        let canonical_slot = InternedType::fresh_canonical(Type::synth_path(
            vec!["label_dep".to_owned(), "Slot".to_owned()],
            Vec::new(),
            test_span(),
        ));
        let selective_slot = vec![PathSegment::new("Slot".to_owned(), test_span())];
        label_slot_type_args(&canonical_slot, &selective_slot, test_span(), &env)
            .expect("canonical label_dep.Slot matches its selective binding");
        let shadow_slot = vec![
            PathSegment::new("label_dep".to_owned(), test_span()),
            PathSegment::new("Slot".to_owned(), test_span()),
        ];
        assert!(
            label_slot_type_args(&canonical_slot, &shadow_slot, test_span(), &env).is_err(),
            "the source-spelled label_dep.Slot resolves through the shadow alias"
        );

        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations);
        let explicit_args = vec![
            CallArg::Type(Type::synth_path(
                vec!["Value".to_owned()],
                Vec::new(),
                test_span(),
            )),
            CallArg::Value(Expr::Unit {
                occurrence: crate::ast::ExpressionOccurrence::fresh(),
                meta: Meta::new(test_span()),
            }),
        ];
        let call = Expr::UserElaborator {
            occurrence: crate::ast::ExpressionOccurrence::fresh(),
            form: crate::ast::UserElaboratorCallForm::Ordinary,
            name: "local".to_owned(),
            args: explicit_args,
            meta: Meta::new(test_span()),
            ext: NodeId(41),
        };
        let result_ty =
            crate::pass::typecheck_core::apply::run_general_ordinary_value(&call, None, &mut tcx)
                .expect("typecheck local elaborator call")
                .ty;
        assert!(result_ty.identity_is_canonical());
        let actual_value = Type::synth_path(
            vec!["types".to_owned(), "Value".to_owned()],
            Vec::new(),
            test_span(),
        );
        let mut capture_imports = Vec::new();
        let nominal_provider = NominalProvider::new(Some(env.module), env.package);
        let replayed_capture_ty = captured_term_type_for_replay(
            &InternedType::fresh_canonical(actual_value.clone()),
            &ResolvedCaptureTermPath {
                source_owner_module_path: Some("dep".to_owned()),
                owner_module_path: Some("dep".to_owned()),
                visibility_edges: vec![ResolvedCaptureVisibilityEdge {
                    owner_module_path: Some("dep".to_owned()),
                    visibility: crate::ast::Visibility::Public,
                    target: "captured function `captured`".to_owned(),
                }],
                replay_tail: vec!["captured".to_owned()],
            },
            &env,
            &nominal_provider,
            &mut capture_imports,
        );
        let Type::Path {
            segments: replayed_segments,
            ..
        } = replayed_capture_ty
        else {
            panic!("expected replayed nominal capture type")
        };
        assert_eq!(
            replayed_segments
                .iter()
                .map(PathSegment::as_str)
                .collect::<Vec<_>>(),
            vec![capture_imports[0].alias.as_str(), "Value"]
        );
        assert_eq!(capture_imports[0].module_path, "types");
        crate::pass::typecheck_core::require_type_equiv_state(
            result_ty.as_type(),
            &actual_value,
            test_span(),
            &env.alias_ctx(),
            result_ty.identity_is_canonical(),
            true,
        )
        .expect("explicit Value keeps the selectively imported types.Value identity");
        let shadow_value = Type::synth_path(
            vec!["other".to_owned(), "Value".to_owned()],
            Vec::new(),
            test_span(),
        );
        assert!(
            crate::pass::typecheck_core::require_type_equiv_state(
                result_ty.as_type(),
                &shadow_value,
                test_span(),
                &env.alias_ctx(),
                result_ty.identity_is_canonical(),
                true,
            )
            .is_err(),
            "caller alias `types` must not reinterpret canonical types.Value"
        );
    }

    #[test]
    fn reflected_imported_alias_keeps_its_owner_identity() {
        let api = lowered_module(
            "module testapi; \
             host type String role(str);",
        );
        let types = lowered_module(
            "module testapi/types; \
             import testapi as api; \
             pub type String = api.String;",
        );
        let consumer = lowered_module(
            "module testapi/main; \
             import testapi/types(String);",
        );
        let package = Package::build(
            Path::new(""),
            vec![
                (PathBuf::from("testapi.kio"), api),
                (PathBuf::from("testapi/types.kio"), types),
                (PathBuf::from("testapi/main.kio"), consumer),
            ],
            None,
        )
        .expect("package");
        package.resolve_imports().expect("resolve imports");
        let consumer = &package
            .module("testapi/main")
            .expect("consumer module")
            .module;
        let env = ModuleEnv::build(consumer, None, None, Some(&package)).expect("env");
        let mut elaborations = Elaborations::new();
        let tcx = TypeCtx::new(&env, &mut elaborations);

        let reflected = reflect_elaborator_type(
            Type::synth_path(vec!["String".to_owned()], Vec::new(), test_span()),
            &tcx,
        )
        .expect("reflect type");
        let crate::ast::Type::Path { segments, args, .. } = reflected.as_type() else {
            panic!("expected reflected alias path");
        };
        assert!(args.is_empty());
        assert_eq!(
            segments
                .iter()
                .map(|segment| segment.as_str())
                .collect::<Vec<_>>(),
            vec!["testapi", "types", "String"]
        );
    }

    #[test]
    fn reflected_caller_binder_stays_bare_under_nominal_collision() {
        let consumer = lowered_module(
            "module testapi/main; \
             newtype A : . { constructor mk_a; projector un_a; };",
        );
        let package = Package::build(
            Path::new(""),
            vec![(PathBuf::from("testapi/main.kio"), consumer)],
            None,
        )
        .expect("package");
        package.resolve_imports().expect("resolve imports");
        let consumer = &package
            .module("testapi/main")
            .expect("consumer module")
            .module;
        let env = ModuleEnv::build(consumer, None, None, Some(&package)).expect("env");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations);
        tcx.push_type_param("A", test_span());

        let reflected = reflect_elaborator_type(
            Type::synth_path(vec!["A".to_owned()], Vec::new(), test_span()),
            &tcx,
        )
        .expect("reflect type");
        let crate::ast::Type::Path { segments, args, .. } = reflected.as_type() else {
            panic!("expected reflected binder path");
        };
        assert!(args.is_empty());
        assert_eq!(
            segments
                .iter()
                .map(|segment| segment.as_str())
                .collect::<Vec<_>>(),
            vec!["A"]
        );
    }

    #[test]
    fn user_elaborator_qualified_function_capture_replays_from_owner_alias() {
        use crate::pass::resolve::Package;
        use crate::pass::typecheck_core::{ModuleEnv, TypeCtx};
        use std::path::{Path, PathBuf};

        let helper = lowered_module(
            "module pkg/helper; \
             pub fn helper() -> . { () }",
        );
        let refl = lowered_module(
            "module pkg/refl; \
             import __comptime__; \
             import pkg/helper as h; \
             pure fn capture_demo_impl(ct: __Comptime__, _helper: __Checked_term__, _source: __Type__, _target: __Type__ | .) -> __Checked_term__ { \
                 __elab_error__(ct, \"not evaluated\") \
               } \
             pub elab capture_demo : [T] . -> . { captures h.helper; impl capture_demo_impl; };",
        );
        let package = Package::build(
            Path::new(""),
            vec![
                (PathBuf::from("pkg/helper.kio"), helper),
                (PathBuf::from("pkg/refl.kio"), refl),
            ],
            None,
        )
        .unwrap();
        let refl = &package.module("pkg/refl").expect("refl module").module;
        let env = ModuleEnv::build(refl, None, None, Some(&package)).expect("env");
        let elaborator = refl
            .items
            .iter()
            .find_map(|item| match item {
                crate::ast::Item::Elaborator(elaborator, _) => Some(elaborator),
                _ => None,
            })
            .expect("elaborator");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations);
        let captures =
            resolve_user_elaborator_captures(elaborator, &env, &mut tcx).expect("captures");
        let Some(UserElaboratorTemplateInput::CapturedTerm { term }) = captures.inputs.first()
        else {
            panic!("expected captured checked term");
        };
        let crate::ast::Expr::Path { segments, .. } = term.clone_expr() else {
            panic!("expected captured term path");
        };
        assert_eq!(
            segments
                .iter()
                .map(|segment| segment.as_str())
                .collect::<Vec<_>>(),
            vec!["h", "helper"]
        );
    }

