    #[test]
    fn user_elaborator_generated_dependency_rebuilds_artifact_type_scope() {
        let package = lowered_package(&[
            (
                "provider/types.kio",
                "module provider/types; pub type Shared = .;",
            ),
            (
                "elab.kio",
                "module elab; \
                 import __comptime__; \
                 pure fn demo_impl(ct: __Comptime__) -> __Checked_term__ { __term_unit__(ct) } \
                 elab demo : . -> . { impl demo_impl; };",
            ),
        ]);
        let normalized = crate::pass::alpha_normalize::normalize_package(&package);
        let typecheck_scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(
                    crate::pass::typecheck_core::TypeInterner::<Lowered>::default(),
                ),
            );
        let package = normalized.package();
        let module = &package.module("elab").expect("elaborator module").module;
        let env = ModuleEnv::build_with_typecheck_scope(
            module,
            None,
            None,
            Some(package),
            typecheck_scope,
        )
        .expect("environment");
        let dependency = UserElaboratorTemplateGeneratedImport {
            module_path: "provider/types".to_owned(),
            alias: "_q0".to_owned(),
        };

        let (artifact, _) = user_elaborator_eval_artifact(
            &env,
            std::slice::from_ref(&dependency),
            "demo",
            test_span(),
            None,
        )
        .expect("evaluator artifact");
        let entry = artifact.package().module("elab").expect("artifact module");
        assert!(entry.module.imports.iter().any(|import_| {
            matches!(
                &import_.kind,
                ImportKind::Qualified { path, alias }
                    if module_import_path(path) == dependency.module_path
                        && alias == &dependency.alias
            )
        }));

        let segments = [
            PathSegment::new(dependency.alias, test_span()),
            PathSegment::new("Shared".to_owned(), test_span()),
        ];
        let expanded = crate::pass::resolve::expand_type_import_segments_in_entry(&segments, entry);
        assert_eq!(
            expanded.iter().map(PathSegment::as_str).collect::<Vec<_>>(),
            vec!["provider", "types", "Shared"],
            "the artifact's indexed type scope must include generated dependencies"
        );
    }

    #[test]
    fn user_elaborator_artifact_pairs_are_analysis_scoped_singleflight() {
        fn key(alias: &str) -> UserElaboratorArtifactKey {
            UserElaboratorArtifactKey::new(
                "elab/match".to_owned(),
                "match".to_owned(),
                vec![UserElaboratorTemplateGeneratedImport {
                    module_path: "model/types".to_owned(),
                    alias: alias.to_owned(),
                }],
            )
        }

        fn empty_artifact(implementation_name: &str) -> UserElaboratorEvalArtifactPair {
            let span = Span::new(0, 0);
            UserElaboratorEvalArtifactPair {
                artifact: std::sync::Arc::new(
                    crate::normalization::EvalArtifact::from_validated_parts(
                        Package::from_parts(std::collections::BTreeMap::new(), None),
                        crate::normalization::EvalPrimitiveEnv::default(),
                    ),
                ),
                implementation: crate::ast::Expr::<UncheckedPrime>::Path {
                    occurrence: Default::default(),
                    segments: vec![PathSegment::new(implementation_name.to_owned(), span)],
                    meta: Meta::new(span),
                    ext: (),
                },
            }
        }

        let builds = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let package = Package::from_parts(std::collections::BTreeMap::new(), None);
        let persistent =
            std::sync::Arc::new(crate::pass::typecheck_core::TypeInterner::<Lowered>::default());
        let first_package = crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_package(
            &package,
            persistent.clone(),
        );
        let artifacts = (0..8)
            .map(|_| {
                let builds = builds.clone();
                let package = first_package.clone();
                std::thread::spawn(move || {
                    package
                        .user_elaborator_artifacts()
                        .get_or_try_compute(
                            key("_q0"),
                            || {
                                builds.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                                std::thread::sleep(std::time::Duration::from_millis(20));
                                Ok::<_, ()>(empty_artifact("first"))
                            },
                            |_| {},
                        )
                        .expect("package artifact")
                })
            })
            .map(|thread| thread.join().expect("artifact thread"))
            .collect::<Vec<_>>();
        assert_eq!(builds.load(std::sync::atomic::Ordering::Relaxed), 1);
        assert!(
            artifacts
                .iter()
                .all(|artifact| std::sync::Arc::ptr_eq(&artifacts[0], artifact))
        );
        let crate::ast::Expr::Path { segments, .. } = &artifacts[0].implementation else {
            panic!("expected paired staged implementation")
        };
        assert_eq!(segments[0].as_str(), "first");

        let distinct_artifact = first_package
            .user_elaborator_artifacts()
            .get_or_try_compute(
                key("_q1"),
                || {
                    builds.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    Ok::<_, ()>(empty_artifact("different_captures"))
                },
                |_| {},
            )
            .expect("different exact capture imports build a distinct artifact");
        assert!(!std::sync::Arc::ptr_eq(&artifacts[0], &distinct_artifact));
        let crate::ast::Expr::Path { segments, .. } = &distinct_artifact.implementation else {
            panic!("expected paired staged implementation")
        };
        assert_eq!(segments[0].as_str(), "different_captures");
        assert_eq!(builds.load(std::sync::atomic::Ordering::Relaxed), 2);

        let first_error = first_package
            .user_elaborator_artifacts()
            .get_or_try_compute(
                key("failure"),
                || Err::<UserElaboratorEvalArtifactPair, _>(Span::new(10, 11)),
                |_| {},
            );
        assert!(matches!(first_error, Err(span) if span == Span::new(10, 11)));
        let second_error = first_package
            .user_elaborator_artifacts()
            .get_or_try_compute(
                key("failure"),
                || Err::<UserElaboratorEvalArtifactPair, _>(Span::new(20, 21)),
                |_| {},
            );
        assert!(matches!(second_error, Err(span) if span == Span::new(20, 21)));
        let recovered = first_package
            .user_elaborator_artifacts()
            .get_or_try_compute(
                key("failure"),
                || {
                    builds.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    Ok::<_, Span>(empty_artifact("recovered"))
                },
                |_| {},
            )
            .expect("a failed initialization is retried");
        let crate::ast::Expr::Path { segments, .. } = &recovered.implementation else {
            panic!("expected paired staged implementation")
        };
        assert_eq!(segments[0].as_str(), "recovered");
        let artifact_stats = first_package.user_elaborator_artifacts().snapshot();
        assert_eq!(artifact_stats.hits, 7);
        assert_eq!(artifact_stats.misses, 5);
        assert_eq!(artifact_stats.first_writes, 3);

        let first_artifact = std::sync::Arc::downgrade(&artifacts[0].artifact);
        drop(artifacts);
        drop(distinct_artifact);
        drop(recovered);
        assert!(first_artifact.upgrade().is_some());
        drop(first_package);
        assert!(first_artifact.upgrade().is_none());

        let second_package = crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_package(
            &package, persistent,
        );
        let second_artifact = second_package
            .user_elaborator_artifacts()
            .get_or_try_compute(
                key("_q0"),
                || {
                    builds.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                    Ok::<_, ()>(empty_artifact("second_package"))
                },
                |_| {},
            )
            .expect("new package check builds its own artifact");
        let crate::ast::Expr::Path { segments, .. } = &second_artifact.implementation else {
            panic!("expected paired staged implementation")
        };
        assert_eq!(segments[0].as_str(), "second_package");
        assert_eq!(builds.load(std::sync::atomic::Ordering::Relaxed), 4);
    }

    #[test]
    fn reused_structural_interner_does_not_reuse_package_content() {
        const ELABORATOR: &str = "package_content_probe";

        fn package(message: &str) -> Package {
            let provider = format!(
                "module probe/elaborators; \
                 import __comptime__; \
                 pure fn package_content_probe_impl( \
                   ct: __Comptime__, _source: __Type__, _value: __Checked_term__ \
                 ) -> __Checked_term__ {{ __elab_error__(ct, \"{message}\") }} \
                 pub elab package_content_probe : [Source] Source -> Source {{ \
                   impl package_content_probe_impl; \
                 }};"
            );
            lowered_package(&[
                ("probe/elaborators.kio", &provider),
                (
                    "probe/main.kio",
                    "module probe/main; \
                     import probe/elaborators(package_content_probe); \
                     fn run() -> . { package_content_probe!(()) }",
                ),
            ])
        }

        fn diagnostic_message(result: Result<Elaborations, Vec<LocatedError>>) -> String {
            let errors = result.expect_err("the probe elaborator should reject its call");
            errors
                .first()
                .expect("one elaborator diagnostic")
                .error
                .diagnostic()
                .message
                .clone()
        }

        start_user_elaborator_artifact_build_probe(ELABORATOR);
        let interner =
            std::sync::Arc::new(crate::pass::typecheck_core::TypeInterner::<Lowered>::default());

        let first = diagnostic_message(
            check_package_collect_elaborations_collect_errors_with_interner(
                &package("package A implementation"),
                interner.clone(),
            ),
        );
        let second = diagnostic_message(
            check_package_collect_elaborations_collect_errors_with_interner(
                &package("package B implementation"),
                interner,
            ),
        );

        assert!(first.contains("package A implementation"), "got: {first}");
        assert!(second.contains("package B implementation"), "got: {second}");
        assert_eq!(
            finish_user_elaborator_artifact_build_probe(ELABORATOR)
                .values()
                .sum::<usize>(),
            2,
            "each package analysis builds its own exact evaluator artifact"
        );
    }

    #[test]
    fn imported_consumer_batches_share_one_exact_artifact_per_package_check() {
        const ELABORATOR: &str = "artifact_build_probe";
        start_user_elaborator_artifact_build_probe(ELABORATOR);
        let package = lowered_package(&[
            (
                "probe/elaborators.kio",
                "module probe/elaborators; \
                 import __comptime__; \
                 pure fn artifact_build_probe_impl( \
                   _ct: __Comptime__, _source: __Type__, value: __Checked_term__ \
                 ) -> __Checked_term__ { value } \
                 pub elab artifact_build_probe : [Source] Source -> Source { \
                   impl artifact_build_probe_impl; \
                 };",
            ),
            (
                "probe/a.kio",
                "module probe/a; \
                 import probe/elaborators(artifact_build_probe); \
                 fn keep(value: .) -> . { artifact_build_probe!(value) }",
            ),
            (
                "probe/b.kio",
                "module probe/b; \
                 import probe/elaborators(artifact_build_probe); \
                 newtype Wrapped : . { constructor wrap; projector unwrap; }; \
                 fn keep(value: Wrapped) -> Wrapped { artifact_build_probe!(value) }",
            ),
        ]);
        let normalized = crate::pass::alpha_normalize::normalize_package(&package);
        let scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(crate::pass::typecheck_core::TypeInterner::default()),
            );

        check_normalized_package_with_scope_and_execution(
            normalized,
            scope.clone(),
            crate::pass::typecheck_core::TypecheckExecution::AllowParallel,
        )
        .expect("natural user elaborator package checks");

        let builds_by_module = finish_user_elaborator_artifact_build_probe(ELABORATOR);
        assert_eq!(builds_by_module.len(), 1);
        assert_eq!(builds_by_module.values().sum::<usize>(), 1);
        assert!(
            builds_by_module.contains_key("probe/a") || builds_by_module.contains_key("probe/b"),
            "one imported consumer wins the package-scoped singleflight"
        );
        let prepared = scope.memo().snapshot().user_elaborator_prepared;
        assert_eq!(
            prepared.misses, 1,
            "first distinct template prepares the value"
        );
        assert_eq!(
            prepared.hits, 1,
            "second distinct template reuses the prepared value"
        );
        assert_eq!(prepared.first_writes, 1);
    }

    #[test]
    fn eager_result_inference_and_deferred_check_share_one_exact_artifact() {
        const ELABORATOR: &str = "eager_deferred_artifact_probe";
        start_user_elaborator_artifact_build_probe(ELABORATOR);
        let package = lowered_package(&[
            (
                "probe/elaborators.kio",
                "module probe/elaborators; \
                 import __comptime__; \
                 pure fn eager_deferred_artifact_probe_impl( \
                   _ct: __Comptime__, _source: __Type__, value: __Checked_term__, \
                   _target: __Type__ | . \
                 ) -> __Checked_term__ { value } \
                 pub elab eager_deferred_artifact_probe : [Source] Source -> [Target] Target { \
                   impl eager_deferred_artifact_probe_impl; \
                 };",
            ),
            (
                "probe/a_eager.kio",
                "module probe/a_eager; \
                 import probe/elaborators(eager_deferred_artifact_probe); \
                 fn keep() -> . { \
                   let inferred = eager_deferred_artifact_probe!(()); \
                   inferred \
                 }",
            ),
            (
                "probe/b_deferred.kio",
                "module probe/b_deferred; \
                 import probe/elaborators(eager_deferred_artifact_probe); \
                 fn keep() -> . { eager_deferred_artifact_probe!(()) }",
            ),
        ]);
        let normalized = crate::pass::alpha_normalize::normalize_package(&package);
        let scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(crate::pass::typecheck_core::TypeInterner::default()),
            );

        check_normalized_package_with_scope_and_execution(
            normalized,
            scope.clone(),
            crate::pass::typecheck_core::TypecheckExecution::Sequential,
        )
        .expect("eager and deferred user elaborator calls check");

        assert_eq!(
            finish_user_elaborator_artifact_build_probe(ELABORATOR),
            HashMap::from([("probe/a_eager".to_owned(), 1)]),
            "the later deferred call reuses the artifact built for eager result inference"
        );
        let snapshot = scope.memo().snapshot();
        assert_eq!(
            snapshot.user_elaborator.misses, 2,
            "the inferred and expected result inputs produce distinct templates"
        );
        assert_eq!(snapshot.user_elaborator.first_writes, 2);
        assert_eq!(snapshot.user_elaborator_prepared.misses, 1);
        assert_eq!(snapshot.user_elaborator_prepared.hits, 1);
    }

    #[test]
    fn staged_provider_helper_reconstructs_imported_surface_elaboration() {
        const INNER: &str = "nested_artifact_inner";
        const OUTER: &str = "nested_artifact_outer";
        start_user_elaborator_artifact_build_probe(INNER);
        start_user_elaborator_artifact_build_probe(OUTER);
        let package = lowered_package(&[
            (
                "probe/inner.kio",
                "module probe/inner; \
                 import __comptime__; \
                 pure fn nested_artifact_inner_impl( \
                   _ct: __Comptime__, _source: __Type__, value: __Checked_term__ \
                 ) -> __Checked_term__ { value } \
                 pub elab nested_artifact_inner : [Source] Source -> Source { \
                   impl nested_artifact_inner_impl; \
                 };",
            ),
            (
                "probe/outer.kio",
                "module probe/outer; \
                 import __comptime__; \
                 import probe/inner(nested_artifact_inner); \
                 pure fn nested_artifact_outer_impl( \
                   _ct: __Comptime__, _source: __Type__, value: __Checked_term__ \
                 ) -> __Checked_term__ { nested_artifact_inner!(value) } \
                 pub elab nested_artifact_outer : [Source] Source -> Source { \
                   impl nested_artifact_outer_impl; \
                 };",
            ),
            (
                "probe/consumer.kio",
                "module probe/consumer; \
                 import probe/outer(nested_artifact_outer); \
                 fn keep() -> . { nested_artifact_outer!(()) }",
            ),
        ]);

        check_package(&package).expect("provider helper surface elaboration is reconstructed");

        assert_eq!(
            finish_user_elaborator_artifact_build_probe(INNER),
            HashMap::from([("probe/outer".to_owned(), 1)])
        );
        assert_eq!(
            finish_user_elaborator_artifact_build_probe(OUTER),
            HashMap::from([("probe/consumer".to_owned(), 1)])
        );
    }

    fn replay_template_with_type_argument(
        module: &Module,
        elaborations: &mut Elaborations,
        values: &[Expr],
        arg: crate::ast::Type<UncheckedPrime>,
        capture_imports: &[UserElaboratorTemplateGeneratedImport],
    ) {
        let span = test_span();
        let unit = crate::ast::Type::<UncheckedPrime>::Unit {
            meta: Meta::new(span),
        };
        let checked = crate::normalization::CheckedTerm::type_app_for_test(
            crate::normalization::CheckedTerm::new(
                crate::ast::Expr::<UncheckedPrime>::Unit {
                    occurrence: Default::default(),
                    meta: Meta::new(span),
                },
                unit.clone(),
            ),
            arg,
            unit.clone(),
        );
        let template = Ok(trusted_user_elaborator_template(checked, unit));
        let memo = crate::pass::typecheck_core::MemoCtx::default();
        let mut replay = UserElaboratorReplayEnv {
            module_path: "caller",
            module,
            elaborations,
            package: None,
            memo: &memo,
        };
        user_elaborator_template_to_elaboration(
            &template,
            UserElaboratorReplayInputs {
                values,
                value_adapter: None,
                residual_eta: None,
                ambient_type_names: &HashSet::new(),
                capture_imports,
                quoted: None,
            },
            span,
            &mut replay,
        )
        .expect("template replay");
    }

    #[test]
    fn replayed_template_types_reserve_imports_added_by_value_substitution() {
        let module = lowered_module("module caller; import __intrinsics__;");
        let span = test_span();
        let value = Expr::synth_call(
            Expr::Path {
                occurrence: Default::default(),
                segments: vec![crate::ast::PathSegment::new("__left__", span)],
                meta: Meta::new(span),
                ext: (),
            },
            vec![
                CallArg::Type(Type::Infer {
                    meta: Meta::new(span),
                    ext: (),
                }),
                CallArg::Type(Type::Unit {
                    meta: Meta::new(span),
                }),
                CallArg::Value(Expr::Unit {
                    occurrence: Default::default(),
                    meta: Meta::new(span),
                }),
            ],
            span,
        )
        .with_fresh_occurrence();
        let mut elaborations = Elaborations::new();
        elaborations.record_type_resolution(
            "caller",
            value.site().id,
            0,
            InternedType::fresh_canonical(Type::synth_path(
                vec!["value".to_owned(), "types".to_owned(), "Value".to_owned()],
                Vec::new(),
                span,
            )),
        );
        replay_template_with_type_argument(
            &module,
            &mut elaborations,
            &[value],
            crate::ast::Type::<UncheckedPrime>::synth_path(
                vec![
                    "template".to_owned(),
                    "types".to_owned(),
                    "Result".to_owned(),
                ],
                Vec::new(),
                span,
            ),
            &[],
        );

        let imports = elaborations.prime_requalification_imports_for("caller");
        let value = imports
            .iter()
            .find(|import| import.module_path == "value/types")
            .expect("value substitution import");
        let template = imports
            .iter()
            .find(|import| import.module_path == "template/types")
            .expect("template type import");
        assert_ne!(value.alias, template.alias);
    }

    #[test]
    fn replay_does_not_expand_a_canonical_module_segment_as_a_capture_alias() {
        let module = lowered_module("module caller;");
        let span = test_span();
        let mut elaborations = Elaborations::new();
        replay_template_with_type_argument(
            &module,
            &mut elaborations,
            &[],
            crate::ast::Type::<UncheckedPrime>::synth_path(
                vec!["_q0".to_owned(), "types".to_owned(), "Rep".to_owned()],
                Vec::new(),
                span,
            ),
            &[UserElaboratorTemplateGeneratedImport {
                module_path: "captured/types".to_owned(),
                alias: "_q0".to_owned(),
            }],
        );

        assert!(
            elaborations
                .prime_requalification_imports_for("caller")
                .iter()
                .any(|import| import.module_path == "_q0/types"),
            "canonical module identity must survive capture-alias replay"
        );
    }

    #[test]
    fn template_replay_uses_the_current_capture_import_authority() {
        let module = lowered_module("module caller; import stale/helper as _q0;");
        let span = test_span();
        let unit = crate::ast::Type::<UncheckedPrime>::Unit {
            meta: Meta::new(span),
        };
        let checked = crate::normalization::CheckedTerm::new(
            crate::ast::Expr::<UncheckedPrime>::Path {
                occurrence: Default::default(),
                segments: vec![
                    PathSegment::new("_q0".to_owned(), span),
                    PathSegment::new("helper".to_owned(), span),
                ],
                meta: Meta::new(span),
                ext: (),
            },
            unit.clone(),
        );
        let template = Ok(trusted_user_elaborator_template(checked, unit));
        let current_capture_imports = [UserElaboratorTemplateGeneratedImport {
            module_path: "current/helper".to_owned(),
            alias: "_q0".to_owned(),
        }];
        let memo = crate::pass::typecheck_core::MemoCtx::default();
        let mut elaborations = Elaborations::new();
        let mut replay = UserElaboratorReplayEnv {
            module_path: "caller",
            module: &module,
            elaborations: &mut elaborations,
            package: None,
            memo: &memo,
        };

        let replayed = user_elaborator_template_to_elaboration(
            &template,
            UserElaboratorReplayInputs {
                values: &[],
                value_adapter: None,
                residual_eta: None,
                ambient_type_names: &HashSet::new(),
                capture_imports: &current_capture_imports,
                quoted: None,
            },
            span,
            &mut replay,
        )
        .expect("template replay");

        let [generated] = elaborations.generated_imports_for("caller") else {
            panic!("expected exactly one current capture import")
        };
        assert_eq!(generated.module_path, "current/helper");
        assert_ne!(generated.alias, "_q0");
        let crate::ast::Expr::Path { segments, .. } = replayed.expression else {
            panic!("expected captured helper path")
        };
        assert_eq!(segments[0].as_str(), generated.alias.as_str());
    }

    #[test]
    fn user_elaborator_memo_verification_ignores_call_site_spans() {
        let template_at = |span| {
            let ty = crate::ast::Type::<UncheckedPrime>::Unit {
                meta: Meta::new(span),
            };
            trusted_user_elaborator_template(
                crate::normalization::CheckedTerm::template_value(0, ty.clone()),
                ty,
            )
        };
        let first = template_at(Span::new(10, 11));
        let second = template_at(Span::new(90, 91));

        assert_eq!(
            TypeMemoKey::from_type(&first.result_ty),
            TypeMemoKey::from_type(&second.result_ty),
        );
        assert_eq!(
            user_elaborator_template_verification_expr(&first),
            user_elaborator_template_verification_expr(&second),
        );

        let function_at = |abi_arity| crate::ast::Type::<UncheckedPrime>::Function {
            param: Box::new(first.result_ty.clone()),
            ret: Box::new(second.result_ty.clone()),
            meta: Meta::new(Span::new(20, 21)),
            abi_arity,
            caps: (),
        };
        let unary = function_at(1);
        let binary = function_at(2);
        assert_eq!(
            TypeMemoKey::from_type(&unary),
            TypeMemoKey::from_type(&binary),
        );
        assert_ne!(
            user_elaborator_result_type_verification_key(&unary),
            user_elaborator_result_type_verification_key(&binary),
        );
    }

    #[test]
    fn captured_import_alias_is_reallocated_in_the_replay_module() {
        let helper = lowered_module(
            "module pkg/helper; \
             pub fn helper() -> . { () }",
        );
        let other = lowered_module(
            "module pkg/other; \
             pub fn other() -> . { () }",
        );
        let elaborators = lowered_module(
            "module pkg/elaborators; \
             import __comptime__; \
             import pkg/helper as h; \
             pub pure fn capture_impl(ct: __Comptime__, helper: __Checked_term__) -> __Checked_term__ { \
               __term_call__(ct, __term_type__(ct, helper), helper, __term_unit__(ct)) \
             } \
             pub elab capture_demo : . -> . { captures h.helper; impl capture_impl; };",
        );
        let main = lowered_module(
            "module pkg/main; \
             import pkg/elaborators(capture_demo); \
             import pkg/other as h; \
             pub fn run() -> . { capture_demo!() }",
        );
        let package = Package::build(
            Path::new(""),
            vec![
                (PathBuf::from("pkg/helper.kio"), helper),
                (PathBuf::from("pkg/other.kio"), other),
                (PathBuf::from("pkg/elaborators.kio"), elaborators),
                (PathBuf::from("pkg/main.kio"), main),
            ],
            None,
        )
        .expect("package");

        let prime = check_package(&package).expect("captured import replay");
        let main = &prime.module("pkg/main").expect("main module").module;
        assert!(main.imports.iter().any(|import_| {
            matches!(
                &import_.kind,
                ImportKind::Qualified { path, alias }
                    if module_import_path(path) == "pkg/helper" && alias != "h"
            )
        }));
    }

    // ---- Cross-module alias unfolding ------------------------------

    #[test]
    fn cross_module_type_alias_unfolds_in_consumer() {
        use crate::pass::resolve::Package;
        use std::path::{Path, PathBuf};
        // Per `specs/package.md` § Module-name rules, the declared
        // segments equal the file's path relative to the package
        // root. With no package file, the storage key is the
        // declared name verbatim — consumer-side `import pkg/aliases(Same);`
        // finds the module declared `module pkg/aliases;`
        // at `pkg/aliases.kio`.
        let helper = lowered_module(
            "module pkg/aliases; \
             pub type Same = .;",
        );
        let consumer = lowered_module(
            "module pkg/consumer; \
             import pkg/aliases(Same); \
             fn make() -> Same { () }",
        );
        let package = Package::build(
            Path::new(""),
            vec![
                (PathBuf::from("pkg/aliases.kio"), helper),
                (PathBuf::from("pkg/consumer.kio"), consumer),
            ],
            None,
        )
        .unwrap();
        check_package(&package).unwrap_or_else(|e| panic!("expected ok, got {e:?}"));
    }

    #[test]
    fn qualified_callee_identity_survives_direct_and_let_bound_application() {
        use crate::pass::resolve::Package;
        use std::path::{Path, PathBuf};

        for body in ["d.id(value)", "let f = d.id; f(value)"] {
            let modules = vec![
                (
                    PathBuf::from("types.kio"),
                    lowered_module("module types; pub host type Value role(bool);"),
                ),
                (
                    PathBuf::from("other.kio"),
                    lowered_module("module other; pub host type Value role(i32);"),
                ),
                (
                    PathBuf::from("dep.kio"),
                    lowered_module(
                        "module dep; import types as types; \
                         pub type Flag = types.Value & types.Value; \
                         pub fn id(value: Flag) -> Flag { value }",
                    ),
                ),
                (
                    PathBuf::from("shadow.kio"),
                    lowered_module(
                        "module shadow; import other as other; \
                         pub type Flag = other.Value & other.Value;",
                    ),
                ),
                (
                    PathBuf::from("main.kio"),
                    lowered_module(&format!(
                        "module main; import dep as d; import other as types; import shadow as dep; \
                         fn call(value: types.Value & types.Value) -> d.Flag {{ {body} }}"
                    )),
                ),
            ];
            let package = Package::build(Path::new(""), modules, None).expect("package build");
            let err = check_package(&package).expect_err("callee identity mismatch must reject");
            assert!(
                matches!(err.error, Error::Type(_)),
                "expected type error for `{body}`, got {:?}",
                err.error
            );
        }
    }

    #[test]
    fn selective_import_resolves_host_fn_and_host_type() {
        use crate::pass::resolve::Package;
        use std::path::{Path, PathBuf};
        // Host items are ordinary public declarations under normal
        // scoping. A consumer that selectively imports a `host fn` and a
        // role-bearing `host type` must see both: the host fn as a
        // callable name (regression — a selective `import m(foo);`
        // where `foo` is a host fn previously left `foo` unbound, since
        // only qualified `m.foo` access resolved), and the host type as
        // a role-bearing type its literal annotations can name.
        let producer = lowered_module(
            "module pkg/producer; \
             pub host type Text role(str); \
             pub host fn emit(p0: Text) -> .;",
        );
        let consumer = lowered_module(
            "module pkg/consumer; \
             import pkg/producer(emit, Text); \
             pub fn run() -> . { emit(\"hi\"(Text)) }",
        );
        let package = Package::build(
            Path::new(""),
            vec![
                (PathBuf::from("pkg/producer.kio"), producer),
                (PathBuf::from("pkg/consumer.kio"), consumer),
            ],
            None,
        )
        .unwrap();
        check_package(&package).unwrap_or_else(|e| panic!("expected ok, got {e:?}"));
    }

    #[test]
    fn if_then_else_without_role_bool_errors() {
        let m = module(
            "module pkg/main; \
             import __intrinsics__; \
             fn pick() -> . { \
               __if_then_else__(., (), .() { () }, .() { () }) \
             }",
        );
        let res = check_module_with_package_file(&m, None, None);
        match res {
            Err(Error::Type(Diagnostic { message, .. })) => {
                assert!(
                    message.contains(
                        "no `role(bool)` host type is in unqualified lexical scope; \
                         `__if_then_else__` requires one"
                    ),
                    "got: {message}"
                );
            }
            other => panic!("expected Type error, got {other:?}"),
        }
    }

