    #[test]
    fn fit_function_bottom_return_widens_to_unit_return() {
        // fit!'s Bottom-source carve-out: source function `I32 -> !`
        // is coerced into `I32 -> .` by walking the function-arrow
        // covariantly on the return. Without the carve-out, the
        // leaf would reject "non-matching atoms"; with it, the
        // return is `__absurd__`-coerced.
        ok("module x; \
            fn always_diverge(_unused: .) -> ! { always_diverge(()) } \
            fn widen() -> . -> . { fit!(always_diverge) }");
    }

    #[test]
    fn fit_bottom_source_top_level_works() {
        // fit!(x: !, A) succeeds for any atomic A. We use a fn that
        // recurses (to avoid needing a `!`-valued literal) and pipe
        // its result through fit! with a concrete target.
        ok("module x; \
            fn diverge() -> ! { diverge() } \
            fn use_diverge() -> . { fit!(diverge(), .) }");
    }

    #[test]
    fn type_arg_inference_full_drop_two_adjacent_type_args_works() {
        // Full elision is accepted for any binder count — the
        // unifier pins each binder from the value-arg types.
        // `__pair__` declares `[A][B](x: A, y: B)`; a fully-
        // elided `__pair__(x, y)` solves `[A] := .`,
        // `[B] := .` from the value args.
        ok("module pkg/main; \
            import __intrinsics__; \
            fn use_pair(x: ., y: .) -> (. & .) { __pair__(x, y) }");
    }

    #[test]
    fn type_arg_inference_full_drop_two_adjacent_type_args_explicit_underscore_works() {
        // The user can also spell `_` placeholders explicitly;
        // the unifier solves the same substitution.
        ok("module pkg/main; \
            import __intrinsics__; \
            fn use_pair() -> (. & .) { __pair__(_, _, (), ()) }");
    }

    #[test]
    fn type_arg_inference_through_app_binds_payload() {
        // `peel`'s parameter is `Box(A)` (a kind-`*→*` brand applied
        // to the binder `A`); the call site's value-arg has type
        // `Box(.)`. `unify_pattern` must recurse through the applied
        // `Type::Path` (head against head, arg against arg) to bind
        // `[A] := .`. Without the arg-recursion the unifier falls
        // through to `require_type_equiv`, which rejects the
        // inferred-binder shape against the concrete one.
        ok("module pkg/main; \
            newtype Box[A] : A { pub constructor mk_box; pub projector un_box; }; \
            fn lift[A](x: A) -> Box(A) { Box.mk_box(x) } \
            fn peel[A](x: Box(A)) -> A { Box.un_box(x) } \
            fn round_trip() -> . { peel(lift(())) }");
    }

    #[test]
    fn type_arg_inference_directly_solves_applied_hkt_head() {
        ok("module pkg/main; \
            newtype Box[A] : A { pub constructor mk_box; pub projector un_box; }; \
            fn keep[*F][A](value: F(A)) -> F(A) { value } \
            fn round_trip(value: Box(.)) -> Box(.) { keep(value) }");
    }

    // ---- arbitrary annotations on `fn` signatures ----------------------------

    #[test]
    fn fn_param_annotation_consistent_with_synth_works() {
        // A concrete value-parameter annotation binds the parameter
        // before the body is visited. The body then synthesizes the
        // bare `x` path at that concrete type.
        ok("module pkg/main; \
            fn id[A](x: A) -> A { x } \
            fn use_id() -> . { id(_, (.(x: .) { x })(())) }");
    }

    #[test]
    fn fn_param_annotation_underscore_in_arg_position_defers_to_flow() {
        // `: _` on a `fn` value parameter when the fn is itself a
        // call's value arg: check mode binds the whole missing slot
        // from the expected function type. This is the same path as
        // the no-annotation form.
        ok("module pkg/main; \
            fn apply[A](f: A -> ., x: A) -> . { f(x) } \
            fn use_apply() -> . { apply(., .(x: _) { () }, ()) }");
    }

    #[test]
    fn fn_ret_ty_annotation_consistent_with_flow_works() {
        // A `fn` return-type annotation that matches the
        // bidirectional flow's expected return type type-checks.
        // `check_fn_against` verifies the annotation against the
        // expected return type pulled from the call's signature.
        ok("module pkg/main; \
            fn apply[A](f: A -> ., x: A) -> . { f(x) } \
            fn use_apply() -> . { apply(., .(x) -> . { () }, ()) }");
    }

    #[test]
    fn fn_ret_ty_annotation_underscore_defers_to_flow() {
        // `-> _` on a `fn` return-type slot is identical to no
        // annotation: the bidirectional flow drives the fn's
        // return type.
        ok("module pkg/main; \
            fn apply[A](f: A -> ., x: A) -> . { f(x) } \
            fn use_apply() -> . { apply(., .(x) -> _ { () }, ()) }");
    }

    #[test]
    fn fn_param_annotation_inconsistent_with_flow_errors() {
        // A concrete `: T` annotation that contradicts the
        // bidirectional flow's expected type fails with a normal
        // type error. With `[A] := .` pinned explicitly, the fn
        // is checked against `. -> .`; the explicit
        // `: (. & .)` annotation contradicts the expected `.`.
        let m = module(
            "module pkg/main; \
             fn apply[A](f: A -> ., x: A) -> . { f(x) } \
             fn use_apply() -> . { apply(., .(x: (. & .)) { () }, ()) }",
        );
        match check_module(&m) {
            Err(Error::Type(_)) => {}
            other => panic!("expected Type error, got {other:?}"),
        }
    }

    #[test]
    fn fn_ret_ty_annotation_inconsistent_with_flow_errors() {
        // A concrete `-> R` annotation that contradicts the
        // bidirectional flow's expected return type fails with a
        // normal type error. `apply`'s `f: A -> .` pins the
        // expected return type to `.`; the explicit `-> (. & .)`
        // contradicts it.
        let m = module(
            "module pkg/main; \
             fn apply[A](f: A -> ., x: A) -> . { f(x) } \
             fn use_apply() -> . { apply(., .(x) -> (. & .) { () }, ()) }",
        );
        match check_module(&m) {
            Err(Error::Type(_)) => {}
            other => panic!("expected Type error, got {other:?}"),
        }
    }

    #[test]
    fn fn_ret_ty_annotation_inconsistent_with_synth_body_errors() {
        // The synth-only path: the fn carries a concrete `: T`
        // annotation, so synthesis can complete; the
        // explicit `-> R` annotation is then verified against the
        // body's synthesized type. Here the body's `x` synthesizes
        // to `.` (from the param annotation), but the return
        // annotation declares `(. & .)`.
        let m = module(
            "module pkg/main; \
             fn use_fn() -> . { (.(x: .) -> (. & .) { x })(()) }",
        );
        match check_module(&m) {
            Err(Error::Type(_)) => {}
            other => panic!("expected Type error, got {other:?}"),
        }
    }

    #[test]
    fn fn_param_nested_infer_accepted_in_check_mode() {
        // Nested `_` inside a lambda value-parameter annotation is
        // admissible when the lambda literal sits in a checked
        // position — the surrounding expected type structurally
        // fills the placeholder. Here the lambda is passed to
        // `apply` whose first param has the concrete fn type
        // `((. & .)) -> .`; the lambda's annotation `(. & _)`
        // matches structurally with the second `_` resolving to
        // `.`. The resolved expected slot binds the parameter before
        // the body is checked.
        ok("module pkg/main; \
             fn apply(f: ((. & .)) -> ., x: (. & .)) -> . { f(x) } \
             fn use_apply() -> . { apply(.(x: (. & _)) { () }, ((), ())) }");
    }

    #[test]
    fn fn_ret_ty_nested_infer_accepted_in_check_mode() {
        // Same as above but for the return-type slot — the lambda's
        // `-> (. & _)` is checked structurally against the
        // expected return `(. & .)`.
        ok("module pkg/main; \
             fn apply(f: . -> (. & .), x: .) -> (. & .) { f(x) } \
             fn use_apply() -> (. & .) { apply(.(x) -> (. & _) { ((), ()) }, ()) }");
    }

    #[test]
    fn fn_param_nested_infer_rejected_in_synth_mode() {
        // A partial annotation in a synthesis-only position — here
        // the `let`-bound RHS, where no expected type pushes in —
        // is a type error: the nested `_` has nothing to resolve
        // against. The diagnostic must point at the placeholder
        // and explain the missing context.
        let m = module(
            "module pkg/main; \
             fn use_let() -> . { let f = .(x: (. & _)) { () }; f(((), ())) }",
        );
        match check_module(&m) {
            Err(Error::Type(Diagnostic { message, .. })) => {
                assert!(
                    message.contains(
                        "nested `_` placeholder in a `fn` signature has no surrounding context"
                    ),
                    "got: {message}"
                );
            }
            other => panic!("expected Type error, got {other:?}"),
        }
    }

    #[test]
    fn fn_def_mid_position_binder_typechecks() {
        // `(P0)[A] P1 -> R` per `specs/language.md` § Type
        // parameters: a binder in the middle of a fn's param list
        // narrows scope to its right and breaks the value-product
        // run.
        // The result type is
        //   `Function(P0, Forall([A], Function(A, R)))`
        // i.e., a 1-arg function whose result is a polymorphic
        // 1-arg function. The body sees both `x` and `y` in
        // scope flat per § 4 (declaration-side binders scope over
        // the entire body, regardless of position). Calling via
        // the curried form `pick("hi")((), ())` works under the
        // call-site flattening logic.
        ok("module x; \
            fn pick(x: .)[A](y: A) -> . { x }");
    }

    #[test]
    fn fn_def_trailing_binder_typechecks() {
        // `(P0, P1)[A] -> R` — trailing binder wraps the ret
        // type directly. Type: `Function(Product(P0, P1),
        // Forall([A], A))`. Body uses `__absurd__` to construct a
        // value of any `a`, which only typechecks because the
        // call is unreachable (no inhabited `!` value exists).
        ok("module x; \
            import __intrinsics__; \
            fn forever(b: !)[A] -> A { __absurd__(A, b) }");
    }

    #[test]
    fn fn_def_multi_binder_run_at_mid_position() {
        // `(P0)[A][B] P1 -> R` — consecutive binders cluster
        // into a single Forall but the curry-break is preserved.
        // Type: `Function(P0, Forall([A], Forall([B], Function(A, R))))`.
        ok("module x; \
            fn pick_double(x: .)[A][B](y: A) -> . { x }");
    }

    // ---- UFCS dispatch: whole-receiver match ---------------------------

    /// Whole-receiver match against a product-typed first param:
    /// receiver `(A & B)` unifies with first param `(A & B)`.
    #[test]
    fn ufcs_whole_receiver_matches_product_param() {
        ok("module x; \
            newtype A : . { pub constructor mk_a; pub projector un_a; }; \
            newtype B : . { pub constructor mk_b; pub projector un_b; }; \
            fn target(self: (A & B)) -> . { () } \
            fn caller(r: (A & B)) -> . { r.>target }");
    }

    /// Whole-receiver mismatch: receiver wider than the callee's
    /// first param. Strict dispatch rejects without trying to project a
    /// sub-conjunct; the user has to narrow with
    /// `onto!` first.
    #[test]
    fn ufcs_whole_receiver_mismatch_rejected() {
        let m = module(
            "module x; \
             newtype A : . { pub constructor mk_a; pub projector un_a; }; \
             newtype B : . { pub constructor mk_b; pub projector un_b; }; \
             fn target(self: A) -> . { () } \
             fn caller(r: (A & B)) -> . { r.>target }",
        );
        let err = check_module(&m).expect_err("expected UFCS dispatch failure");
        match err {
            Error::Type(Diagnostic { message, .. }) => {
                assert!(message.contains("type mismatch"), "got: {message}");
            }
            other => panic!("expected Type error, got {other:?}"),
        }
    }

    /// N right-folded value params: receiver fills the FIRST param;
    /// the remaining params are supplied as positional value args
    /// in the call's parens.
    #[test]
    fn ufcs_n_right_folded_params_receiver_fills_first() {
        ok("module x; \
            newtype A : . { pub constructor mk_a; pub projector un_a; }; \
            newtype B : . { pub constructor mk_b; pub projector un_b; }; \
            fn target(a: A, b: B) -> . { () } \
            fn caller(a_val: A, b_val: B) -> . { a_val.>target(b_val) }");
    }

    #[test]
    fn ufcs_unit_receiver_fills_first_polymorphic_value_arg() {
        ok("module x; \
            newtype B : . { pub constructor mk_b; pub projector un_b; }; \
            fn const2[A][B](x: A, y: B) -> B { y } \
            fn caller(b: B) -> B { ().>const2(b) }");
    }

    /// Monomorphic callee with a product-typed first param. The
    /// receiver's type must equal the param's type; no projection
    /// or conjunct flattening.
    #[test]
    fn ufcs_mono_callee_whole_receiver() {
        ok("module x; \
            newtype A : . { pub constructor mk_a; pub projector un_a; }; \
            newtype B : . { pub constructor mk_b; pub projector un_b; }; \
            fn target(self: (A & B)) -> . { () } \
            fn caller(r: (A & B)) -> . { target(r) }");
    }

    // ---- Position-keyed index ------------------------------------------
    //
    // The LSP's hover / goto-definition / references index is populated for
    // every node the typer visits in `Lowered` mode;
    // these tests assert a representative sample of (span, type,
    // binder) triples are present after a typer run, and that the
    // disjointness contract on parallel-merge holds.

    /// Type the source through the package-aware entry point and
    /// return the `Elaborations` table the typer recorded — the
    /// position index lives at `elabs.position_index()`. Helper for
    /// the position-index tests.
    fn collect_elabs(src: &str) -> Elaborations {
        use crate::pass::resolve::Package;
        use std::path::{Path, PathBuf};
        let m = lowered_module(src);
        // The file path must match the `module …;` declaration so the
        // `Package::build` path-coherence check is satisfied. The path
        // relative to the (empty) package root is the segments after
        // the package name; a single-segment `module pkg;` lives at
        // `pkg.kio`.
        let segs = &m.path.segments;
        let rest = &segs[1.min(segs.len())..];
        let mut file_path = PathBuf::new();
        for seg in &rest[..rest.len().saturating_sub(1)] {
            file_path.push(&seg.name);
        }
        file_path.push(format!(
            "{}.kio",
            rest.last()
                .or_else(|| segs.last())
                .map(|s| s.name.as_str())
                .unwrap_or("module")
        ));
        let package =
            Package::build(Path::new(""), vec![(file_path, m)], None).expect("package builds");
        check_package_collect_elaborations(&package).expect("typecheck succeeds")
    }

    #[test]
    fn elaborator_implementation_path_reuses_one_synthesis_for_whole_and_leaf_positions() {
        let provider = concat!(
            "module provider;\n",
            "import __comptime__;\n",
            "pub pure fn unit_impl(ct: __Comptime__) -> __Checked_term__ { __term_unit__(ct) }\n",
        );
        let main = concat!(
            "module main;\n",
            "import provider as helper;\n",
            "elab unit : . -> . { impl helper.unit_impl; };\n",
        );
        let whole = source_span(main, "helper.unit_impl");
        let leaf = source_span(main, "unit_impl");
        reset_user_elaborator_implementation_syntheses();
        let package = lowered_package(&[("provider.kio", provider), ("main.kio", main)]);
        let elaborations =
            check_package_collect_elaborations(&package).expect("qualified implementation checks");
        let index = elaborations.position_index();

        let whole_ty = index
            .type_at("main", whole)
            .expect("whole implementation path has a type");
        let leaf_ty = index
            .type_at("main", leaf)
            .expect("implementation leaf has a type");
        assert_eq!(whole_ty, leaf_ty);
        assert!(matches!(
            index.binder_at("main", leaf),
            Some(ResolvedBinder::Fn { module_path, name })
                if module_path == "provider" && name == "unit_impl"
        ));
        assert_eq!(
            user_elaborator_implementation_syntheses(),
            1,
            "publishing a second position must not synthesize the implementation again"
        );
    }

    #[test]
    fn single_segment_elaborator_implementation_has_one_shared_position() {
        let source = concat!(
            "module main;\n",
            "import __comptime__;\n",
            "pure fn unit_impl(ct: __Comptime__) -> __Checked_term__ { __term_unit__(ct) }\n",
            "elab unit : . -> . { impl unit_impl; };\n",
        );
        let start = source.rfind("unit_impl").expect("implementation path");
        let whole = Span::new(start as u32, (start + "unit_impl".len()) as u32);
        let leaf = whole;
        reset_user_elaborator_implementation_syntheses();
        let elaborations = collect_elabs(source);
        let index = elaborations.position_index();

        assert_eq!(whole, leaf);
        let implementation_ty = index
            .type_at("main", leaf)
            .expect("single-segment implementation has a type");
        assert_eq!(index.type_at("main", leaf), Some(implementation_ty));
        assert!(matches!(
            index.binder_at("main", leaf),
            Some(ResolvedBinder::Fn { module_path, name })
                if module_path == "main" && name == "unit_impl"
        ));
        assert_eq!(
            user_elaborator_implementation_syntheses(),
            1,
            "one-segment whole/leaf equality must not trigger a second synthesis"
        );
    }

    /// Every expression node the typer visits records its synthesized
    /// type in the position index. A tiny module with `let y = x; y`
    /// produces three expression visits (the `x` value, the `y` body,
    /// the surrounding fn body) and each shows up by its source span.
    #[test]
    fn position_index_records_local_let_binding_types() {
        let src = "module x; fn f(x: .) -> . { let y = x; y }";
        let elabs = collect_elabs(src);
        let idx = elabs.position_index();
        // Sanity: at least three entries — the `x` value, the let
        // body expression, and the trailing `y` reference. The
        // exact total depends on what counts as a sub-expression
        // the typer visits; the lower bound is sufficient.
        assert!(
            idx.type_count() >= 3,
            "position index should record per-expression types; got {} entries",
            idx.type_count()
        );
    }

    #[test]
    fn failed_simple_goal_call_does_not_publish_earlier_argument_position_types() {
        let module = module(
            "module x; \
             host type I32; \
             host type Text; \
             fn same[A](first: A, second: A) -> . { () } \
             fn bad(left: I32, right: Text) -> . { same(left, right) }",
        );
        let normalized = crate::pass::alpha_normalize::normalize_module(&module);
        let module = normalized.module();
        let (item_index, bad) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(def) if def.name == "bad" => Some((index, def)),
                _ => None,
            })
            .expect("bad function");
        let Expr::Call { args, .. } = &bad.body else {
            panic!("bad body should be one call")
        };
        let argument_spans = args
            .iter()
            .map(|arg| match arg {
                CallArg::Value(value) => value.span(),
                CallArg::Type(_) => panic!("bad call should contain only value arguments"),
            })
            .collect::<Vec<_>>();
        let [
            crate::ast::SignatureParam::Value(left),
            crate::ast::SignatureParam::Value(right),
        ] = bad.sig.params.as_slice()
        else {
            panic!("bad function should have two value parameters")
        };
        let env = ModuleEnv::build(module, None, None, None).expect("env");
        let mut elaborations = Elaborations::new();
        let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
        tcx.push_value(
            left.name.clone(),
            left.ty.clone().expect("left parameter annotation"),
        );
        tcx.push_value(
            right.name.clone(),
            right.ty.clone().expect("right parameter annotation"),
        );

        let error = match synth_expr(&bad.body, &mut tcx) {
            Err(error) => error,
            Ok(_) => panic!("I32 and Text must conflict"),
        };
        assert!(
            error.diagnostic().message.contains("type mismatch"),
            "got: {}",
            error.diagnostic().message
        );
        drop(tcx);

        for argument_span in argument_spans {
            assert!(
                elaborations
                    .position_index()
                    .types_iter()
                    .all(|((module_path, span), _)| {
                        module_path != "x" || *span != argument_span
                    }),
                "a failed later constraint published an earlier argument's staged type"
            );
        }
    }

    #[test]
    fn position_index_records_nested_application_completions() {
        fn source_span(source: &str, needle: &str) -> Span {
            let start = source.find(needle).expect("test expression is present");
            Span::new(
                u32::try_from(start).expect("test source fits in a span"),
                u32::try_from(start + needle.len()).expect("test source fits in a span"),
            )
        }

        fn assert_bare_path(ty: &Type, expected: &str) {
            let Type::Path { segments, args, .. } = ty else {
                panic!("expected bare path `{expected}`, got {ty:?}");
            };
            assert!(args.is_empty(), "expected bare path, got {ty:?}");
            assert_eq!(
                segments
                    .iter()
                    .map(|segment| segment.name.as_str())
                    .collect::<Vec<_>>(),
                [expected],
            );
        }

        fn assert_path_leaf(ty: &Type, expected: &str) {
            let Type::Path { segments, args, .. } = ty else {
                panic!("expected path ending in `{expected}`, got {ty:?}");
            };
            assert!(args.is_empty(), "expected unparameterized path, got {ty:?}");
            assert_eq!(
                segments.last().map(|segment| segment.name.as_str()),
                Some(expected),
            );
        }

        let src = concat!(
            "module x;\n",
            "newtype Marker : . { constructor mark; projector unmark; };\n",
            "fn identity[A](value: A) -> A { value }\n",
            "fn keep[A](value: A) -> A { value }\n",
            "fn preserve_marker(value: Marker) -> Marker { value }\n",
            "fn from_marker[A](_marker: Marker) -> A -> A { .(value: A) -> A { value } }\n",
            "fn view[S][A](get: S -> A, value: S) -> A { get(value) }\n",
            "fn pair_fst[A][B]() -> (A & B) -> A { .(left: A, _right: B) -> A { left } }\n",
            "fn immediate[T](value: T) -> T { keep(identity(value)) }\n",
            "fn immediate_ufcs(marker: Marker) -> Marker { keep(marker.>preserve_marker) }\n",
            "fn deferred_call[C][D](c: C, d: D) -> C { view(pair_fst(), (c, d)) }\n",
            "fn deferred_ufcs[T](marker: Marker, value: T) -> T { ",
            "view(marker.>from_marker, value) }\n",
        );
        let elabs = collect_elabs(src);
        let index = elabs.position_index();

        let immediate = index
            .type_at("x", source_span(src, "identity(value)"))
            .expect("immediately completed nested call has a position type");
        assert_bare_path(immediate, "T");

        let immediate_ufcs = index
            .type_at("x", source_span(src, "marker.>preserve_marker"))
            .expect("immediately completed regular UFCS has a position type");
        assert_path_leaf(immediate_ufcs, "Marker");

        let deferred_call = index
            .type_at("x", source_span(src, "pair_fst()"))
            .expect("deferred nested call has a position type after completion");
        let Type::Function {
            param: call_param,
            ret: call_ret,
            ..
        } = deferred_call
        else {
            panic!("expected deferred call to resolve to a function, got {deferred_call:?}");
        };
        let Type::Product { left, right, .. } = call_param.as_ref() else {
            panic!("expected deferred call parameter to be a product, got {call_param:?}");
        };
        assert_bare_path(left, "C");
        assert_bare_path(right, "D");
        assert_bare_path(call_ret, "C");

        let deferred_ufcs = index
            .type_at("x", source_span(src, "marker.>from_marker"))
            .expect("deferred regular UFCS has a position type after completion");
        let Type::Function {
            param: ufcs_param,
            ret: ufcs_ret,
            ..
        } = deferred_ufcs
        else {
            panic!("expected deferred UFCS to resolve to a function, got {deferred_ufcs:?}");
        };
        assert_bare_path(ufcs_param, "T");
        assert_bare_path(ufcs_ret, "T");
    }

    #[test]
    fn position_index_merges_entries_from_multiple_fn_bodies() {
        let src = "module x; fn a() -> . { () } fn b() -> . { () }";
        let elabs = collect_elabs(src);
        let idx = elabs.position_index();
        assert!(
            idx.type_count() >= 2,
            "per-module elaboration merge should retain entries from both fn bodies; got {}",
            idx.type_count()
        );
    }

    #[test]
    fn position_index_presents_only_exact_binder_facts() {
        fn path_name(ty: &Type) -> &str {
            let Type::Path { segments, .. } = ty else {
                panic!("expected path type");
            };
            &segments[0].name
        }

        let module_path = "main".to_owned();
        let decl_span = Span::new(10, 11);
        let type_span = Span::new(20, 21);
        let let_span = Span::new(30, 31);
        let type_args_span = Span::new(40, 40);
        let use_span = Span::new(50, 51);
        let value_decl_span = Span::new(60, 65);
        let value_use_span = Span::new(70, 75);
        let hygienic = Type::synth_path(vec!["A_n2".to_owned()], Vec::new(), decl_span);

        let mut presentation = crate::pass::binder_presentation::BinderPresentation::default();
        presentation.record_name(&module_path, decl_span, "A_n2", "A");
        presentation.record_name(&module_path, value_decl_span, "apply_2", "apply");

        let mut index = PositionIndex::new();
        index
            .types
            .insert((module_path.clone(), type_span), hygienic.clone());
        index.inlay_let_types.insert(
            (module_path.clone(), let_span),
            (hygienic.clone(), Default::default()),
        );
        index.record_inlay_type_args(
            &module_path,
            crate::ast::ExpressionSite {
                id: crate::ast::ExpressionOccurrence::fresh().key(),
                span: type_args_span,
            },
            type_args_span,
            0,
            vec![hygienic],
            Default::default(),
        );
        index.binders.insert(
            (module_path.clone(), use_span),
            ResolvedBinder::TypeParam {
                name: "A_n2".to_owned(),
                decl_span: Some(decl_span),
            },
        );
        index.binders.insert(
            (module_path.clone(), value_use_span),
            ResolvedBinder::Local {
                name: "apply_2".to_owned(),
                decl_span: Some(value_decl_span),
            },
        );
        index
            .local_decls
            .insert((module_path.clone(), "A_n2".to_owned()), decl_span);
        index
            .local_decls_by_span
            .insert((module_path.clone(), decl_span), "A_n2".to_owned());

        index.present_binder_names(std::sync::Arc::new(presentation));

        assert_eq!(
            path_name(
                index
                    .types
                    .get(&(module_path.clone(), type_span))
                    .expect("recorded type")
            ),
            "A_n2"
        );
        assert_eq!(
            path_name(
                &index
                    .inlay_let_types
                    .get(&(module_path.clone(), let_span))
                    .expect("recorded let inlay")
                    .0
            ),
            "A_n2"
        );
        assert_eq!(
            path_name(
                &index
                    .inlay_type_args
                    .get(&(module_path.clone(), type_args_span))
                    .expect("recorded type arguments")[0]
                    .types[0]
            ),
            "A_n2"
        );
        assert!(matches!(
            index.binders.get(&(module_path.clone(), use_span)),
            Some(ResolvedBinder::TypeParam { name, .. }) if name == "A"
        ));
        assert!(matches!(
            index.binders.get(&(module_path.clone(), value_use_span)),
            Some(ResolvedBinder::Local { name, .. }) if name == "apply"
        ));
        assert_eq!(
            index
                .local_decls
                .get(&(module_path.clone(), "A_n2".to_owned())),
            Some(&decl_span)
        );
        assert_eq!(
            index
                .local_decls_by_span
                .get(&(module_path, decl_span))
                .map(String::as_str),
            Some("A")
        );
    }

    #[test]
    fn position_index_preserves_shadowed_type_parameter_identity() {
        let module_path = "main".to_owned();
        let outer_decl_span = Span::new(10, 11);
        let inner_decl_span = Span::new(20, 21);
        let outer_use_span = Span::new(30, 31);
        let inner_use_span = Span::new(40, 41);
        let fallback_use_span = Span::new(50, 51);

        let mut presentation = crate::pass::binder_presentation::BinderPresentation::default();
        presentation.record_name(&module_path, outer_decl_span, "A", "A");
        presentation.record_name(&module_path, inner_decl_span, "A_n2", "A");

        let mut index = PositionIndex::new();
        index
            .local_decls
            .insert((module_path.clone(), "A".to_owned()), outer_decl_span);
        index
            .local_decls
            .insert((module_path.clone(), "A_n2".to_owned()), inner_decl_span);
        index
            .local_decls_by_span
            .insert((module_path.clone(), outer_decl_span), "A".to_owned());
        index
            .local_decls_by_span
            .insert((module_path.clone(), inner_decl_span), "A_n2".to_owned());
        index.binders.insert(
            (module_path.clone(), outer_use_span),
            ResolvedBinder::TypeParam {
                name: "A".to_owned(),
                decl_span: Some(outer_decl_span),
            },
        );
        index.binders.insert(
            (module_path.clone(), inner_use_span),
            ResolvedBinder::TypeParam {
                name: "A_n2".to_owned(),
                decl_span: Some(inner_decl_span),
            },
        );
        index.binders.insert(
            (module_path.clone(), fallback_use_span),
            ResolvedBinder::TypeParam {
                name: "A_n2".to_owned(),
                decl_span: None,
            },
        );

        index.present_binder_names(std::sync::Arc::new(presentation));

        assert!(matches!(
            index.binders.get(&(module_path.clone(), outer_use_span)),
            Some(ResolvedBinder::TypeParam {
                name,
                decl_span: Some(span),
            }) if name == "A" && *span == outer_decl_span
        ));
        assert!(matches!(
            index.binders.get(&(module_path.clone(), inner_use_span)),
            Some(ResolvedBinder::TypeParam {
                name,
                decl_span: Some(span),
            }) if name == "A" && *span == inner_decl_span
        ));
        assert!(matches!(
            index.binders.get(&(module_path.clone(), fallback_use_span)),
            Some(ResolvedBinder::TypeParam {
                name,
                decl_span: None,
            }) if name == "A_n2"
        ));
        assert_eq!(
            index.local_decl_at(&module_path, "A"),
            Some(outer_decl_span)
        );
        assert_eq!(
            index.local_decl_at(&module_path, "A_n2"),
            Some(inner_decl_span)
        );
        assert_eq!(
            index
                .local_decls_by_span
                .get(&(module_path.clone(), outer_decl_span))
                .map(String::as_str),
            Some("A")
        );
        assert_eq!(
            index
                .local_decls_by_span
                .get(&(module_path, inner_decl_span))
                .map(String::as_str),
            Some("A")
        );
    }

    #[cfg(feature = "lsp")]
    #[test]
    fn position_index_cancelled_binder_filter_is_transactional() {
        let declaration_span = Span::new(10, 11);
        let use_span = Span::new(20, 21);
        let mut index = PositionIndex::new();
        index.record_local_decl("main", "value", declaration_span);
        index.record_binder(
            "main",
            use_span,
            ResolvedBinder::Local {
                name: "value".to_owned(),
                decl_span: Some(declaration_span),
            },
        );

        let mut visits = 0;
        assert!(!index.try_retain_binders(|_, _, _| {
            visits += 1;
            if visits == 1 { Some(false) } else { None }
        }));

        assert_eq!(visits, 2);
        assert_eq!(index.binder_count(), 2);
        assert!(index.binder_at("main", declaration_span).is_some());
        assert!(index.binder_at("main", use_span).is_some());
        assert!(
            index
                .binder_declarations
                .contains(&("main".to_owned(), declaration_span))
        );
        assert_eq!(index.local_decl_at("main", "value"), Some(declaration_span));
    }

    #[test]
    fn completion_metadata_records_bound_declaration_types() {
        let src = "module x; fn f(unused: . -> ., x: .) -> . { let y = x; y }";
        let elabs = collect_elabs(src);
        let idx = elabs.position_index();
        for (name, expected) in [("unused", ". -> ."), ("x", "."), ("y", ".")] {
            let declaration = idx.local_decl_at("x", name).expect("recorded declaration");
            let ty = idx
                .type_at("x", declaration)
                .expect("bound declaration type");
            let mut rendered = String::new();
            crate::pass::typecheck_core::write_type(ty, &mut rendered);
            assert_eq!(rendered, expected, "{name}");
        }
    }

    /// A local path records the binder whose declaration introduced it.
    #[test]
    fn position_index_records_fn_param_binder() {
        // `x` parameter, used once on the let RHS; `y` let-local,
        // returned. Both go through `lookup_value` →
        // `Kind::Local` → `ResolvedBinder::Local`.
        let src = "module x; fn f(x: .) -> . { let y = x; y }";
        let elabs = collect_elabs(src);
        let idx = elabs.position_index();
        // Scan for the two expected `Local` binders by name.
        let names: std::collections::HashSet<&str> = idx
            .binders_iter()
            .filter_map(|(_, b)| match b {
                ResolvedBinder::Local { name, .. } => Some(name.as_str()),
                _ => None,
            })
            .collect();
        assert!(
            names.contains("x"),
            "expected a Local binder for `x`; found names = {names:?}"
        );
        assert!(
            names.contains("y"),
            "expected a Local binder for `y`; found names = {names:?}"
        );
    }

    #[test]
    fn position_index_lambda_uses_keep_exact_shadowed_declaration_spans() {
        let source = "module x; fn f() -> . -> . { .(value) { \
            let inner = .(value: .) { value }; value } }";
        let elaborations = collect_elabs(source);
        let index = elaborations.position_index();
        let offsets: Vec<_> = source
            .match_indices("value")
            .map(|(offset, _)| offset as u32)
            .collect();
        assert_eq!(offsets.len(), 4);
        for (usage, declaration) in [(offsets[2], offsets[1]), (offsets[3], offsets[0])] {
            let binder = index.binder_at("x", Span::new(usage, usage + 5)).unwrap();
            assert!(
                matches!(binder, ResolvedBinder::Local { decl_span: Some(span), .. } if span.start == declaration),
                "each checked or synthesized lambda use retains its own declaration: {binder:?}"
            );
        }
    }

    /// A reference to a top-level fn from inside another fn's body
    /// records an `Fn` binder at the call-site's identifier
    /// segment. The recorded `module_path` is the consumer's
    /// module path (the binding site is resolved separately on
    /// goto-definition).
    #[test]
    fn position_index_records_top_level_fn_binder() {
        let src = "module x; \
                   fn id[A](v: A) -> A { v } \
                   fn use_id(u: .) -> . { id(u) }";
        let elabs = collect_elabs(src);
        let idx = elabs.position_index();
        // Search the binder map for an `Fn` entry whose name is
        // `id`. The exact span depends on what the parser
        // assigned — span lookup by byte-offset can drift if the
        // identifier's lexical extent doesn't match the test's
        // assumption. The substantive contract is "the binder is
        // recorded somewhere"; the LSP query side will use the
        // cursor's span to look it up.
        let mut found_id = false;
        for ((_mp, _span), binder) in idx.binders_iter() {
            if let ResolvedBinder::Fn { name, .. } = binder
                && name == "id"
            {
                found_id = true;
                break;
            }
        }
        assert!(
            found_id,
            "expected an `Fn`-binder for `id` to be recorded; binder_count = {}",
            idx.binder_count()
        );
    }

    /// A cross-module `import m(foo);` reference records a `Fn`
    /// binder (the `Kind::Fn` and `Kind::CrossModuleFn` cases share
    /// the `Fn` variant; nothing downstream distinguishes them).
    /// The binder records the provider module so the same declaration
    /// has one identity across selective and qualified import surfaces.
    #[test]
    fn position_index_records_cross_module_fn_binder() {
        use crate::pass::resolve::Package;
        use std::path::{Path, PathBuf};
        let helper = lowered_module("module pkg/helper; pub fn h() -> . { () }");
        let consumer =
            lowered_module("module pkg/consumer; import pkg/helper(h); fn main() -> . { h() }");
        let package = Package::build(
            Path::new(""),
            vec![
                // Declared module paths mirror file paths relative to
                // the package root.
                (PathBuf::from("pkg/helper.kio"), helper),
                (PathBuf::from("pkg/consumer.kio"), consumer),
            ],
            None,
        )
        .expect("package builds");
        let elabs = check_package_collect_elaborations(&package).expect("typecheck succeeds");
        let idx = elabs.position_index();
        // Scan the binder map for an `Fn` entry whose key is in
        // the `pkg/consumer` module and whose name is `h`.
        let found = idx.binders_iter().any(|((mp, _span), binder)| {
            mp == "pkg/consumer"
                && matches!(
                    binder,
                    ResolvedBinder::Fn { module_path, name }
                        if module_path == "pkg/helper" && name == "h"
                )
        });
        assert!(
            found,
            "expected an Fn binder for the cross-module `h` call in pkg/consumer; \
             binder_count = {}",
            idx.binder_count()
        );
    }

    #[test]
    fn position_index_uses_provider_identity_for_qualified_callable_leaves() {
        use crate::pass::resolve::Package;
        use std::path::{Path, PathBuf};

        let helper = lowered_module(
            "module pkg/helper; \
             pub fn h() -> . { () } \
             pub newtype Box : . { pub constructor mk; pub projector get; };",
        );
        let consumer = lowered_module(
            "module pkg/consumer; \
             import pkg/helper(Box); \
             import pkg/helper as helper; \
             fn main() -> Box { let _unit = helper.h(); helper.Box.mk(()) }",
        );
        let package = Package::build(
            Path::new(""),
            vec![
                (PathBuf::from("pkg/helper.kio"), helper),
                (PathBuf::from("pkg/consumer.kio"), consumer),
            ],
            None,
        )
        .expect("package builds");
        let elabs = check_package_collect_elaborations(&package).expect("typecheck succeeds");
        let binders = elabs
            .position_index()
            .binders_iter()
            .filter(|((module, _), _)| module == "pkg/consumer")
            .map(|(_, binder)| binder)
            .collect::<Vec<_>>();

        assert!(binders.iter().any(|binder| matches!(
            binder,
            ResolvedBinder::Fn { module_path, name }
                if module_path == "pkg/helper" && name == "h"
        )));
        assert!(binders.iter().any(|binder| matches!(
            binder,
            ResolvedBinder::Newtype { module_path, name }
                if module_path == "pkg/helper" && name == "Box"
        )));
        assert!(binders.iter().any(|binder| matches!(
            binder,
            ResolvedBinder::NewtypeMember { module_path, newtype, member }
                if module_path == "pkg/helper" && newtype == "Box" && member == "mk"
        )));
    }

    #[test]
    fn position_index_splits_identity_alias_head_from_terminal_member() {
        use crate::pass::resolve::Package;
        use std::path::{Path, PathBuf};

        let origin = lowered_module(
            "module origin; \
             pub newtype Tag : . { pub constructor make; pub projector open; };",
        );
        let relay =
            lowered_module("module relay; import origin as source; pub type Tag = source.Tag;");
        let decoy = lowered_module(
            "module decoy; \
             pub newtype Tag : . { pub constructor make; pub projector open; };",
        );
        let consumer = lowered_module(
            "module consumer; import relay as source; \
             fn main() -> source.Tag { source.Tag.make(()) }",
        );
        let package = Package::build(
            Path::new(""),
            vec![
                (PathBuf::from("origin.kio"), origin),
                (PathBuf::from("relay.kio"), relay),
                (PathBuf::from("decoy.kio"), decoy),
                (PathBuf::from("consumer.kio"), consumer),
            ],
            None,
        )
        .expect("package builds");
        package.resolve_imports().expect("uses resolve");
        package
            .check_in_body_resolution()
            .expect("body names resolve");
        let elabs = check_package_collect_elaborations(&package).expect("typecheck succeeds");
        let binders = elabs
            .position_index()
            .binders_iter()
            .filter(|((module, _), _)| module == "consumer")
            .map(|(_, binder)| binder)
            .collect::<Vec<_>>();

        assert!(binders.iter().any(|binder| matches!(
            binder,
            ResolvedBinder::TypeAlias { module_path, name }
                if module_path == "relay" && name == "Tag"
        )));
        assert!(binders.iter().any(|binder| matches!(
            binder,
            ResolvedBinder::NewtypeMember { module_path, newtype, member }
                if module_path == "origin" && newtype == "Tag" && member == "make"
        )));
        assert!(!binders.iter().any(|binder| matches!(
            binder,
            ResolvedBinder::NewtypeMember { module_path, .. } if module_path == "decoy"
        )));
    }

    /// Type-annotation references on `fn` parameters and return
    /// types are not indexed — the parser threads the
    /// annotation through as a `Type::Path`, but the typer's
    /// own walk doesn't visit it as an expression, so the
    /// position index records expression positions only.
    /// This test pins that scope: at least one expression-position
    /// `Local` binder for the body reference is recorded.
    #[test]
    fn position_index_records_only_value_positions() {
        let src = "module x; fn f(x: .) -> . { x }";
        let elabs = collect_elabs(src);
        let idx = elabs.position_index();
        // The body's `x` reference is the value-position
        // occurrence; its binder is a `Local` for `x`.
        let found = idx
            .binders_iter()
            .any(|(_, b)| matches!(b, ResolvedBinder::Local { name, .. } if name == "x"));
        assert!(found, "expected a Local binder for the `x` body reference");
        // At least one type entry — the body's `x` reference.
        assert!(
            idx.type_count() >= 1,
            "expected at least one type entry in v1"
        );
    }

    /// The merge contract: two non-overlapping shards merge into a
    /// single index with the sum of their entries. Mirrors the
    /// per-fn-body parallel-merge `parallelism/01` will rely on.
    #[test]
    fn position_index_merge_combines_disjoint_shards() {
        let mut a = PositionIndex::new();
        let mut b = PositionIndex::new();
        let span1 = Span::new(0, 5);
        let span2 = Span::new(10, 15);
        let unit_ty = Type::Unit {
            meta: Meta::new(span1),
        };
        a.record_type("m", span1, unit_ty.clone());
        b.record_type("m", span2, unit_ty);
        a.merge(b);
        assert_eq!(
            a.type_count(),
            2,
            "merge should combine disjoint shards into one map"
        );
        assert!(a.type_at("m", span1).is_some());
        assert!(a.type_at("m", span2).is_some());
    }

    #[test]
    fn position_index_preserves_identity_provenance_through_merge() {
        let mut a = PositionIndex::new();
        let mut b = PositionIndex::new();
        let span = Span::new(0, 5);
        let ty = Type::synth_path(vec!["owner".to_owned(), "T".to_owned()], Vec::new(), span);
        b.record_type_with_identity(
            "m",
            span,
            InternedType::fresh_canonical(ty),
            HashSet::from(["T".to_owned()]),
        );
        a.merge(b);
        assert!(a.type_identity_is_canonical("m", span));
        assert_eq!(
            a.type_binders_at("m", span),
            Some(HashSet::from(["T".to_owned()]))
        );
    }

    #[test]
    fn position_index_direct_overwrite_clears_identity_provenance() {
        let mut index = PositionIndex::new();
        let span = Span::new(0, 5);
        let canonical =
            Type::synth_path(vec!["owner".to_owned(), "T".to_owned()], Vec::new(), span);
        index.record_type_with_identity(
            "m",
            span,
            InternedType::fresh_canonical(canonical),
            HashSet::from(["A".to_owned()]),
        );

        index.record_type(
            "m",
            span,
            Type::synth_path(vec!["alias".to_owned(), "T".to_owned()], Vec::new(), span),
        );

        assert!(!index.type_identity_is_canonical("m", span));
        assert_eq!(index.type_binders_at("m", span), None);
    }

    #[test]
    fn position_index_merge_overwrite_preserves_later_identity_provenance() {
        let span = Span::new(0, 5);
        let canonical = || {
            InternedType::fresh_canonical(Type::synth_path(
                vec!["owner".to_owned(), "T".to_owned()],
                Vec::new(),
                span,
            ))
        };
        let source =
            || Type::synth_path(vec!["alias".to_owned(), "T".to_owned()], Vec::new(), span);

        let mut canonical_then_source = PositionIndex::new();
        canonical_then_source.record_type_with_identity(
            "m",
            span,
            canonical(),
            HashSet::from(["A".to_owned()]),
        );
        let mut source_shard = PositionIndex::new();
        source_shard.record_type("m", span, source());
        canonical_then_source.merge(source_shard);
        assert!(!canonical_then_source.type_identity_is_canonical("m", span));
        assert_eq!(canonical_then_source.type_binders_at("m", span), None);

        let mut source_then_canonical = PositionIndex::new();
        source_then_canonical.record_type("m", span, source());
        let mut canonical_shard = PositionIndex::new();
        canonical_shard.record_type_with_identity(
            "m",
            span,
            canonical(),
            HashSet::from(["A".to_owned()]),
        );
        source_then_canonical.merge(canonical_shard);
        assert!(source_then_canonical.type_identity_is_canonical("m", span));
        assert_eq!(
            source_then_canonical.type_binders_at("m", span),
            Some(HashSet::from(["A".to_owned()]))
        );
    }

    /// Generated / cloned bodies can reuse source spans. Merging two
    /// shards with the same key follows the old sequential path's
    /// `HashMap::insert` behavior: the later shard wins
    /// deterministically.
    #[test]
    fn position_index_merge_overlapping_shards_uses_later_entry() {
        let mut a = PositionIndex::new();
        let mut b = PositionIndex::new();
        let span = Span::new(0, 5);
        let first_ty = Type::Unit {
            meta: Meta::new(span),
        };
        let second_ty = Type::Bottom {
            meta: Meta::new(span),
        };
        a.record_type("m", span, first_ty);
        b.record_type("m", span, second_ty);
        a.merge(b);
        assert!(matches!(a.type_at("m", span), Some(Type::Bottom { .. })));
    }

    /// `PositionIndex` is `Send` — the parallel-merge contract in
    /// `parallelism/01` ships per-fn-body shards across thread
    /// boundaries, so the index must satisfy the `Send` bound. A
    /// compile-time check via a generic `fn`: if `PositionIndex`
    /// stops being `Send`, this test fails to compile.
    #[test]
    fn position_index_is_send() {
        fn assert_send<T: Send>() {}
        assert_send::<PositionIndex>();
    }

    // ---- Immediate-lambda direct-callee completion --------------------

    #[test]
    fn immediate_lambda_same_node_fills_absent_and_whole_placeholder() {
        ok("module x; \
            fn absent() -> . { .(value) { value }(()) } \
            fn placeholder() -> . { .(value: _) { value }(()) }");
    }

    #[test]
    fn immediate_lambda_does_not_use_body_or_later_application() {
        let bound = err("module x; \
            fn run() -> . { let f = .(value) { value }; f(()) }");
        assert!(
            bound.contains("cannot synthesize the type of `fn` parameter `value`")
                || bound.contains("cannot infer the type of `fn` parameter `value`"),
            "got: {bound}"
        );

        let later = err("module x; \
            fn run() -> . { .(first)(second) { second }(())(()) }");
        assert!(
            later.contains("cannot infer the type of `fn` parameter `second`"),
            "got: {later}"
        );
    }

    #[test]
    fn immediate_lambda_accepts_contextual_nested_placeholder_and_rejects_concrete_mismatch() {
        ok("module x; fn run() -> . { .(pair: (. & _)) { () }(((), ())) }");
        let concrete = err("module x; fn run() -> . { .(pair: (. & .)) { () }(()) }");
        assert!(
            concrete.contains("type mismatch: expected `(. & .)`, found `.`"),
            "got: {concrete}"
        );
    }

    #[test]
    fn immediate_lambda_return_slot_modes() {
        ok("module x; \
            fn absent() -> . { .(value: .) { value }(()) } \
            fn placeholder() -> . { .(value: .) -> _ { value }(()) } \
            fn concrete() -> . { .(value: .) -> . { value }(()) }");

        let mismatch = err("module x; \
            newtype R : . { pub constructor mk_r; pub projector un_r; }; \
            fn run() -> R { .(value: .) -> R { value }(()) }");
        assert!(
            mismatch.contains("type mismatch: expected `R`, found `.`"),
            "got: {mismatch}"
        );
    }

