    #[test]
    fn immediate_lambda_layer_binder_scope_solves_repeated_names_independently() {
        let package = lowered_package(&[(
            "x.kio",
            "module x; \
             newtype N : . { pub constructor mk_n; pub projector un_n; }; \
             fn run() -> N { \
               .[T](first: T)[T](second: T) { second }(_, (), N, N.mk_n(())) \
             }",
        )]);
        let prime = check_package(&package).expect("the repeated binders solve independently");
        let run = prime
            .module("x")
            .expect("x module")
            .module
            .items
            .iter()
            .find_map(|item| match item {
                Item::FnDef(def) if def.name == "run" => Some(def),
                _ => None,
            })
            .expect("run function");
        let crate::ast::Expr::Call {
            callee,
            args: outer_args,
            ..
        } = &run.body
        else {
            panic!("the second value layer must remain an outer Prime call");
        };
        let [
            crate::ast::CallArg::Type(outer_type),
            crate::ast::CallArg::Value(_),
        ] = outer_args.as_slice()
        else {
            panic!("the second layer must carry one type and one value argument");
        };
        let crate::ast::Type::Path {
            segments: outer_segments,
            ..
        } = outer_type
        else {
            panic!("the second layer's explicit type argument must remain nominal");
        };
        assert_eq!(
            outer_segments
                .iter()
                .map(|segment| segment.name.as_str())
                .collect::<Vec<_>>(),
            ["N"]
        );

        let crate::ast::Expr::Call {
            args: inner_args, ..
        } = callee.as_ref()
        else {
            panic!("the first value layer must remain an inner Prime call");
        };
        let [
            crate::ast::CallArg::Type(crate::ast::Type::Unit { .. }),
            crate::ast::CallArg::Value(_),
        ] = inner_args.as_slice()
        else {
            panic!("the first layer's inferred type argument must remain unit");
        };
    }

