    // ---- check-mode Let / Seq threading -------------------------------
    //
    // `default_check_value_against`'s Let/Seq arms thread the expected
    // type from the surrounding context through the body. Without
    // threading, a body call's type-arg inference would lose the
    // expected return — the polymorphic call's binders reachable only
    // through the return would surface as "cannot infer".

    #[test]
    fn check_mode_let_threads_expected_into_body() {
        // `caller` returns `Box(.)`. The body `let _ = (); pure(())`
        // (after parse) sets up: synth `()`, push `_`, check the
        // body against `Box(.)`. The body is `pure(())` — a
        // polymorphic call whose `[A]` is only solvable from the
        // expected return `Box(.)` (the value arg `()` does also
        // pin it, here, but the test still exercises the let-check-
        // mode arm).
        ok("module x; \
            newtype Box[A] : A { pub constructor mk_box; pub projector un_box; }; \
            fn pure[A](x: A) -> Box(A) { Box.mk_box(A, x) } \
            fn caller() -> Box(.) { let _ = (); pure(()) }");
    }

    #[test]
    fn check_mode_let_binds_value_into_body_scope() {
        // `let x = SomeValue; body_using_x` — body sees `x : type-of-
        // SomeValue` even when checked against an expected type. Here
        // `let x = (); x` against expected `.` succeeds because
        // `x : .`.
        ok("module x; \
            fn caller() -> . { let x = (); x }");
    }

    #[test]
    fn check_mode_let_body_mismatch_against_expected_errors() {
        // `let x = (); x` checked against expected `Foo` fails because
        // `x : .` does not equal `Foo`. The check-mode let arm
        // surfaces the body's mismatch against `expected`.
        let msg = err("module x; \
                       newtype Foo : . { pub constructor mk_foo; pub projector un_foo; }; \
                       fn caller() -> Foo { let x = (); x }");
        assert!(
            msg.contains("type") || msg.contains("mismatch"),
            "got: {msg}"
        );
    }

    #[test]
    fn check_mode_seq_threads_expected_into_body() {
        // `(); body` — Seq form, the leading value-statement is
        // discarded (must type to `.`), the body continues against
        // the surrounding expected type. Same threading promise as
        // let; just no binder.
        ok("module x; \
            newtype Box[A] : A { pub constructor mk_box; pub projector un_box; }; \
            fn pure[A](x: A) -> Box(A) { Box.mk_box(A, x) } \
            fn caller() -> Box(.) { (); pure(()) }");
    }

    #[test]
    fn check_mode_seq_rejects_non_unit_statement() {
        // `e;` where `e : Foo` (not `.`) is a type error per spec
        // — `let _ = e;` to discard a non-unit value deliberately.
        // The check-mode Seq arm enforces the same rule as the synth
        // arm.
        let msg = err("module x; \
                       newtype Foo : . { pub constructor mk_foo; pub projector un_foo; }; \
                       fn make_foo() -> Foo { Foo.mk_foo(()) } \
                       fn caller() -> . { make_foo(); () }");
        // Diagnostic mentions either the unit expectation or "discard".
        assert!(msg.contains(".") || msg.contains("discard"), "got: {msg}");
    }

    // ---- check_fn_against body push -----------------------------------
    //
    // `check_fn_against`'s body check switched from synth-and-equiv
    // to `check_value_against`. The push threads the expected return
    // type into the body, which feeds nested polymorphic calls' type-
    // arg inference. Without the push, a call in the body whose
    // binders are only reachable through the call's return type would
    // surface as "cannot infer".

    #[test]
    fn fn_body_push_pins_binder_from_expected_return() {
        // `make_box()` has expected return `Box(.)`. The body is
        // `pure(())` — `pure: [A] A -> Box(A)`. The value arg `()`
        // pins `[A] = .` here too, but the check-mode body push
        // also feeds the expected `Box(.)` through to the call's
        // inference engine, exercising the threaded path.
        ok("module x; \
            newtype Box[A] : A { pub constructor mk_box; pub projector un_box; }; \
            fn pure[A](x: A) -> Box(A) { Box.mk_box(A, x) } \
            fn make_box() -> Box(.) { pure(()) }");
    }

    #[test]
    fn fn_body_push_pins_return_only_binder() {
        // `make_pair_left[B]` returns `B & .`. The body is a
        // `__pair__(B, ., ?, ())` call — the `?` slot is `[B]`'s
        // value, supplied as a fn-param. The fn's `x: b` value-arg
        // pins `[B]` via the explicit annotation, but the body's
        // inner call's full picture still needs the expected return
        // `B & .` to flow through.
        ok("module x; \
            import __intrinsics__; \
            fn make_pair_left[B](x: B) -> (B & .) { \
              __pair__(B, ., x, ()) \
            }");
    }

    #[test]
    fn fn_body_push_through_let_to_call() {
        // The body is `let _ = (); pure(())` against expected `Box(.)`.
        // Two layers of check-mode threading: the fn-body push lands
        // the expected at `let`, which threads through to `pure(())`.
        // Without either layer, the inner call's type-arg inference
        // loses `Box(.)` and surfaces "cannot infer".
        ok("module x; \
            newtype Box[A] : A { pub constructor mk_box; pub projector un_box; }; \
            fn pure[A](x: A) -> Box(A) { Box.mk_box(A, x) } \
            fn caller() -> Box(.) { let _ = (); pure(()) }");
    }

    // ---- Mutation-killing regression tests -----------------------------

    #[test]
    fn fn_value_arg_one_sided_function_mismatch_rejected() {
        // A function-typed *value* passed where a function type with the
        // same domain but a *different* codomain is expected. There is no
        // lambda to decompose, so the check routes through whole-`Function`
        // equivalence — which must agree on BOTH the param and the ret
        // (a conjunction, not a disjunction).
        let msg = err("module x; \
            newtype Foo : . { pub constructor mk_foo; pub projector foo; }; \
            newtype Bar : . { pub constructor mk_bar; pub projector bar; }; \
            fn apply(k: (. -> Foo)) -> . { () } \
            fn run(h: (. -> Bar)) -> . { apply(h) }");
        assert!(msg.contains("type mismatch"), "got: {msg}");
    }

    #[test]
    fn rec_under_covariant_newtype_arg_accepted() {
        // `Box[A] : A` makes `A` covariant, so the self-reference in
        // `Rec : Box(Rec)` lands at variance `+` and passes strict
        // positivity. An all-invariant (empty / `Default`) variance env
        // would compose the slot to `*` and wrongly reject.
        ok("module x; \
            newtype Box[A] : A { pub constructor mk_box; pub projector un_box; }; \
            rec newtype Rec : Box(Rec) { pub constructor mk_rec; pub projector un_rec; };");
    }

    #[test]
    fn phantom_param_negative_occurrence_accepted() {
        // `Phantom[A] : Other` never uses `A`, so `A` is `Unused`. The
        // self-reference `R : Phantom(R -> .)` therefore lands at `Unused`
        // (the phantom slot discards it) and passes. A polarity flip in
        // the variance walk would surface the negative `R -> .` occurrence
        // and reject.
        ok("module x; \
            newtype Other : . { pub constructor mk_o; pub projector un_o; }; \
            newtype Phantom[A] : Other { pub constructor mk_ph; pub projector un_ph; }; \
            rec newtype R : Phantom(R -> .) { pub constructor mk_r; pub projector un_r; };");
    }

    #[test]
    fn int_literal_rejected_against_str_role_param() {
        // `42` flowing into a `role(str)` host-type param: the literal's
        // int shape does not admit the `str` role of the expected host
        // type, so the tier-2 admission check must reject it.
        let msg = err("module main; \
            host type S role(str); \
            host fn f(x: S) -> .; \
            fn run() -> . { f(42) }");
        assert!(
            msg.contains("cannot be typed")
                || msg.contains("does not admit")
                || msg.contains("no type"),
            "got: {msg}"
        );
    }

    #[test]
    fn int_literal_admitted_against_rehost_alias_role() {
        // A `type` alias of a role-bearing host type inherits its role;
        // a bare `42` into a param of that alias type is admitted through
        // the single-segment (bare-name) admission arm.
        ok("module main; \
            host type I32 role(i32); \
            type Myint = I32; \
            fn f(x: Myint) -> . { () } \
            fn run() -> . { f(42) }");
    }

