    fn assert_terminal_public_layer_work(
        reserved_slots: usize,
        child_opens: usize,
        expected_children: usize,
        synthesized_children: usize,
        marker_finishes: usize,
        open_body_observations: usize,
    ) {
        let work = crate::pass::typecheck_core::apply::terminal_public_layer_work();
        assert_eq!(work.reserved_slots, reserved_slots, "terminal slot count");
        assert_eq!(
            work.parent_goal_growth, reserved_slots,
            "every omitted terminal binder must add one current-parent goal"
        );
        assert_eq!(work.child_opens, child_opens, "terminal child count");
        assert_eq!(
            work.child_goal_count, 0,
            "terminal children must own no inferred binder goals"
        );
        assert_eq!(
            work.expected_children, expected_children,
            "expected terminal child count"
        );
        assert_eq!(
            work.synthesized_children, synthesized_children,
            "synthesized terminal child count"
        );
        assert_eq!(
            work.marker_finishes, marker_finishes,
            "terminal marker completion count"
        );
        assert_eq!(
            work.open_body_observations, open_body_observations,
            "mixed open terminal header count"
        );
        if child_opens == 0 {
            assert!(work.last_parent.is_none() && work.last_child.is_none());
        } else {
            assert_ne!(
                work.last_parent, work.last_child,
                "the terminal child must be distinct from its action parent"
            );
        }
    }

    fn assert_final_elaborator_successor_work(
        terminal_continues: usize,
        migrated_descents: usize,
        earlier_terminal_yields: usize,
        earlier_nonterminal_yields: usize,
    ) {
        let work = crate::pass::typecheck_core::apply::final_elaborator_successor_work();
        assert_eq!(
            work.terminal_continues, terminal_continues,
            "Final successor work: {work:?}"
        );
        assert_eq!(
            work.migrated_descents, migrated_descents,
            "Final successor work: {work:?}"
        );
        assert_eq!(
            work.earlier_terminal_yields, earlier_terminal_yields,
            "Final successor work: {work:?}"
        );
        assert_eq!(
            work.earlier_nonterminal_yields, earlier_nonterminal_yields,
            "Final successor work: {work:?}"
        );
    }

