    fn source_span(source: &str, needle: &str) -> Span {
        let start = source.find(needle).expect("test expression is present");
        Span::new(
            u32::try_from(start).expect("test source fits in a span"),
            u32::try_from(start + needle.len()).expect("test source fits in a span"),
        )
    }

    fn retained_call_at(package: &Package, module_path: &str, span: Span) -> Expr {
        struct Finder {
            span: Span,
            found: Vec<Expr>,
        }

        impl crate::pass::visit_mut::TypecheckVisitMut<Lowered> for Finder {
            fn visit_expr(&mut self, expr: &mut Expr) {
                let is_call = matches!(expr, Expr::UserElaborator { .. })
                    || matches!(expr, Expr::Ufcs { bang: Some(_), .. });
                if is_call && expr.span() == self.span {
                    self.found.push(expr.clone());
                }
                crate::pass::visit_mut::walk_expr(self, expr);
            }
        }

        let mut module = package
            .module(module_path)
            .expect("test module exists")
            .module
            .clone();
        let mut finder = Finder {
            span,
            found: Vec::new(),
        };
        crate::pass::visit_mut::TypecheckVisitMut::visit_module(&mut finder, &mut module);
        assert_eq!(
            finder.found.len(),
            1,
            "expected one retained call at {span:?}, found {:#?}",
            finder.found
        );
        finder.found.pop().expect("one retained call")
    }

    fn retained_field_access_at(package: &Package, module_path: &str, span: Span) -> Expr {
        struct Finder {
            span: Span,
            found: Vec<Expr>,
        }

        impl crate::pass::visit_mut::TypecheckVisitMut<Lowered> for Finder {
            fn visit_expr(&mut self, expr: &mut Expr) {
                if matches!(
                    expr,
                    Expr::Elaborator {
                        call: crate::ast::ElaboratorCall::FieldAccess { .. },
                        ..
                    }
                ) && expr.span() == self.span
                {
                    self.found.push(expr.clone());
                }
                crate::pass::visit_mut::walk_expr(self, expr);
            }
        }

        let mut module = package
            .module(module_path)
            .expect("test module exists")
            .module
            .clone();
        let mut finder = Finder {
            span,
            found: Vec::new(),
        };
        crate::pass::visit_mut::TypecheckVisitMut::visit_module(&mut finder, &mut module);
        assert_eq!(
            finder.found.len(),
            1,
            "expected one retained field access at {span:?}, found {:#?}",
            finder.found
        );
        finder.found.pop().expect("one retained field access")
    }

    fn check_retained_success(
        package: &Package,
    ) -> (
        CheckedLoweredPackage,
        std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
    ) {
        let normalized = crate::pass::alpha_normalize::normalize_package(package);
        let scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(
                    crate::pass::typecheck_core::TypeInterner::<Lowered>::default(),
                ),
            );
        let checked = check_normalized_package_with_scope_and_execution(
            normalized,
            scope.clone(),
            crate::pass::typecheck_core::TypecheckExecution::Sequential,
        )
        .expect("retained action closes");
        (checked, scope)
    }

    fn check_retained_error_with_scope(
        package: &Package,
    ) -> (
        Error,
        std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
    ) {
        let normalized = crate::pass::alpha_normalize::normalize_package(package);
        let scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(
                    crate::pass::typecheck_core::TypeInterner::<Lowered>::default(),
                ),
            );
        match check_normalized_package_with_scope_and_execution(
            normalized,
            scope.clone(),
            crate::pass::typecheck_core::TypecheckExecution::Sequential,
        ) {
            Ok(_) => panic!("the retained package unexpectedly typechecked"),
            Err(errors) => {
                let error = errors
                    .into_iter()
                    .next()
                    .expect("the retained package returned an empty error set")
                    .error;
                (error, scope)
            }
        }
    }

    fn check_retained_error(package: &Package) -> Error {
        check_retained_error_with_scope(package).0
    }

    fn check_retained_function_at_final(
        package: &Package,
        module_path: &str,
        function_name: &str,
    ) -> (
        Elaborations,
        std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
        Result<(), Error>,
    ) {
        check_retained_function_at_terminal_mode(package, module_path, function_name, false)
    }

    fn check_retained_function_from_final_preflight(
        package: &Package,
        module_path: &str,
        function_name: &str,
    ) -> (
        Elaborations,
        std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
        Result<(), Error>,
    ) {
        check_retained_function_at_terminal_mode(package, module_path, function_name, true)
    }

    fn check_retained_function_at_terminal_mode(
        package: &Package,
        module_path: &str,
        function_name: &str,
        preflight: bool,
    ) -> (
        Elaborations,
        std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
        Result<(), Error>,
    ) {
        let normalized = crate::pass::alpha_normalize::normalize_package(package);
        let scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(
                    crate::pass::typecheck_core::TypeInterner::<Lowered>::default(),
                ),
            );
        let package = normalized.package();
        let module = &package
            .module(module_path)
            .expect("test module exists")
            .module;
        let (item_index, function) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(function) if function.name == function_name => Some((index, function)),
                _ => None,
            })
            .unwrap_or_else(|| panic!("test module has no `{function_name}` function"));
        let env = crate::pass::typecheck_core::ModuleEnv::build_with_typecheck_scope(
            module,
            None,
            None,
            Some(package),
            scope.clone(),
        )
        .expect("Final-mode test module environment");
        let mut elaborations = Elaborations::new();
        let result = {
            let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
            for parameter in function.sig.value_params() {
                tcx.push_value(
                    parameter.name.clone(),
                    parameter
                        .ty
                        .clone()
                        .expect("Final-mode test parameter annotation"),
                );
            }
            let expected = InternedType::fresh(function.ret.clone());
            if preflight {
                crate::pass::typecheck_core::apply::run_general_ordinary_value_from_final_preflight_for_test(
                    &function.body,
                    Some(&expected),
                    &mut tcx,
                )
                .map(|_| ())
            } else {
                crate::pass::typecheck_core::apply::run_general_ordinary_value_at_final_for_test(
                    &function.body,
                    Some(&expected),
                    &mut tcx,
                )
                .map(|_| ())
            }
        };
        let result = result.and_then(|()| {
            elaborations.discharge_deferred_with_execution(
                &env,
                crate::pass::typecheck_core::TypecheckExecution::Sequential,
            )
        });
        (elaborations, scope, result)
    }

    fn check_retained_module_error(
        package: &Package,
        module_path: &str,
    ) -> (
        Elaborations,
        std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
        Vec<Error>,
    ) {
        let normalized = crate::pass::alpha_normalize::normalize_package(package);
        let scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(
                    crate::pass::typecheck_core::TypeInterner::<Lowered>::default(),
                ),
            );
        let package = normalized.package();
        let module = &package
            .module(module_path)
            .expect("test module exists")
            .module;
        let mut elaborations = Elaborations::new();
        let errors =
            crate::pass::typecheck_core::check_module_in_package_with_typecheck_scope_collect_errors(
                module,
                package.package_file().map(|entry| &entry.package_file),
                package
                    .package_file()
                    .map(|entry| entry.package_name.as_str()),
                Some(package),
                &mut elaborations,
                scope.clone(),
            )
            .expect_err("retained module is rejected");
        (elaborations, scope, errors)
    }

    fn assert_retained_call_unpublished(
        elaborations: &Elaborations,
        module_path: &str,
        original: &Expr,
    ) {
        let node_id = elaboration_node_id(original).expect("retained call has a node id");
        assert!(
            elaborations
                .elaboration_for(module_path, original)
                .is_none(),
            "failed retained call published its replacement"
        );
        assert!(
            elaborations
                .position_index()
                .type_at(module_path, original.span())
                .is_none(),
            "failed retained call published its position type"
        );
        assert!(
            elaborations.deferred.iter().all(|deferred| match deferred {
                DeferredElaboration::UserElaborator(obligation) => obligation.node_id != node_id,
            }),
            "failed retained call escaped in the deferred queue"
        );
    }

    fn assert_retained_call_published(
        elaborations: &Elaborations,
        module_path: &str,
        original: &Expr,
    ) {
        assert!(
            elaborations
                .elaboration_for(module_path, original)
                .is_some(),
            "successful retained call did not publish its replacement"
        );
        assert!(
            elaborations
                .position_index()
                .type_at(module_path, original.span())
                .is_some(),
            "successful retained call did not publish its position type"
        );
    }

    fn assert_marked_polymorphic_return_error(errors: &[Error], span: Span) {
        assert_eq!(
            errors.len(),
            1,
            "the missing result anchor must be the only diagnostic: {errors:#?}"
        );
        let Error::Type(diagnostic) = &errors[0] else {
            panic!("the missing result anchor must be a type error: {errors:#?}")
        };
        assert_eq!(diagnostic.span, span);
        assert_eq!(
            diagnostic.message,
            "this polymorphic `fn` needs an independently known result type before its body is checked"
        );
        assert_eq!(
            diagnostic.help(),
            Some("write a concrete return annotation or provide an enclosing expected result")
        );
    }

    #[test]
    fn retained_fixed_result_elaborator_closes_and_evaluates_once() {
        check_package_sources(&["module main; \
            host type I32; \
            host fn witness() -> I32; \
            fn identity[T](value: T) -> T { value } \
            fn consume[T](_f: T -> T, _value: T) -> . { () } \
            fn run() -> . { consume(.(value) { identity(value) }, witness()) }"])
        .expect("ordinary identity call closes in the surrounding retained frontier");

        let main = "module main; \
            import elab(same); \
            host type I32; \
            host fn witness() -> I32; \
            fn consume[T](_f: T -> T, _value: T) -> . { () } \
            fn run() -> . { consume(.(value) { same!(value) }, witness()) }";
        let package = lowered_package(&[
            ("elab.kio", RETAINED_ACTION_ELABORATORS),
            ("main.kio", main),
        ]);
        let original = retained_call_at(&package, "main", source_span(main, "same!(value)"));
        let (checked, scope) = check_retained_success(&package);

        assert!(
            checked
                .elaborations()
                .elaboration_for("main", &original)
                .is_some(),
            "closed fixed-result action publishes its replacement"
        );
        assert_eq!(scope.memo().user_elaborator_template_executions(), 1);
        validate_substituted_package(checked.substituted())
            .expect("closed fixed-result action survives standalone Prime validation");
    }

    #[test]
    fn retained_multi_goal_type_producing_elaborator_closes_and_evaluates_once() {
        let main = "module main; \
            import elab(infer_pair); \
            host type I32 role(i32); \
            host type String role(str); \
            fn run() -> I32 & String { \
              let pair = infer_pair!((0, \"closed\")); \
              pair \
            }";
        let package = lowered_package(&[
            ("elab.kio", RETAINED_ACTION_ELABORATORS),
            ("main.kio", main),
        ]);
        let original = retained_call_at(
            &package,
            "main",
            source_span(main, "infer_pair!((0, \"closed\"))"),
        );
        let (checked, scope) = check_retained_success(&package);

        assert!(
            checked
                .elaborations()
                .elaboration_for("main", &original)
                .is_some(),
            "closed type-producing action publishes its replacement"
        );
        let Some(Type::Product { left, right, .. }) = checked
            .elaborations()
            .position_index()
            .type_at("main", original.span())
        else {
            panic!("the type-producing call must publish its concrete product result")
        };
        let path_ends_in = |ty: &Type, expected: &str| {
            matches!(
                ty,
                Type::Path { segments, .. }
                    if segments.last().is_some_and(|segment| segment.as_str() == expected)
            )
        };
        assert!(
            path_ends_in(left, "I32")
                && path_ends_in(right, "String")
                && !crate::pass::typecheck_core::type_contains_goal(left)
                && !crate::pass::typecheck_core::type_contains_goal(right),
            "the type-producing call published a residual result: {left:?} & {right:?}"
        );
        assert_eq!(scope.memo().user_elaborator_template_executions(), 1);
        validate_substituted_package(checked.substituted())
            .expect("closed multi-goal action survives standalone Prime validation");
    }

    #[test]
    fn retained_initial_layer_optional_result_evaluates_once_and_closes_its_goal() {
        let elaborator = "module elab; \
            import __comptime__; \
            type Optional_type = __Type__ | .; \
            pure fn infer_unit_impl(ct: __Comptime__, _a: Optional_type) -> __Checked_term__ { \
              __term_unit__(ct) \
            } \
            pub elab infer_unit : [A] . -> A { impl infer_unit_impl; };";
        let main = "module main; \
            import elab(infer_unit); \
            fn run() -> . { let _inferred = infer_unit!(); () }";
        let package = lowered_package(&[("elab.kio", elaborator), ("main.kio", main)]);
        let original = retained_call_at(&package, "main", source_span(main, "infer_unit!()"));
        let (checked, scope) = check_retained_success(&package);

        assert!(
            matches!(
                checked
                    .elaborations()
                    .position_index()
                    .type_at("main", original.span()),
                Some(Type::Unit { .. })
            ),
            "the evaluator-returned Unit type must close the initial A occurrence"
        );
        assert_eq!(scope.memo().user_elaborator_template_executions(), 1);
        validate_substituted_package(checked.substituted())
            .expect("the initial-owner type-producing action survives Prime validation");
    }

    #[test]
    fn optional_absence_requires_the_exact_result_binder() {
        let elaborator = "module elab; \
            import __comptime__; \
            type Optional_type = __Type__ | .; \
            pure fn infer_unit_impl( \
                ct: __Comptime__, \
                _phantom: Optional_type, \
                _result: Optional_type \
              ) -> __Checked_term__ { __term_unit__(ct) } \
            pub elab infer_unit : [Phantom][Result] . -> Result { impl infer_unit_impl; };";
        let main = "module main; \
            import elab(infer_unit); \
            fn run() -> . { let _inferred = infer_unit!(_, _); () }";
        let package = lowered_package(&[("elab.kio", elaborator), ("main.kio", main)]);
        let original = retained_call_at(&package, "main", source_span(main, "infer_unit!(_, _)"));
        let (elaborations, scope, errors) = check_retained_module_error(&package, "main");

        assert!(
            errors.iter().any(|error| {
                let message = &error.diagnostic().message;
                message.contains("cannot infer type argument") && message.contains("Phantom")
            }),
            "the phantom binder must be rejected before result inference: {errors:#?}"
        );
        assert_retained_call_unpublished(&elaborations, "main", &original);
        assert_eq!(
            scope.memo().user_elaborator_template_executions(),
            0,
            "a phantom Optional slot must block evaluator execution"
        );
    }

    #[test]
