    #[test]
    fn fills_written_callback_export_failure_preserves_later_publication() {
        let bad = "observe!(identity(dispatch(.(state: State) -> State | Done { () }, seed)))";
        let good = "observe!(identity(dispatch(.(state: State) -> State | Done { advance(state) }, seed)))";
        let main = format!(
            "module main; import elab(observe); host type State; host type Done; \
             host fn dispatch[S][R](step: S -> S | R, seed: S) -> R; \
             host fn advance(state: State) -> State | Done; \
             host fn identity[A](value: A) -> A; \
             fn bad(seed: State) -> . {{ {bad} }}; \
             fn good(seed: State) -> . {{ {good} }}"
        );
        let package =
            lowered_package(&[("elab.kio", WRITTEN_CALLBACK_OBSERVER), ("main.kio", &main)]);
        let bad_call = retained_call_at(&package, "main", source_span(&main, bad));
        let good_call = retained_call_at(&package, "main", source_span(&main, good));
        let normalized = crate::pass::alpha_normalize::normalize_package(&package);
        let scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(
                    crate::pass::typecheck_core::TypeInterner::<Lowered>::default(),
                ),
            );
        let package = normalized.package();
        let module = &package.module("main").expect("main module").module;
        let env = crate::pass::typecheck_core::ModuleEnv::build_with_typecheck_scope(
            module,
            None,
            None,
            Some(package),
            scope,
        )
        .expect("shared check environment");
        let functions = module
            .items
            .iter()
            .enumerate()
            .filter_map(|(index, item)| match item {
                Item::FnDef(function) => Some((index, function)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(functions.len(), 2);
        let mut elaborations = Elaborations::new();
        crate::pass::typecheck_core::apply::reset_public_header_work();
        let error = crate::pass::typecheck_core::check_fn_def(
            functions[0].1,
            functions[0].0,
            &env,
            &mut elaborations,
        )
        .expect_err("the nested source has a bad callback body");
        assert!(error.diagnostic().message.contains("type mismatch"));
        assert!(crate::pass::typecheck_core::apply::public_header_work().pending_exports > 0);
        assert_retained_call_unpublished(&elaborations, "main", &bad_call);
        assert_eq!(elaborations.type_resolution_count(), 0);
        assert_eq!(elaborations.call_plan_count(), 0);
        assert!(elaborations.fn_param_types.is_empty());
        assert!(elaborations.literal_resolutions.is_empty());
        crate::pass::typecheck_core::check_fn_def(
            functions[1].1,
            functions[1].0,
            &env,
            &mut elaborations,
        )
        .expect("later root completes without the failed nested equations");
        elaborations
            .discharge_deferred_with_execution(
                &env,
                crate::pass::typecheck_core::TypecheckExecution::Sequential,
            )
            .expect("later publication completes");
        assert_retained_call_unpublished(&elaborations, "main", &bad_call);
        assert_retained_call_published(&elaborations, "main", &good_call);
    }

