    #[test]
    fn deferred_nested_application_diagnostics_hide_internal_hole_names() {
        let msg = package_type_err(&["module x; \
            host type I32 role(i32); \
            fn choose[T](left: T, _right: T) -> T { left } \
            fn take[A][B](_b: B, _pair: B & A) -> . { () } \
            fn run[A](x: A) -> . { take(x, choose((1, 1), (2, 2))) }"]);
        assert!(msg.contains("type mismatch"), "got: {msg}");
        assert!(
            msg.contains('A'),
            "source binder must remain visible: {msg}"
        );
        assert!(
            !msg.contains("A_n2")
                && !msg.contains("__")
                && !msg.contains('\0')
                && !msg.contains("expected0"),
            "internal hole name leaked: {msg}"
        );
    }

    #[test]
    fn type_has_free_elaborator_param_detects_one_sided_occurrence() {
        // A free elaborator param on *either* side of a function, product,
        // or sum must be detected (a disjunction). Demanding it on both
        // sides would miss `A -> Int`, `Int -> A`, `A & Int`, `Int | A`.
        fn p(name: &str) -> Type {
            Type::synth_path(vec![name.to_owned()], Vec::new(), Span::new(0, 0))
        }
        fn func(param: Type, ret: Type) -> Type {
            Type::synth_function(vec![param], ret, Span::new(0, 0))
        }
        fn prod(left: Type, right: Type) -> Type {
            Type::Product {
                left: Box::new(left),
                right: Box::new(right),
                meta: Meta::new(Span::new(0, 0)),
            }
        }
        fn sum(left: Type, right: Type) -> Type {
            Type::Sum {
                left: Box::new(left),
                right: Box::new(right),
                meta: Meta::new(Span::new(0, 0)),
            }
        }
        let names: HashSet<String> = ["A".to_owned()].into_iter().collect();
        assert!(type_has_free_elaborator_param(
            &func(p("A"), p("Int")),
            &names
        ));
        assert!(type_has_free_elaborator_param(
            &func(p("Int"), p("A")),
            &names
        ));
        assert!(type_has_free_elaborator_param(
            &prod(p("A"), p("Int")),
            &names
        ));
        assert!(type_has_free_elaborator_param(
            &sum(p("Int"), p("A")),
            &names
        ));
        assert!(!type_has_free_elaborator_param(
            &func(p("Int"), p("Int")),
            &names
        ));
    }

    #[test]
    fn ordinary_and_marked_type_captures_use_the_type_namespace() {
        for name in ["Foo", "_Foo"] {
            let capture = crate::ast::UserElaboratorCapture {
                segments: vec![crate::ast::PathSegment::new(
                    name.to_owned(),
                    Span::new(0, 0),
                )],
                span: Span::new(0, 0),
            };
            assert_eq!(
                classify_user_elaborator_capture(&capture).unwrap(),
                UserElaboratorCaptureSpelling::Type,
                "{name}"
            );
        }
    }

    #[test]
    fn dotted_capture_ending_in_a_type_name_is_not_a_member() {
        // A dotted path ending in a type-shaped segment is neither a bare
        // type, a bare value, nor a member — it must be rejected, not waved
        // through as a member capture.
        for name in ["B", "_B"] {
            let capture = crate::ast::UserElaboratorCapture {
                segments: vec![
                    crate::ast::PathSegment::new("a".to_owned(), Span::new(0, 0)),
                    crate::ast::PathSegment::new(name.to_owned(), Span::new(0, 0)),
                ],
                span: Span::new(0, 0),
            };
            assert!(
                classify_user_elaborator_capture(&capture).is_err(),
                "{name}"
            );
        }
    }

