    #[test]
    fn top_level_alias_with_bare_infer_rejected() {
        // A `_` in a top-level binding annotation is rejected by
        // `check_well_formed_type` — the sole `_`-rejection point outside
        // fn-signatures and call type-arg lists.
        let msg = err("module x; type Bad = _;");
        assert!(
            msg.contains("not allowed here") || msg.contains("must be explicit"),
            "got: {msg}"
        );
    }

    #[test]
    fn elaborator_capture_owner_and_visibility_are_exact() {
        // A user elaborator's captured items must resolve to their
        // *declaring* module (for the generated import) and retain each
        // declaration's exact visibility (for the elaborator visibility
        // floor). Exercises the member / fn / type owner resolvers directly
        // across qualified, selective, and same-module spellings.
        use crate::pass::resolve::Package;
        use crate::pass::typecheck_core::ModuleEnv;
        use std::path::{Path, PathBuf};

        let dep = lowered_module(
            "module dep; \
             pub newtype T : . { constructor mk; pub projector un; }; \
             pub fn foo() -> . { () } \
             pub type Al = .;",
        );
        let main = lowered_module(
            "module main; \
             import dep as d; \
             import dep(T, foo, Al); \
             pub newtype U : . { constructor mku; pub projector unu; }; \
             pub type Unused = .;",
        );
        let package = Package::build(
            Path::new(""),
            vec![
                (PathBuf::from("dep.kio"), dep),
                (PathBuf::from("main.kio"), main),
            ],
            None,
        )
        .unwrap();
        let main_mod = &package.module("main").expect("main module").module;
        let env = ModuleEnv::build(main_mod, None, None, Some(&package)).expect("env");

        let cap = |segs: &[&str]| crate::ast::UserElaboratorCapture {
            segments: segs
                .iter()
                .map(|s| crate::ast::PathSegment::new((*s).to_owned(), Span::new(0, 0)))
                .collect(),
            span: Span::new(0, 0),
        };
        let edges = |resolved: &ResolvedCaptureTermPath| {
            resolved
                .visibility_edges
                .iter()
                .map(|edge| (edge.visibility.clone(), edge.target.clone()))
                .collect::<Vec<_>>()
        };

        // 3-segment qualified newtype member (`d.T.mk`): owner is the
        // declaring module `dep`; the visibility edges retain both the
        // public newtype and its private constructor as separately named
        // requirements.
        let mk = resolve_capture_member_owner(&cap(&["d", "T", "mk"]), &env).expect("d.T.mk");
        assert_eq!(mk.owner_module_path.as_deref(), Some("dep"));
        assert_eq!(
            edges(&mk),
            vec![
                (
                    crate::ast::Visibility::Public,
                    "captured newtype `d.T`".to_owned()
                ),
                (
                    crate::ast::Visibility::Private,
                    "captured member `d.T.mk`".to_owned()
                ),
            ]
        );
        // The public projector records both declarations as public.
        let un = resolve_capture_member_owner(&cap(&["d", "T", "un"]), &env).expect("d.T.un");
        assert_eq!(un.owner_module_path.as_deref(), Some("dep"));
        assert_eq!(
            edges(&un),
            vec![
                (
                    crate::ast::Visibility::Public,
                    "captured newtype `d.T`".to_owned()
                ),
                (
                    crate::ast::Visibility::Public,
                    "captured member `d.T.un`".to_owned()
                ),
            ]
        );
        // Unknown member is a clear error, not a silent resolution.
        assert!(resolve_capture_member_owner(&cap(&["d", "T", "nope"]), &env).is_err());

        // 2-segment selective-imported newtype member (`T.mk`): the owner
        // is still the declaring module `dep`, not the current module.
        let t_mk = resolve_capture_member_owner(&cap(&["T", "mk"]), &env).expect("T.mk");
        assert_eq!(t_mk.owner_module_path.as_deref(), Some("dep"));
        assert_eq!(
            edges(&t_mk),
            vec![
                (
                    crate::ast::Visibility::Public,
                    "captured newtype `T`".to_owned()
                ),
                (
                    crate::ast::Visibility::Private,
                    "captured member `T.mk`".to_owned()
                ),
            ]
        );

        // 2-segment same-module newtype member (`U.mku`): owner is the
        // current module; the private constructor remains a separate entry.
        let u_mku = resolve_capture_member_owner(&cap(&["U", "mku"]), &env).expect("U.mku");
        assert_eq!(u_mku.owner_module_path.as_deref(), Some("main"));
        assert_eq!(
            edges(&u_mku),
            vec![
                (
                    crate::ast::Visibility::Public,
                    "captured newtype `U`".to_owned()
                ),
                (
                    crate::ast::Visibility::Private,
                    "captured member `U.mku`".to_owned()
                ),
            ]
        );

        // 2-segment qualified fn (`d.foo`): owner is `dep`, public.
        let d_foo = resolve_capture_member_owner(&cap(&["d", "foo"]), &env).expect("d.foo");
        assert_eq!(d_foo.owner_module_path.as_deref(), Some("dep"));
        assert_eq!(
            edges(&d_foo),
            vec![(
                crate::ast::Visibility::Public,
                "captured member `d.foo`".to_owned()
            )]
        );

        // Single-name selective-imported fn (`foo`): owner is `dep`.
        let foo = resolve_capture_fn_owner(&cap(&["foo"]), &env).expect("foo");
        assert_eq!(foo.owner_module_path.as_deref(), Some("dep"));
        assert_eq!(
            edges(&foo),
            vec![(
                crate::ast::Visibility::Public,
                "captured function `foo`".to_owned()
            )]
        );

        // Single-name type owners: newtype `T` and alias `Al` both trace
        // to their declaring module `dep`.
        assert_eq!(
            resolve_type_name_owner("T", &env),
            Some(("dep".to_owned(), crate::ast::Visibility::Public))
        );
        assert_eq!(
            resolve_type_name_owner("Al", &env),
            Some(("dep".to_owned(), crate::ast::Visibility::Public))
        );
    }

    #[test]
    fn capture_type_owners_reuse_the_nominal_provider() {
        use crate::pass::resolve::Package;
        use crate::pass::typecheck_core::ModuleEnv;
        use std::path::{Path, PathBuf};

        const ALIASES: usize = 16;
        const NEWTYPES: usize = 16;
        const FILLERS: usize = 32;

        let mut provider = String::from("module provider;");
        let mut imported = Vec::with_capacity(ALIASES + NEWTYPES);
        for index in 0..ALIASES {
            let name = format!("Alias{index}");
            provider.push_str(&format!(" pub type {name} = .;"));
            imported.push(name);
        }
        for index in 0..NEWTYPES {
            let name = format!("Nominal{index}");
            provider.push_str(&format!(
                " pub newtype {name} : . {{ pub constructor make{index}; pub projector unmake{index}; }};"
            ));
            imported.push(name);
        }
        for index in 0..FILLERS {
            provider.push_str(&format!(" pub type Filler{index} = .;"));
        }
        let consumer = format!("module consumer; import provider({});", imported.join(", "));
        let package = Package::build(
            Path::new(""),
            vec![
                (PathBuf::from("provider.kio"), lowered_module(&provider)),
                (PathBuf::from("consumer.kio"), lowered_module(&consumer)),
            ],
            None,
        )
        .expect("package");
        let consumer = &package.module("consumer").expect("consumer module").module;
        let provider = &package.module("provider").expect("provider module").module;
        let env = ModuleEnv::build(consumer, None, None, Some(&package)).expect("environment");

        reset_capture_type_owner_item_visits();
        for name in &imported {
            assert_eq!(
                resolve_type_name_owner(name, &env),
                Some(("provider".to_owned(), crate::ast::Visibility::Public))
            );
        }
        assert!(
            capture_type_owner_item_visits() <= provider.items.len(),
            "capture type ownership must consume the exact nominal provider in O(D + K), not search the package for every alias/newtype: {} visits",
            capture_type_owner_item_visits()
        );
    }

    #[test]
    fn package_check_surfaces_module_type_error() {
        use crate::pass::resolve::Package;
        use std::path::{Path, PathBuf};
        // A two-module package where the second module has a
        // body-vs-return mismatch. The package check driver must surface
        // the error, not swallow it into an empty / `Ok` result.
        let ok_mod = lowered_module("module pkg/a; pub fn ok() -> . { () }");
        let bad_mod = lowered_module(
            "module pkg/b; \
             newtype Foo : . { pub constructor mk; pub projector un; }; \
             fn bad() -> Foo { () }",
        );
        let package = Package::build(
            Path::new(""),
            vec![
                (PathBuf::from("pkg/a.kio"), ok_mod),
                (PathBuf::from("pkg/b.kio"), bad_mod),
            ],
            None,
        )
        .unwrap();
        package.resolve_imports().expect("resolve_imports");
        let err = check_package_collect_elaborations(&package)
            .expect_err("package check should surface the module's type error");
        match err.error {
            Error::Type(Diagnostic { message, .. }) => {
                assert!(message.contains("type mismatch"), "got: {message}");
            }
            other => panic!("expected a type error, got {other:?}"),
        }
    }

